-- Guide texts (zhCN) for the shared Polestar_Guides pack
-- (professions, reputations, mounts, pets, dungeons, ...).
-- Includes the official Polestar_zhCN texts (they win) and fills every gap,
-- so the addon stays complete whatever order the addons load in.

local _, E = ...
if not (GetLocale and GetLocale() == "zhCN") then return end
if not E.enabled then return end

local G = E.guides

-- Pack-level texts (folder labels and the pack blurb); the official pack's
-- own copies are merged in at runtime, but they are kept here too so this
-- addon stays complete on its own.
