G["forever/class/druid/aquatic-form"] = {
	["At the {area:2362}"] = "在{area:2362}",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "施放{spell:18960}。两半都在背包里时，站在西北岸的{area:2362}旁，使用{item:15883}将其合成，然后再次施放{spell:18960}（在{zone:1450}内也可使用），传送到{npc:11802}身边。他站在自己建筑的楼上：从室内上楼，箭头无法区分楼层。之后，{area:2361}中央的{npc:11800}可以送德鲁伊直接飞往{area:702}。",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "施放{spell:18960}。两半都在背包里时，站在西北岸的{area:2362}旁，使用{item:15883}将其合成，然后再次施放{spell:18960}（在{zone:1450}内也可使用），传送到{npc:11802}身边。他站在自己建筑的楼上：从室内上楼，箭头无法区分楼层。{npc:11798}可以送德鲁伊飞往{area:1638}。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:28} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。{quest:28}每30分钟计时刷新。{area:2361}下方的{area:656}深处底部有六个饰物容器（花瓶），藏在狭窄的凹坑里，常在冒泡的裂隙附近（湖中央的{object:177524}能补满呼吸）；每个打开后三分钟刷新，其他德鲁伊也会来拿。浮上水面前确认背包里有{item:15877}：拾取后五分钟它就会消失。直接把它游送到西北岸的{area:2362}，在神龛范围内使用，并与树旁的{npc:11799}交谈。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:29} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。{quest:29}每30分钟计时刷新。{area:2361}下方的{area:656}深处底部有六个饰物容器（花瓶），藏在狭窄的凹坑里，常在冒泡的裂隙附近（湖中央的{object:177524}能补满呼吸）；每个打开后三分钟刷新，其他德鲁伊也会来拿。浮上水面前确认背包里有{item:15877}：拾取后五分钟它就会消失。直接把它游送到西北岸的{area:2362}，在神龛范围内使用，并与树旁的{npc:11799}交谈。",
	["Druid"] = "德鲁伊",
	["Fly from {area:2361} to {area:442}. The {object:177792} lies far out on the sea floor off the north coast, between tall rocks west of where the {area:456} reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."] = "从 {area:2361} 飞往 {area:442}。{object:177792} 位于北岸外较远处的海底，在 {area:456} 入海口西侧的高大岩石之间；从岩石东侧看不到它。注意呼吸和黑海岸蛇颈龙；战斗时要回到水面上。",
	["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Head west to the coast: the {object:177790} lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."] = "从{area:442}乘船前往{zone:1453}，再飞往{area:108}。向西去海岸：{object:177790}位于离岸较远的海底，在冒泡的裂隙（可补充空气）旁边、沉没的船锚西面。这里有鲨鱼游荡；不要继续游过更远处的沉船，深水区会使你疲劳。",
	["Take the portal up to {npc:4217} in the {area:1658}. {quest:5061}: swim fast and breathe underwater."] = "使用传送门上去，找 {area:1658} 的 {npc:4217}。{quest:5061}：提高游泳速度，并可在水下呼吸。",
	["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies at the bottom of very deep water off the coast north-west of the {area:228}, beside an air fissure where you can breathe: watch your breath on the way down."] = "乘{npc:11798}的航班到{zone:1456}，飞往{zone:1454}，再乘飞艇到{zone:1420}；{zone:1421}在{zone:1458}以南。{object:177790}在{area:228}西北海岸外的极深水底，紧挨着一处能呼吸的空气裂隙：下潜途中注意呼吸。",
	["The {object:177792} lies underwater in the {area:382} pond north of the Crossroads, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "{object:177792}在十字路口以北{area:382}池塘的水下，一堵木墙前。那里的风险投资公司成员很容易加入战斗：从西边进入以避开大部分。",
	["The {object:177792} lies underwater in the {area:382} pond north of the {area:380}, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "{object:177792}在{area:380}以北{area:382}池塘的水下，一堵木墙前。那里的风险投资公司成员很容易加入战斗：从西边进入以避开大部分。",
	["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "你的水中旅行形态：快速游泳、水下呼吸，另外还有一条腰带和一个神像。",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，来自湖中的{object:177785}",
	["{item:15882}, from the {object:177790}"] = "{item:15882}，来自{object:177790}",
	["{item:15883}, from the {object:177792}"] = "{item:15883}，来自{object:177792}",
	["{item:15885}: join the halves at the shrine"] = "{item:15885}：在神殿合成两半",
	["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033} 站在 {area:1639} 的德鲁伊小屋里。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. Skyborne: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up."] = "{npc:4217} 在 {area:1658} 德鲁伊建筑的楼上。天裔：施放 {spell:18960}，在 {area:2361} 中央搭乘 {npc:11800} 的航班（她会将德鲁伊送到 {area:702}，无需先开通飞行路线），然后使用传送门上去。",
}

G["forever/class/druid/bear-form"] = {
	["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "10级时会收到德鲁伊的召唤：{area:222}的{npc:3064}或{zone:1456}的{npc:6746}（{zone:1454}的{npc:6929}的信也可以）。任何一位都会让你去找{zone:1456}{area:1639}的{npc:3033}。",
	["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "10级时会收到德鲁伊的召唤：{area:186}的{npc:3602}、{zone:1457}的德纳萨里安或{zone:1453}的塞瑞德兰。任何一位都会让你去找达纳苏斯塞纳里奥区的{npc:4217}。",
	["Back to {npc:255853} by the falls."] = "回到瀑布旁的{npc:255853}那里。",
	["Back to {npc:3033} on {area:1639}."] = "回到{area:1639}的{npc:3033}那里。",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here (Faustron for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "施放 {spell:18960}：落点旁的建筑里，{npc:11802} 就在 {area:2361} 的楼上。趁在这里，学会 {area:493} 的飞行路线（部落找湖西南的浮士德；联盟找湖南边的 {npc:10897}）。",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "施放 {spell:18960}：你会来到一栋建筑旁，{npc:11802} 就在楼上，经过护甲商人便能找到。{quest:5929} 位于西北面的树林里。与它交谈，依次听完所有内容（它所代表的意义、身躯的力量、心灵的力量，最后请求它的祝福）：完成交谈即可达成目标，无需战斗。它与地面融为一体，没有任务标记，在三棵树旁散发微弱的蓝灰色光芒：从 {area:2361} 沿北部山脚向西，穿过树木与山丘间的缺口。如果返回时找不到 {npc:11802}，走到室外再施放一次 {spell:18960}。先解锁 {area:493} 的飞行路线（湖泊南面的 {npc:10897}），以便日后使用，再去搭乘 {area:2361} 中部 {npc:11800} 的航班：她会将德鲁伊直接送到 {area:702}，无需解锁飞行路线。随后通过传送门前往上方的 {zone:1457}。",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path (Faustron, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "施放 {spell:18960}：你会来到一栋建筑旁，{npc:11802} 就在楼上。{quest:5930} 位于西北面的树林里。与它交谈，依次听完所有内容（它所代表的意义、身躯的力量、心灵的力量，最后请求它的祝福）：完成交谈即可达成目标，无需战斗。它与地面融为一体，没有任务标记，在三棵树旁散发微弱的蓝灰色光芒：从 {area:2361} 沿北部山脚向西，穿过树木与山丘间的缺口。如果返回时找不到 {npc:11802}，走到室外再施放一次 {spell:18960}。解锁 {quest:5922} 的飞行路线（湖泊西南面的法斯托恩）；{area:2361} 的 {npc:11798} 会将德鲁伊送到 {area:1638}。",
	["Druid"] = "德鲁伊",
	["Fly back to {area:702} and take the portal up to {npc:4217}."] = "飞回{area:702}，乘传送门上去找{npc:4217}。",
	["Fly from {area:702} to {area:442}. The {object:177525} stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the {area:442} road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the {item:15208} by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too."] = "从 {area:702} 飞往 {area:442}。{object:177525} 位于村庄东面最近的枭兽洞穴内：{area:442} 的道路与南北主路交会处有两个小石堆洞穴，目标在北面的那个。洞外有11—13级枭兽，洞内没有敌人：绕过它们进去。在石头旁使用 {item:15208}：月爪枭兽（12—13级）会朝你走来，并停留三分钟。击杀她后，与出现的 {npc:12144} 交谈，请求获得她身躯和心灵的力量：交谈后才会计入进度。击杀其他德鲁伊召唤的月爪枭兽，也能见到这个灵魂。",
	["Skyboat from {area:279}"] = "从{area:279}乘天空飞船",
	["Skyboat from {zone:1456}"] = "从{zone:1456}乘天空飞船",
	["Skyboat to {zone:2521}"] = "乘天空飞船前往{zone:2521}",
	["Speak with the {quest:5929}"] = "与{quest:5929}交谈",
	["Speak with the {quest:5930}"] = "与{quest:5930}交谈",
	["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer (the arrow points at him); he teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "天裔传送门会将你送到{zone:1453}。{npc:5504}是城里的德鲁伊训练师（箭头指向他）；通过下一个任务，他会教你{spell:18960}（学会后会一直保留在法术书的平衡分页中）。",
	["The {object:177525}"] = "{object:177525}",
	["The {object:177525} stands in the {zone:1413} just south-west of {area:378}, by the road out of {zone:1412}. Level 20 Thunderheads roam close by: clear the way first. Use the {item:15710} by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her."] = "{object:177525} 位于 {zone:1413} 的 {area:378} 西南边，靠近离开 {zone:1412} 的道路。附近有 20 级的雷鹰游荡：先清出安全通道。在石头旁使用 {item:15710}：月爪（12-13 级）会出现并停留三分钟。杀死她，然后与出现的 {npc:12144} 交谈，请求获得她身体和心灵的力量：完成对话才算达成目标。如果战斗中死了，月爪会留在石头旁，跑回来把她杀掉即可。",
	["Ur'endra"] = "乌伦德拉",
	["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "你的坦克形态：无限不再由训练师教授{spell:5487}，而是由这些任务给予。同时也会开启{area:493}。",
	["or whichever of the three letters you carry"] = "或你携带的三封信中的任意一封",
	["{npc:252359} stands in {area:16638}."] = "{npc:252359}站在{area:16638}。",
	["{npc:255853} and {npc:258443}"] = "{npc:255853}和{npc:258443}",
	["{npc:255853} waits by the waterfall below the {area:16629}, north-east of {area:16638}. {npc:258443} (the bear you must defeat) lairs in an unmarked cave high on the cliff face west of him, where the {area:16623} meet the {area:16626}: take the path west out of {area:16638} (not north), cross the river on the log bridge and reach the cave from the cliff's upper, northern side. The cave at the foot of the cliffs and the foggy cave are the wrong ones."] = "{npc:255853} 在 {area:16638} 东北方、{area:16629} 下方的瀑布旁等待。{npc:258443}（你必须击败的熊）栖居在他西侧崖壁高处一座未标记的洞穴里，那里是 {area:16623} 与 {area:16626} 的交界处：从 {area:16638} 沿小路向西走（不要向北），经独木桥过河，再从悬崖上方的北侧进入洞穴。崖脚下的洞穴和雾气弥漫的洞穴都不是目标。",
	["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118}在从{zone:2521}来的飞艇降落处等候，位于{zone:1412}北部，{zone:1456}旁边。",
	["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459}站在{npc:259084}和天裔传送门旁，位于{area:279}西边，从{zone:2521}来的天空快船在此降落。{npc:2543}也提供同样的任务。",
	["{npc:3033} stands in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} 站在 {area:1639} 的德鲁伊小屋中，从升降梯东边走过绳桥即可到达。接到任务时，他会教你 {spell:18960}（会保留在法术书的平衡分类中）。",
	["{npc:3033} trains druids in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} 在 {area:1639} 的德鲁伊小屋内训练德鲁伊，穿过升降梯东侧的绳桥便能到达。他会在下一个任务中教你 {spell:18960}（学会后会一直保留在法术书的平衡分页中）。",
	["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}，{area:222}；帕拉和格雷什卡的信也指向同一个地方",
	["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}，{area:186}；德纳萨里安和塞瑞德兰的信也指向同一个地方",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:4217}站在{area:1658}德鲁伊建筑的楼上。他会在任务中教你{spell:18960}（会保留在法术书的平衡页中）。",
	["{spell:5487} and {area:493}"] = "{spell:5487}和{area:493}",
	["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487}在{zone:2521}教授。如果你还在岛上就跳过这一步；否则从{area:17045}南边的悬崖乘天空飞船，就在{zone:1456}北边。",
	["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487}在{zone:2521}教授。如果你还在岛上就跳过这一步；否则从{area:279}北侧乘天空飞船。",
}

G["forever/class/druid/bloodpetal-poison"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. {area:1477} stands in the middle of the {area:74} in the {zone:1435}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. {npc:8580} (level 50 elite, {spell:12887} and {spell:6524}) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The {item:22444} always drops."] = "这是五人地下城，需要一支约50—55级的五人小队。部落：飞往 {area:75}；联盟：飞往 {zone:1419} 的 {area:1438}，再骑乘北上。{area:1477} 位于 {zone:1435} 的 {area:74} 中央：从废墟南侧上楼梯，潜入被水淹没的大厅，穿过大厅继续下潜，再沿楼梯和通道向下走到传送门。{npc:8580}（50级精英，会使用 {spell:12887} 和 {spell:6524}）只会在按顺序点击祭坛深坑上方环形露台上的六座蛇雕像后出现：南、北、西南、东南、西北、东北（顺序正确时雕像会变绿；顺序错误则失败）。先清掉每座雕像旁和下方深坑中的小怪；跳进水里是最快的下行方式，但在边缘附近被击退可能致命。{item:22444} 必定掉落。",
	["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "回到{zone:1449}东南角找{npc:9619}。",
	["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "施放 {spell:18960}。{npc:12042} 站在 {area:2361}；你的职业训练师（{npc:3033}、{npc:4217}，或 {zone:1453} 的塞瑞德兰）也提供同一个任务。",
	["Devilsaur"] = "魔暴龙",
	["Druid"] = "德鲁伊",
	["Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the {area:540}, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' {spell:8137} makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around {area:541} and the western half): open them, about every other one gives a {item:22434}, back in three to five minutes."] = "两种各需八份。格里什异种蝎和 格里什毒刺蝎（51—52级）分布在环形山西南部的虫巢 {area:540} 内外，毒刺的掉率约为七分之一；这些异种蝎与其他虫类共用刷新点，因此把附近的虫子都杀掉，为更多异种蝎腾出刷新位置（五分钟刷新）。虫子的 {spell:8137} 会使你受到更多物理伤害，持续30分钟；工虫受伤时会呼叫援兵。血瓣花苗遍布环形山（{area:541} 周边和西半部）：打开后约有一半概率获得 {item:22434}，三至五分钟后重新刷新。",
	["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "50级时在安戈洛环形山获得经验和两瓶治疗药水；无限中可能已移除经典版的物品选择。",
	["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "飞往{area:976}，向西骑到通往{zone:1449}的长坡：{npc:9619}在坡底扎营，位于环形山东南角。",
	["Gorishi Stings and {item:22434}"] = "格里什钉刺和{item:22434}",
	["The {area:1417}"] = "{area:1417}",
	["Use the {item:22432} on a living {npc:6498} (an Ironhide or {npc:6500}, or {npc:6584}, counts too): they are elite (level 54-55), hit with {spell:14099} and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or {spell:339} it from range, stab it (the barb does not break {spell:2637}), then leave. The credit counts the moment the barb lands, even if you die after. The nearest roams south-west of {area:541}."] = "对一头活着的{npc:6498}（铁皮魔暴龙，或{npc:6500}；{npc:6584}也算）使用{item:22432}：它们是54到55级精英，会用{spell:14099}，而且比旅行形态跑得快。建议组队，但德鲁伊也能单干：在远处用休眠或{spell:339}控制它，再刺入（刺不会打破{spell:2637}），然后离开。刺入的瞬间就算完成，哪怕你随后死亡。最近的一头在{area:541}西南游荡。",
	["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}：用{item:22432}刺它",
	["{npc:9619}: the old item choice may be gone, count on the experience"] = "{npc:9619}：原来的物品奖励选项可能已移除，按只有经验奖励来打算。",
}

G["forever/class/druid/cat-form"] = {
	["Back to {npc:11802}"] = "回到{npc:11802}处",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}，落在{area:2361}的{npc:11802}附近（泽弗拉斯岛上没有人接天裔的任务），然后乘{npc:11798}的飞行前往{area:1638}。{npc:11802}在他那栋建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}，落在{area:2361}的{npc:11802}附近（泽弗拉斯岛上没有人接天裔的任务），然后乘{npc:11800}的飞行前往{area:702}：她站在{area:2361}中央，可以送德鲁伊飞过去，不需要飞行路线。{npc:11802}在他那栋建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。{npc:11802}在{area:2361}他那栋建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "施放{spell:18960}。{npc:11802}在{area:2361}他那栋建筑的楼上：从室内上楼，箭头无法区分楼层。如果还没有那里的飞行路线，顺便学会。",
	["Druid"] = "德鲁伊",
	["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "通过传送门上去，在{area:1658}楼上找{npc:4217}：他会教你{spell:768}。",
	["The relics of the Barrow Dens"] = "兽穴的圣物",
	["The {area:2363}"] = "{area:2363}",
	["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "你的潜行与近战形态：在无限中，{spell:768}在20级由这条任务线给予，而不是训练师。",
	["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{area:1639}的{npc:3033}会教你{spell:768}。",
	["{npc:3033} stands in the druids' hut on {area:1639}. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:3033}站在{area:1639}的德鲁伊小屋内。还没学会水栖形态？也从他那里接受“必修的课程”：同样是去找{npc:11802}，后续的“湖中试炼”（水栖形态指南）也在同一个{area:493}。",
	["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:4217} 站在 {area:1658}。天裔角色若离 {zone:1457} 很远：施放 {spell:18960}，搭乘 {area:2361} 中部 {npc:11800} 的航班（她会将德鲁伊送到 {area:702}，无需解锁飞行路线），然后通过传送门上去。还没有水栖形态？也向他接受“必修的课程”：这个任务同样要找 {npc:11802}，后续的“湖中试炼”（见水栖形态指南）也在同一个 {area:493} 完成。",
	["{quest:98342} (Tauren) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98342}（牛头人）位于 {area:493} 南部桥上方的山坡上；{npc:272054}（天裔）在 {area:2361} 西南、越过两座桥后的高地上，需要爬上去。遗物在湖东的 {area:2363}：先解除变形，点击洞口的雕像，获得持续五分钟的短暂潜行，然后深入洞穴并过桥。愤怒的精魂守着遗物，会攻击视野内的一切：保持雕像给予的潜行，持续前进。每件遗物都是壁龛中猫形雕像旁的小光球：利牙和 利爪 各有一个刷新点，静影圣物 有两个，也是玩家常蹲守的那件。其他玩家拾取时，遗物会显示无法使用：稍等片刻再试。如果潜行消失，回到洞口雕像处重新获取。",
	["{quest:98394} (Night Elves) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98394}（暗夜精灵）在 {area:493} 南部桥上方的山丘上等你；{npc:272054}（天裔）站在双桥另一侧的高地，位于 {area:2361} 西南方：需要爬上去。遗物位于湖东侧的 {area:2363}：先解除形态，点击洞穴入口的雕像，获得持续五分钟的短暂潜行，然后深入洞穴并过桥。愤怒的灵魂守卫着遗物，会攻击看到的任何目标：保持雕像给予的潜行，不要停留。每件遗物都是壁龛中猫雕像旁的小球：獠牙和利爪各有一个刷新点，静影圣物 有两个刷新点，而且玩家通常会蹲守它。其他玩家正在拾取遗物时，它会显示为无法使用：稍等片刻再试。潜行消失了？走回入口雕像处重新获取。",
}

G["forever/class/druid/cure-poison"] = {
	["Back in {area:442}, at the north end of the village."] = "回到{area:442}，在村庄北端。",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}并找{npc:11802}，然后乘{npc:11798}的飞行坐骑前往{area:1638}。{npc:11802}站在他所在建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}并找{npc:11802}，然后在{area:2361}中央乘{npc:11800}的飞行坐骑（她会载德鲁伊飞往{area:702}，无需飞行路线），再乘传送门上到{zone:1457}。{npc:11802}站在他所在建筑的楼上：从室内上楼，箭头无法区分楼层。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "施放{spell:18960}：{npc:11802}就在你身旁建筑的楼上。他会给你{item:15842}。{npc:11798}会将德鲁伊送到{area:1638}；从那里继续飞往十字路口。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "施放{spell:18960}：{npc:11802}就在你旁边那栋楼的楼上。他会给你{item:15842}。{npc:11798}会把德鲁伊送到{area:1638}；从那里再飞往{area:380}。",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "施放 {spell:18960}：{npc:11802} 就在你旁边建筑的楼上。他会给你 {item:15844}。然后飞往 {area:442}（如果还没学会 {zone:1450} 的飞行路线，先找辛德拉尔学习）。",
	["Druid"] = "德鲁伊",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the Crossroads. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "每只{npc:3234}（14-15级）都会掉落一只角，但数量少且四处游荡：搜索最北面的{area:382}及各绿洲附近，尤其是十字路口东南方的{area:388}。它们会从远处冲锋并践踏。草药师可在{zone:1413}北部各处找到{item:2449}。",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the {area:380}. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "每只{npc:3234}（14-15级）都会掉一只角，但它们数量稀少且四处游荡：到{area:382}附近的极北地带和各处绿洲寻找，尤其是{area:380}东南的{area:388}。它们会远程冲锋并践踏。草药师能在{zone:1413}北部各处采到{item:2449}。",
	["From the Crossroads head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "从十字路口向北前往{area:384}，爬到山顶冒泡的{object:19464}。周围有火刃教徒扎营：每次引一两个来打。站到水里使用{item:15842}：会出现三名火刃毒药师（13-14级，会施放诅咒和术士法术）并攻击你。不必击杀他们：采样器装满后就跑。",
	["From the {area:380} head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "从{area:380}向北到{area:384}，爬上山顶冒泡的{object:19464}。燃烧之刃教徒在周围扎营：一次拉一两个。站在水里使用{item:15842}：三个燃烧之刃毒理学家（13-14级，会诅咒和术士法术）出现并攻击。不必杀掉他们：采样器一满就跑。",
	["He hands you the {item:15826}: ten doses, one per gazelle."] = "他会给你{item:15826}：共10剂，每只瞪羚用一剂。",
	["Head north-east from {area:442} to {area:445}. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the {item:15844} (not the {item:12350} of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight."] = "从 {area:442} 向东北前往 {area:445}。站在瀑布顶部的洞口，而非下方的河里，使用 {item:15844}（别用另一个任务的 {item:12350}）。上坡沿途都有纳迦，对岸有一名施法者，装满取样器还会召来两个敌人（一名踏浪者和一名毒性学家，15级）：先清路，并做好战斗准备。",
	["She hands you the {item:15826}: ten doses, one per deer. Destroy any leftover {item:15851}."] = "她会给你 {item:15826}：共十剂，每只鹿用一剂。销毁剩余的 {item:15851}。",
	["Sickly Deer"] = "病弱鹿",
	["Sickly Gazelle"] = "病弱的瞪羚",
	["Sickly Gazelles"] = "生病的瞪羚",
	["The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of {area:442}; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No {skill:182} needed for the blooms. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it ({npc:1313} or {npc:1302} in {zone:1453}, or the Auction House)."] = "月光蘑菇花是带白色斑点的小蘑菇，长在 {area:442} 正东及东南方山丘中小型枭兽洞穴的地面和洞壁上；每处可采到一两个蘑菇，每个洞穴只有几处，因此需要逐个洞穴寻找（三分钟刷新）。那里的枭兽脾气暴躁。采集蘑菇花不需要 {skill:182}。{item:2449} 则需要 {skill:182}：草药师可以在 {zone:1439} 各处采集，其他人需购买（可找 {zone:1453} 的 {npc:1313} 或 {npc:1302}，或在拍卖行购买）。",
	["Use the {item:15826} on Sickly Gazelles"] = "对生病的瞪羚使用{item:15826}",
	["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the {zone:1440} border, north-west of the Crossroads and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "对活着的生病的瞪羚（3级）使用{item:15826}：它们在十字路口以北、直到{zone:1440}交界处的道路两侧，以及十字路口西北方和{area:392}西侧吃草。德鲁伊技巧：先用{spell:339}缠住瞪羚，在缠绕造成伤害前涂上药膏；随后缠绕击杀它时还会再计数一次，因此五只瞪羚就可能够了。浪费了一剂？放弃任务，再从{npc:3448}处重接，即可获得新的药膏。",
	["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the {area:380} up to the {zone:1440} border, north-west of the {area:380} and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "对活着的病弱瞪羚（3级）使用{item:15826}：它们在{area:380}以北、直到{zone:1440}边界的道路两侧吃草，也在{area:380}西北和{area:392}以西活动。德鲁伊小技巧：用{spell:339}缠住一只瞪羚，在缠绕生效前涂上药膏，缠绕造成的击杀会再计一次，所以五只瞪羚就够。浪费了一剂？放弃任务，从{npc:3448}重新接取，就能拿到新的药膏。",
	["Use the {item:15826} on living {npc:12298} (level 5, a green cloud over them): they roam {zone:1439} from the {area:456} to the {zone:1440} border, many around the Blackwood furbolg camp north-east of {area:442}. Druid trick: root a deer with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from {npc:3702} for a fresh salve."] = "对活着的 {npc:12298} 使用 {item:15826}（5级，身上有绿色云雾）：它们在 {zone:1439} 的 {area:456} 到 {zone:1440} 边界之间游荡，{area:442} 东北方的黑木熊怪营地周围尤其多。德鲁伊技巧：用 {spell:339} 缠住一只鹿，在缠绕伤害生效前涂上药膏，之后缠绕将其击杀时还会再计数一次。如果药膏用在一只鹿上却没计数，浪费了一次剂量，可以放弃任务，再从 {npc:3702} 处重接以获得一份新药膏。",
	["Use the {item:15826} on {npc:12298}"] = "对{npc:12298}使用{item:15826}",
	["{item:15842}, standing in the pool"] = "站在水池中使用 {item:15842}",
	["{item:15844}, at the cave mouth"] = "{item:15844}，在洞口",
	["{item:15851} and {item:2449}"] = "{item:15851}和{item:2449}",
	["{item:2449} and Kodo Horns"] = "{item:2449}和科多兽角",
	["{item:2449}; herbalists pick it on the plains"] = "{item:2449}；草药师可在平原上采集",
	["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{area:1639}的{npc:3033}会教你{spell:8946}。",
	["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the Crossroads sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033}在{area:1639}的德鲁伊小屋中；{zone:1412}北部、来自泽风岛的飞艇停靠处，天裔德鲁伊训练师{npc:262560}也提供同一任务。没有{skill:182}？稍后可在十字路口向{npc:3490}购买{item:2449}，也可以现在就在拍卖行买五个。",
	["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the {area:380} sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033}站在{area:1639}的德鲁伊小屋中；{npc:262560}是泽弗拉斯岛飞艇在{zone:1412}北部降落处的天裔德鲁伊训练师，也会给同样的任务。没有{skill:182}？{area:380}的{npc:3490}以后会卖{item:2449}，或者现在就在拍卖行买五个。",
	["{npc:3033}, or {npc:262560} in northern {zone:1412}"] = "{npc:3033}，或 {zone:1412} 北部的 {npc:262560}。",
	["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448}站在十字路口。没有{skill:182}？几步之外、双足飞龙管理员旁的{npc:3490}出售{item:2449}，每个80铜币，每次补货前有三个存货。",
	["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448}站在{area:380}。没有{skill:182}？几步之外、驭风者训练师旁的{npc:3490}以每朵80铜出售{item:2449}，每次限购三个，直到他补货。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} 站在 {area:1658} 德鲁伊建筑的楼上。没有 {skill:182}？先去拍卖行买五份 {item:2449}，后面会用到。",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}; {npc:270459} by the Skyborne Portal does not give this quest. Cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217}站在{area:1658}德鲁伊建筑的楼上；天裔传送门旁的{npc:270459}不提供这个任务。施放{spell:18960}，到{area:2361}中央搭乘{npc:11800}提供的航班（她会把德鲁伊送到{area:702}，无需开通飞行路线），然后通过传送门上去。没有{skill:182}？先在拍卖行买五个{item:2449}：后面会用到。",
	["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{npc:4217} 在 {area:1658} 楼上，可教你 {spell:8946}。",
	["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "无限中训练师不再教授{spell:8946}：这条任务线会教你，途中还会获得一个药袋。",
}

G["forever/class/hunter/rhokdelar"] = {
	["Back to the Ancients"] = "回到古树处",
	["Before the demons"] = "对付恶魔之前",
	["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "古树哈斯塔特的箭袋需要 {item:18704}。{npc:6109} 是需要团队挑战的世界首领，位于 {zone:1447} 南部，每两到四天才刷新一次，几乎每次击杀都会掉落。在 {zone:1452} 的 {area:2255} 南边洞穴 {area:2245} 内外，精英深蓝龙人约每 200 次击杀掉落一件；那里的魔法利爪掉率稍高。如果不想要箭袋，就跳过本指南的剩余部分。",
	["Hunter"] = "猎人",
	["Learn {spell:19878} and get demon-slaying potions"] = "学习 {spell:19878}，并准备屠魔药剂。",
	["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "尚未在无限确认。在经典怀旧服中，背包里带着 {item:18724} 使用 {item:18707} 可以制成伦鲁迪洛尔，之后再与瓦特鲁斯交谈一次，就能免费获得 {item:18715}。",
	["Onyxia"] = "奥妮克希亚",
	["Onyxia is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. She drops one {item:18705} in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first."] = "奥妮克希亚是 {area:2159} 的 40 人团队首领，巢穴入口位于 {zone:1445} 南部的 {area:511}，每周刷新一次。她大约每五次击杀有两次掉落一件 {item:18705}，没有任务也能拾取，因此每次击杀最多只有一名猎人拿到：提前商量好分配顺序。",
	["Rhok'delar and Lok'delar"] = "伦鲁迪洛尔和罗克迪洛尔",
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring an Elixir of Demonslaying ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "这四个恶魔是60级精英，伪装成友善的旅行者；与其中一个交谈并表明你知道它是什么，它就会变回恶魔形态。每一场都必须单挑：不带宠物（解散它），战斗开始后不能有其他玩家的治疗、增益或攻击，否则恶魔会骂你懦夫并消失，要等3小时才会回来（它死亡后同样如此）。开怪前加的增益和使用药水没问题，朋友也可以在场边帮你清理游荡的怪物或敌对玩家，只要他们不碰恶魔、也不碰你。带上一个屠魔药水（{skill:171}制作或在拍卖行购买）、用于长时间风筝的强效法力药水，以及一把附有屠魔的武器（如果可以）。训练师处学到的{spell:19878}能在小地图上显示伪装的恶魔。组队时把拾取方式设为自由拾取，这样你才能拾取头颅。",
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring an {item:9224} ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "这四个恶魔是60级精英，伪装成友善的旅行者；与其中一个交谈并表明你知道它是什么，它就会变回恶魔形态。每一场都必须单挑：不带宠物（解散它），战斗开始后不能有其他玩家的治疗、增益或攻击，否则恶魔会骂你懦夫并消失，要等3小时才会回来（它死亡后同样如此）。开怪前加的增益和使用药水没问题，朋友也可以在场边帮你清理游荡的怪物或敌对玩家，只要他们不碰恶魔、也不碰你。带上一个{item:9224}（{skill:171}制作或在拍卖行购买）、用于长时间风筝的强效法力药水，以及一把附有屠魔的武器（如果可以）。训练师处学到的{spell:19878}能在小地图上显示伪装的恶魔。组队时把拾取方式设为自由拾取，这样你才能拾取头颅。",
	["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "猎人史诗弓任务线：在经典版中，手杖和肌腱会变成伦鲁迪洛尔和罗克迪洛尔（无限中未确认）。",
	["The {item:18703}"] = "{item:18703}",
	["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "古树瓦特鲁斯、古树斯托玛和{npc:14526}是{zone:1448}北部{area:1767}一处环形湖中央小岛上的石化树木。只有携带叶子的人登上岛上小丘的东缘时，他们的灵魂才会出现。联盟：飞往{area:1998}；部落：飞往{area:1997}。古树瓦特鲁斯提供{quest:7636}，古树斯托玛提供“合适的弓弦”，古树哈斯塔特提供箭袋任务；每个任务都可以单独交还。",
	["from the {item:18703}"] = "来自{item:18703}",
	["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717} 是位于 {area:254} 内的40人团队副本。{npc:12018} 投降后会出现 {object:179703}；其中约有一半概率开出 {item:18703}，每次击败首领最多一片，因此可能要打好几周。右键点击叶子开始任务。",
	["{item:18704}, from {npc:6109}"] = "{item:18704}，来自{npc:6109}",
	["{item:18705}, from Onyxia"] = "{item:18705}，来自奥妮克希亚",
	["{item:18707}, by Vartrus"] = "{item:18707}，在古树瓦特鲁斯旁",
	["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}：经典版中的罗克迪洛尔",
	["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}：箭袋，本指南最后一步",
	["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}是带着狼的巨魔，她的巡逻路线很长，从安戈洛西部的湖泊出发，最远可到环形山南部；使用{spell:19878}追踪。与她交谈后，她会变成{npc:14533}，她的狼普莱瑟斯则变成地狱猎犬。这是四场挑战中最难的一场：用冰冻陷阱困住普莱瑟斯，把平凡的西蒙妮引到远处；或者将普莱瑟斯风筝拉远后先击杀，再让平凡的西蒙妮脱战重置，回来单独对付她。她的{spell:421}伤害很高，用{spell:3034}耗光她的法力值（无限中冷却时间为15秒），持续牵制她；她的{spell:23205}会降低你的远程攻击强度，因此最后用近战解决她。在普莱瑟斯挣脱前拾取她的头颅。",
	["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529} 是一名人类，在 {zone:1428} 西部、{area:254} 南侧游荡。与他交谈后，他会变成 {npc:14534}，是四只恶魔中最容易的一只。全程保持他身上的 {spell:3043}：效果持续期间，他对你的伤害很低。他进入 {spell:23257} 状态时，用 {spell:19801} 驱散；该状态仍在时绝不要进入近战范围。两次狂暴之间可以用 {spell:2974} 和 {spell:2973} 与他近战。他无法离开 {zone:1428}，必要时可绕着树木风筝他。",
	["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531} 是一名牛头人，在 {zone:1452} 北部、{area:2255} 以北的岩石间循环巡逻。与他交谈后，他会变成 {npc:14535}。在他 30 码以内，{spell:23298} 会造成很高的伤害：全程拉开距离，开启 {spell:5118}，沿道路向南风筝。他身上的 {spell:1978} 会附加 {spell:23299}，造成额外自然伤害，因此跑动时要保持它持续生效；可以用 {spell:19801} 驱除他的 {spell:23257}，但保持距离更重要。这场战斗很漫长：带上法力药水，并提前规划风筝路线。",
	["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {object:164639}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536} 是个侏儒，在 {zone:1451} 最西南方的 {area:3428} 大门附近走动。与他交谈，他会变成 {npc:14530}。变身时他会施放 {spell:23272} 进入狂暴：放下一个 {object:164639}，再用 {spell:5384}，即可让他重置并消除狂暴。{spell:2974} 能长时间将他定身；被定身时，他会恐惧你并召来甲虫（{npc:14761}）：用陷阱和 {spell:2643} 迅速消灭它们，以免被持续消耗。",
}

G["forever/class/hunter/the-hunters-charm"] = {
	["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "50级时任何联盟猎人训练师都会提供此任务：{zone:1453}{object:28027}的{npc:5516}、{zone:1455}{object:32390}的{npc:5116}，或{zone:1457}塞纳里奥区的多利安。",
	["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "50级时任何部落猎人训练师都提供此任务：{zone:1454}{object:172958}的{npc:3352}，或{zone:1456}{area:1641}上的{npc:3039}。",
	["Experience"] = "经验",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "50级时在{zone:1447}和{area:1417}获得经验；无限上可能已没有经典版的物品选择。",
	["Hunter"] = "猎人",
	["In Classic Ogtinc let you choose the {item:19991}, the {item:19992} or the {item:20083} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "在经典怀旧服中，奥汀克会让你在 {item:19991}、{item:19992} 和 {item:20083} 之间选择一件。无限的更新说明称这项选择已取消，但其任务页面仍列出三件未命名的奖励：交还前先查看奖励窗口。",
	["Morphaz in the {area:1417}"] = "{area:1417}中的摩弗拉斯",
	["Morphaz is an elite green drake (level 52) inside the {area:1417}, a five-player dungeon: needs a group of five. The temple stands in the {area:74} in eastern {zone:1435}: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} or {area:42} and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses {spell:12533} and {spell:11019}. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls."] = "摩弗拉斯是 {area:1417} 内的一只精英绿龙（52级），该地下城为五人地下城：需要五人小队。神庙位于 {zone:1435} 东部的 {area:74}：登上外围台阶，潜入积水大厅，再沿楼梯下到入口。部落：飞往 {area:75}；联盟：飞往 {area:1438} 或 {area:42}，再骑马前往。刚进去时他还没出现：先击杀上层环廊各平台上的六名巨魔守护者，才会打开下行通道，通向祭祀大坑中的 {npc:5710}。迦玛兰死后会出现两只绿龙，德拉维沃尔和德姆塞卡尔（逐只引出）；两只都死后，摩弗拉斯和哈扎斯会一起出现，无法分开。先清理池子周围的龙人，因为它们会呼救。摩弗拉斯会使用 {spell:12533} 和 {spell:11019}。牙齿必定掉落。队里的战士可能也需要来这一趟，收集看台上巨魔掉落的巫毒羽毛。",
	["You need six {item:20087}. Wavethrashers (three-headed sea beasts) live along {zone:1447}'s coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the {area:1229} about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. {spell:1494} does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water."] = "你需要六片 {item:20087}。碎浪多头怪是三头海兽，生活在 {zone:1447} 的沿海，多数在水下：东北海岸的幼年碎浪多头怪（51—52级）约三只掉一片鳞片；东海岸 {area:1229} 附近的碎浪多头怪（52—53级）掉率差不多（那里也有少数在沙滩上行走）；东南海岸的大型碎浪多头怪（53—54级）掉率约为七分之一。{spell:1494} 不会显示它们；在能呼吸的位置战斗，条件允许时带上水下呼吸手段。深水区有精英鲨鱼。",
	["You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over {zone:1447} and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the {area:1220} in the north, and the hills north-east and south-east of {area:1237}; the {area:1234} area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes."] = "你需要两个完美的鹿角。苔蹄快步者（52-53级，鹿）在{zone:1447}各处吃草，掉率约为十二只出一个，预计要击杀二十四只。较好的鹿群位置：北部{area:1220}以北，以及{area:1237}东北和东南的山丘；{area:1234}一带还有精英巨人和龙类。它们在生命值降至30%时会激怒。苔蹄快步者与电角蜥蜴角鹰兽共用刷新点：如果没有鹿，就杀掉角鹰兽，之后可能会刷出鹿。刷新时间约为五分半钟。",
	["{item:20017}, from Mosshoof Coursers"] = "{item:20017}，由苔蹄快步者掉落",
	["{item:20019}, inside the {area:1417}"] = "{item:20019}，在{area:1417}内",
	["{npc:8405} lives on a raised spot on the cliffs at the north-east rim of the {area:1221}, west-central {zone:1447}. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to {area:3137}; Horde: fly to {area:1237}, a short ride west of him."] = "{npc:8405} 住在 {zone:1447} 中西部、{area:1221} 东北边缘的崖顶高地上。沿遗迹周围的高处山脊走：下面的坑里没有通往他的路。联盟：飞到 {area:3137}；部落：飞到他西边不远的 {area:1237}。",
	["{quest:8151} (Alliance)"] = "{quest:8151}（联盟）",
	["{quest:8151} (Horde)"] = "{quest:8151}（部落）",
}

G["forever/class/mage/arcane-refreshment"] = {
	["Back to Lydros"] = "回到莱德罗斯处",
	["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a {item:18249} (it drops from the imp Pusillin in the East wing; a {item:18594} also opens them; Blink no longer gets past). Other mages in your group can take it too: share it."] = "联盟飞往羽月要塞，部落飞往{area:1099}，再骑行前往{zone:1444}中部的{area:2577}。{npc:14368}在图书馆等候，可从西区抵达，或使用{item:18249}打开北区庭院的门进入。钥匙由东区小鬼普希林掉落，{item:18594}也能开门；现在已无法用闪现穿过去。小队里的其他法师也能接取，记得共享任务。",
	["Hydrospawn"] = "海多斯博恩",
	["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "海多斯帕恩是一只57级精英水元素，住在扭木区（厄运之槌东区）：追赶小鬼普希林直到它转身战斗，清掉萨特房间，然后沿螺旋坡道下到水池。五人小队。冰霜法术对他无效，所以冰法改用火焰或奥术。{area:1758}会伤害10码内的所有人，远程要站远；血量降到四分之一时他会召唤小水元素。精华必掉；副本重置前他不会刷新。",
	["Mage"] = "法师",
	["Shen'dralar reputation"] = "辛德拉声望",
	["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "60级的{spell:10140}，来自{area:2577}的图书馆：为你和小队提供饮料。",
	["{item:18299}: Hydrospawn"] = "{item:18299}：海多斯博恩",
	["{npc:14368}: {spell:10140}, and 200 Shen'dralar reputation"] = "{npc:14368}：学习{spell:10140}，并获得 200 点辛德拉声望",
}

G["forever/class/mage/atiesh"] = {
	["Atiesh"] = "埃提耶什",
	["Back to {npc:15192}"] = "返回{npc:15192}",
	["Back to {npc:15192} at the {area:2300}."] = "返回{area:2300}的{npc:15192}处。",
	["Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the {area:2277} in {zone:1423}: each of its twelve bosses before Sapphiron and {npc:15990}, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack."] = "需要在纳克萨玛斯收集四十块埃提耶什的碎片。这座 40 人团队副本位于{zone:1423}的{area:2277}上空。萨菲隆和{npc:15990}之前的十二名首领，以及天启四骑士的箱子，各有约三分之一几率掉落一块，由团队分配。通常需要连续多周通关。将所有碎片放在同一叠中。",
	["Raid"] = "团队副本",
	["Right-click the {quest:9250} to start the quest, then take it to {npc:15192}, the bronze dragon in elf form who stands outside the {area:2300} in eastern {zone:1446}. Fly to {area:976} and ride east."] = "右键点击{quest:9250}开始任务，再将它带给{zone:1446}东部{area:2300}外的{npc:15192}；他是以精灵形态出现的青铜龙。飞往{area:976}，再向东骑行。",
	["Splinters of Atiesh"] = "埃提耶什的碎片",
	["Take the befouled staff to {area:2279}, the dungeon at the north end of {zone:1423}, through the main gate. On {object:175433} find the patch of {object:181206} with a small white flame on it, stand on it and use the staff: {npc:16387}, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his {spell:17466} hurts everyone and cannot be dispelled (shadow resistance helps), his {spell:28342} curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup."] = "将被玷污的法杖带到{zone:1423}北端的副本{area:2279}，从正门进入。在{object:175433}找到一块冒着白色小火苗的{object:181206}，站上去使用法杖，63 级首领萨格拉斯之手{npc:16387}就会出现。请组建实力足够的小队：它的{spell:17466}会伤害所有人且无法驱散，暗影抗性有帮助；{spell:28342}诅咒必须立即解除。战士缴械会使它掉落武器，近战玩家可拾取并用于攻击它。首领最多停留两个半小时，有时间重新组织队伍。",
	["The Greatstaff"] = "守护者的传说之杖",
	["The Staff Head and the Base"] = "杖头与杖柄末端",
	["The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in {area:2279}."] = "守护者的传说法杖：来自纳克萨玛斯的四十块碎片、两个团队首领，以及{area:2279}中的一个恶魔。",
	["Two more raid bosses, a full 40-player raid each, both pieces always drop: the {item:22733} from {npc:15990} on his throne at the top of Naxxramas, the {item:22734} from {npc:15727} at the bottom of the {area:16076}, behind the {area:3478} in southern {zone:1451}. Each boss comes back once a week."] = "还需击败两名团队首领，均需要完整的 40 人团队，两件任务物品必定掉落。{item:22733}来自纳克萨玛斯顶层王座上的{npc:15990}，{item:22734}来自{zone:1451}南部{area:3478}后方、{area:16076}底层的{npc:15727}。两名首领均每周刷新。",
	["the befouled staff, on the {object:181206} inside {area:2279}"] = "在{area:2279}内的{object:181206}处使用被玷污的法杖",
	["your class's {npc:16387} quest; he hands you the befouled staff"] = "接取本职业的{npc:16387}任务，他会交给你被玷污的法杖",
	["{item:22733}: {npc:15990}, Naxxramas"] = "{item:22733}：纳克萨玛斯的{npc:15990}",
	["{item:22734}: {npc:15727}, {area:16076}, past the {object:176146}"] = "{item:22734}：越过{object:176146}，前往{area:16076}的{npc:15727}",
	["{npc:16387}, Hand of Sargeras"] = "{npc:16387}，萨格拉斯之手",
	["{spell:28324}: forty splinters become the {quest:9250}"] = "{spell:28324}：将四十块碎片合成{quest:9250}",
}

G["forever/class/mage/celestial-orb"] = {
	["An off-hand orb or a staff for the late 30s, your pick."] = "30多级后期可选一个副手宝珠或一根法杖，任你选择。",
	["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. She is one of the bosses by the sacred pool, and the tiara always drops. The reward window shows the {item:9527} and the {item:9531}."] = "40 级时，指引你去{npc:6546}处的法师训练师（{npc:5497}、彬克、{npc:4568}、{npc:5885}）还会提供所有职业都能完成的{quest:2861}。随后{npc:6546}需要从{area:978}的 46 级精英纳迦{npc:7795}身上取得{quest:2846}。副本位于{zone:1446}西北部，建议五人、44–54 级。她是圣池旁的首领之一，皇冠必定掉落。奖励窗口显示{item:9527}和{item:9531}。",
	["Back at {npc:6546}'s. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "返回{npc:6546}处，先清理小屋周围的小动物，它们也会加入战斗。接取{quest:1955}即开始三分钟倒计时，{npc:6546}会在花园召唤{npc:6549}。它是 40 级精英，对许多法术、定身和减速有较强抗性。建议组队，40 级法师可能需要帮手或药水，约 45 级时可单人完成。可以从码头远程拉怪。击杀后倒计时仍继续，务必立刻交任务。超时则放弃后重新接取，她会再次召唤恶魔。",
	["Back to {npc:6546}. Accepting {quest:1957} opens a rift beside her cottage and starts a 10 minute timer: twelve {quest:1957} (level 40, Shock and {spell:403}) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out."] = "返回{npc:6546}处。接取{quest:1957}会在小屋旁打开裂隙，并开始十分钟倒计时。十二只 40 级的{quest:1957}会以每波约四只的方式出现，使用震击和{spell:403}。攻击一只不会引到其他。站在场地边缘会引到全部敌人；西南侧的树位于它们攻击范围外，但仍在你的施法距离内。击杀十二只，并在倒计时结束前交任务。",
	["Demon of the Orb"] = "宝珠中的恶魔",
	["Mage"] = "法师",
	["Mana Surge"] = "法力涌动",
	["The Burning Blade Summoners (level 38-39, not elite) work the {area:602} in southern {zone:1443}, east of {area:2408}, and every one carries an {item:7291}. They cast {spell:686} from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western {zone:1412}, south-west of {zone:1456}."] = "38–39 级非精英火刃召唤师分布于{zone:1443}南部、{area:2408}以东的{area:602}，每名都携带一个{item:7291}。他们会在 40 码外施放{spell:686}，身旁带着小鬼，低血量时逃跑求援；旁边柱廊废墟还有地狱魔女巡逻，谨慎拉怪。部落法师还可在{zone:1412}西部、{zone:1456}西南侧找到一名单独的召唤师。",
	["{area:1517} is a dungeon in the northern {zone:1418}: a group of five. Go in by the rear entrance, a cave in {area:1898} south-east of the main entrance (elite dragons fly nearby): the {npc:7023} (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an {npc:7209}, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back."] = "{area:1517}是{zone:1418}北部的五人副本。从主入口东南侧{area:1898}的洞穴后门进入，附近有精英龙飞行。42 级精英{npc:7023}就在第一扇门后。它在 80%、60%、40% 和 20% 生命值时各分裂出一只同为精英的{npc:7209}。碎片存活时，两者都会反射指向性法术，改用范围法术和魔杖。单人技巧：每次碎片出现，都从旁边副本边界走出去；哨兵会回血，但体型会继续缩小。能量源必掉，首领两小时后刷新。",
	["{item:7515} and Stave"] = "{item:7515}和法杖",
	["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}在{zone:1453}的{object:2101}、巫师圣殿顶部，会让你返回{npc:6546}处；{zone:1455}的彬克也提供同一任务。",
	["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}是{zone:1454}的法师训练师之一，位于{object:173161}，会让你返回{npc:6546}处；{zone:1458}的{npc:4568}和{zone:1456}的{npc:3048}也提供同一任务。",
	["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}; come in from the west road, the elites roam its east side."] = "{npc:6546}的小屋在塞拉摩以西的沼泽深处、{area:508}北侧。从西侧道路进入，东侧有精英巡逻。",
	["{npc:6549} (elite, 40)"] = "{npc:6549}（40 级精英）",
	["{quest:1958}: the {item:7515} (off-hand) or the {item:9517}"] = "{quest:1958}：选择副手物品{item:7515}或{item:9517}",
	["{quest:2861} (optional)"] = "{quest:2861}（可选）",
}

G["forever/class/mage/destroy-morphaz"] = {
	["Back to {npc:8395} and up to the tower."] = "回到{npc:8395}那里，再上塔。",
	["Back to {npc:8395}, who teleports you up to the tower."] = "回到{npc:8395}那里，他会把你传送到塔上。",
	["Back to {zone:1447}, {npc:8395} and the tower. Look at the reward window before you hand in: Classic offered the {item:20037}, the {item:20036} or the {item:20035}, and Forever's notes say the choice may be gone."] = "返回{zone:1447}，找{npc:8395}上塔。交任务前先查看奖励窗口：经典版本可选择{item:20037}、{item:20036}或{item:20035}，而无限服的说明表示此选择可能已取消。",
	["Experience"] = "经验",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "50级时通过{zone:1447}和{area:1417}获得经验；无限上可能已没有经典版的物品选择。",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like."] = "联盟飞往{area:3137}，部落飞往{area:1237}。{npc:8395}在其导师高塔下扎营，位于{area:1237}稍东侧。从{zone:1447}主路在{area:1221}处的岔路口直向北走，前往峭壁。请先下坐骑再让他传送，否则可能传送失败。一条没有敌人的小路通往塔顶的{npc:8379}；塔顶侍从可随时将你传送下来。",
	["Mage"] = "法师",
	["Morphaz"] = "摩弗拉斯",
	["The Spitelash Sirens (level 50-52) walk the ruins and beaches around the {area:1221} and the bay east of {area:1237}, often three together, and a few stand inside the {area:1223}; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. {npc:7864} ghosts wander the ruins: watch your back."] = "50–52 级恶鞭海妖在{area:1221}周围废墟与海滩，以及{area:1237}以东海湾巡逻，经常三只一起；{area:1223}内也有几只。每只约四分之一几率掉落珊瑚。恶鞭尖啸者外观相似，但不会掉落。击杀当地其他纳迦，会使更多海妖在对应位置刷新。{npc:7864}的鬼魂也在废墟游荡，注意身后。",
	["The blood elves hold the {area:1220} on the hills of north-eastern {zone:1447}. Blood Elf Surveyors (51-52, {spell:8349} up close) and Reclaimers (52-53, {spell:133}, and they heal and {spell:139} each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes."] = "血精灵占据{zone:1447}东北侧山丘的{area:1220}。51–52 级血精灵勘测员近战会施放{spell:8349}；52–53 级搜寻者使用{spell:133}，还会互相治疗并施放{spell:139}。两者各约四分之一几率掉落粉尘，警戒距离很远，从外围拉怪。刷新时间为五分半。",
	["The {item:20085}"] = "{item:20085}",
	["{area:1477}, the {area:1417}, lies in the {area:74}: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to {npc:5710} and {npc:5711} in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, {spell:12533} and {spell:11019}) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear."] = "{area:1477}，即{area:1417}，位于{area:74}。爬上台阶进入下沉的建筑，游入水下，再沿通道向下到达传送门。建议五人、50–54 级。摩弗拉斯最初不会出现，先击杀上层环形平台的六名 50–52 级精英巨魔守卫，才能从入口左侧坡道下到献祭之池，挑战{npc:5710}和{npc:5711}。预言者迦玛兰死亡后，两条绿龙德拉维沃尔和德姆塞卡尔会出现并巡逻，逐个拉怪。两者死亡后，52 级精英摩弗拉斯（使用{spell:12533}和{spell:11019}）与哈扎斯一同出现，无法分开，需同时战斗。碎片必掉。50 级猎人、牧师和潜行者也需要击杀摩弗拉斯，可以一起组队完成。",
	["{item:20085}: Morphaz"] = "{item:20085}：摩弗拉斯",
	["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "大法师{npc:331}站在{zone:1453}{object:2101}的巫师圣殿里；{zone:1455}的丁克也提供同样的任务。",
	["{npc:7311}, one of {zone:1454}'s mage trainers in {object:173161}, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}是{zone:1454}的法师训练师之一，位于{object:173161}，会提供此任务；{zone:1458}的{npc:4567}和{zone:1456}的{npc:3047}也会提供。",
	["{npc:8379} again"] = "再次找{npc:8379}",
	["{npc:8379}, in the tower"] = "{npc:8379}，在塔里",
}

G["forever/class/mage/mages-wand"] = {
	["\"Plucky\" Johnson"] = "胆大的约翰森",
	["A wand of your school for the 30s: frost, arcane or fire."] = "一根适合你30多级使用的本系魔杖：冰霜、奥术或火焰。",
	["Back to {npc:6546}. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire)."] = "返回{npc:6546}处，交付两个任务后她会开始仪式。稍等几秒再交谈，选择魔杖：冰怒（冰霜）、虚空灵力（奥术）或怒火（火焰）。",
	["Mage"] = "法师",
	["The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of {area:321}; every kind of them drops a {item:7273} about two times in five: you need ten. Then go to the {area:336} (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the {item:7272} forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more."] = "30–36 级枯木巨魔占据阿拉希东南部及{area:321}以南的村庄。所有种类约有五分之二几率掉落{item:7273}，需要十个。随后前往{area:336}，注意是外侧而非内侧法阵。中心石周围有三只 33–39 级元素生物，先逐个拉出并清理。站在中心石旁使用图腾棒，约十秒后，{item:7272}会出现在石头上，点击拾取。如果拾取前死亡，荆棘和图腾棒都会消失，需要重新收集十个。",
	["Tirth sold the book to the Scarlet Crusade. The {area:796} stands in north-eastern {zone:1420}; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in {npc:6487}'s round room: on the left-hand shelf as you face his room, next to the {item:5535}. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read."] = "大法师提尔斯已把书卖给血色十字军。{area:796}位于{zone:1420}东北部，五人组队进入图书馆区。书在通往{npc:6487}圆形房间的最后一条长走廊内，面向首领房间时，位于左侧书架、{item:5535}旁。要拾取书架上突出、被高亮标出的厚蓝书；放大镜光标表示只能阅读的书。",
	["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes."] = "大法师提尔斯的学徒是胆大的约翰森，一只在赛道瞭望塔底部啄食的小灰鸡。夜间可输入 /target 胆大的约翰森寻找。选中后输入 /beckon，不要用 /chicken 或 /wave，他会短暂变回人类，立即与他交谈并询问口令。不要攻击。如果他不在，最多五分钟就会刷新。",
	["Witherbark trolls and the {item:7272}"] = "枯木巨魔与{item:7272}",
	["at the middle stone of the {area:336}"] = "在{area:336}的中心石处",
	["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}在{zone:1453}的{object:2101}、巫师圣殿顶部，会让你前往{npc:6546}处；{zone:1455}的彬克也提供同一任务。",
	["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}是{zone:1454}的法师训练师之一，位于{object:173161}，会让你前往{npc:6546}处；{zone:1458}的{npc:4568}和{zone:1456}的{npc:3048}也提供同一任务。",
	["{npc:6546} also wants one {item:1529}, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of {area:271} drop one about every fifth kill. Do not sell it to a vendor by mistake."] = "{npc:6546}还需要一颗绿色宝石{item:1529}。采矿时有几率从矿脉获得，也可在拍卖行购买；{area:271}西南海岸的碎鳍滩行鱼人约每五只掉落一颗。不要误卖给商人。",
	["{npc:6546}'s ritual"] = "{npc:6546}的仪式",
	["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the {zone:1413}. Her cottage is no refuge: mobs follow you inside. Take both her quests."] = "隐士{npc:6546}住在塞拉摩以西的沼泽深处、{area:508}北侧小屋。农场东侧有 38–41 级精英巡逻，游泳进入还会经过 42 级泥壳蟹；请沿{zone:1413}过来的西侧道路进入。小屋并非安全区，怪物会追进去。接取她的两个任务。",
	["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548}整天待在{zone:1441}东南部{area:439}的赛道旁。",
	["{quest:1951}: Scarlet Monastery Library"] = "{quest:1951}：血色修道院图书馆",
}

G["forever/class/mage/polymorph-pig"] = {
	["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "{spell:118}的新外观：把目标变成猪而不是羊。",
	["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "返回满是恶鞭纳迦的{area:1221}。对一只纳迦施放绵羊形态的{spell:118}，乌龟形态无效。等待数秒，它会分裂出两到六只约 150 生命值的变形克隆，并迅速逃跑。站在绵羊旁，复制体一出现就使用{spell:122}和{spell:1449}。需要击杀五十只，会花些时间，不能处于团队状态。",
	["Back to {npc:8395} and up to the tower."] = "回到{npc:8395}那里，再上塔。",
	["Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags."] = "返回{npc:8395}处并上塔。大法师克希雷姆提供下一项任务时会把贝壳还给你，保留在背包里。",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "联盟飞往{area:3137}，部落飞往{area:1237}。{npc:8395}在{npc:8379}的高塔下扎营，位于{area:1237}稍东侧。从{zone:1447}主路在{area:1221}处的岔路口直向北走，前往峭壁。下坐骑后，他会把你传上去，再沿小径爬到塔顶找大法师。",
	["Mage"] = "法师",
	["Polymorph Clone"] = "变形术克隆体",
	["Polymorph Clones"] = "变形克隆",
	["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}：{spell:118}（猪）",
	["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "55 级非精英{npc:8408}藏在{area:1221}中央最大建筑{area:1223}内的恶鞭守卫后方，会使用打击和{spell:99}。必定掉落{item:23250}，五分半刷新。先退出团队，团队状态下无法获得任务进度，小队状态可以。",
}

G["forever/class/priest/benediction"] = {
	["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "装备 {item:18646}，然后寻找 {npc:14494}，她是位于 {zone:1423} 西北部山坡上的幽灵，在 {area:2279} 大门西边（如果看不见她，先卸下眼睛再重新装备）。{quest:7621} 只需交谈；{quest:7622} 则在接受的瞬间开始，所以先做好准备：回满法力，准备特效法力药水、恶魔符文或黑暗符文、回蓝食物或 {item:13931}，以及一组 {item:8956} 或 {item:13180} 来对付骷髅。",
	["Priest"] = "牧师",
	["Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back."] = "在15名农民死亡前救下50名（路边的{object:179694}会统计死亡人数）。他们分批从洞穴走向{npc:14494}，途中会染病，并引来骷髅和骷髅弓箭手。优先驱除泛紫光的疾病（{spell:552}），给受伤者保持{spell:139}，对濒死者施放{spell:2061}，并在骷髅出现时立即击杀：3级及以上的{spell:15237}一次就能杀死它们，用油则要跳两次伤害，这期间它们仍会攻击你。每波开始时给自己套盾；开启友方姓名板便于找出受伤的农民。朋友可以在你接受任务前给你增益，也能治疗农民或驱除他们的疾病；但事件开始后，不能治疗你、给你增益、攻击骷髅或带宠物来，否则会出现一个恶魔杀死所有人。失败后，{npc:14494}会消失一段时间（玩家报告的时间从15分钟到2小时不等）；她回来后再与她交谈。",
	["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "史诗牧师法杖：来自{area:2717}的{spell:23101}，{npc:14494}的农民救援，然后是暗影之眼。",
	["The splinter needs {item:18665} as well. {npc:12397}, a world boss in the {zone:1419} (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first."] = "合成碎片还需要{item:18665}。{zone:1419}的世界首领{npc:12397}（需团队应对）必定掉落；当地的法力犬和末日守卫指挥官也有小概率掉落（约3%和2%），冬泉谷的赫达琳恶魔则极少掉落。该物品可以交易：先看看拍卖行。",
	["Use the {item:18659} with both Eyes in your bags: {item:18608}"] = "确保两只眼睛都在背包中，再使用 {item:18659}：获得 {item:18608}",
	["With the {item:18659}, {item:18646} and {item:18665} in your bags, use the splinter wherever you are: it becomes {item:18608}. Use {item:18608} to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown)."] = "背包里带着 {item:18659}、{item:18646} 和 {item:18665} 时，无论身在何处，使用碎片即可将其制成 {item:18608}。使用 {item:18608} 可将它转为暗影法杖咒逐，也能再转回来（冷却 30 分钟）。",
	["{item:18608} and Anathema"] = "{item:18608}与咒逐",
	["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "{item:18646}来自{object:179703}，这是在40人团队副本{area:2717}中，{npc:12018}投降后出现的箱子（约一半概率开出该物品）。{area:2717}的传送门位于{area:1584}最深处；完成“熔火之心的传送门”（从该传送门旁取得{item:18412}）后，{area:254}内的{npc:14387}可将你直接传送进去。没有眼睛就无法开始这条任务链：装备后才能看见{npc:14494}。",
	["{item:18646}: {area:2717}, through {area:254}"] = "{item:18646}：经由 {area:254} 前往 {area:2717}",
	["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387}：完成入场资格任务后，由此进入{area:2717}",
}

G["forever/class/priest/blood-of-morphaz"] = {
	["17,060 XP and 1g55s at 50: {zone:1447}, then Morphaz in the {area:1417} (group of 5). The item choice may be gone."] = "50级时获得17,060 XP和1g55s：{zone:1447}，然后是{area:1417}中的摩弗拉斯（5人小队）。物品选择可能已被取消。",
	["17,060 experience and 1 gold 55 silver"] = "17,060经验和1金55银",
	["At 50 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) offers {quest:8254}. Before you leave a city, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "50级时，{zone:1455}的{object:32386}（{object:32362}）内的{npc:11406}会提供{quest:8254}。离开城市前，先在拍卖行买一个{item:7972}（几枚银币）：第三个任务会用到，而且掉率很低。",
	["At 50, {npc:5489} at the altar of {zone:1453}'s Cathedral of Light offers {quest:8254} ({npc:11406} in {zone:1455} has it too). Before you leave, buy an {item:7972} at the Auction House in the {object:2096} (a few silver): the third quest asks for one and it drops rarely."] = "50级时，{zone:1453}圣光大教堂祭坛旁的{npc:5489}会提供{quest:8254}（{zone:1455}的{npc:11406}也有）。离开前，先在{object:2096}的拍卖行买一个{item:7972}（几枚银币）：第三个任务会用到，而且掉率很低。",
	["At 50, {npc:6018} in {zone:1454}'s {object:172961} offers {quest:8254}. Before you leave, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "50级时，{zone:1454} 的 {object:172961} 中的 {npc:6018} 会提供 {quest:8254}。离开前先在拍卖行买一个 {item:7972}（几银币）：第三个任务会需要一个，而它的掉率很低。",
	["Carrying an {item:7972} already? It counts at once. Otherwise any undead may drop one, rarely: the {npc:7864} (level 48) in the {area:1221} below {npc:8405}'s cliff drop it about one kill in ten, the highborne ghosts on {zone:1447}'s border with {zone:1440} (level 45-46) a little less, the Anguished and {npc:7523} in {zone:1452} (54-55) about one in eight. The Auction House is usually quicker."] = "已经带着 {item:7972}？可以立即完成目标。否则，任何亡灵都有小概率掉落：在 {area:1221}、{npc:8405} 所在悬崖下的 {npc:7864}（48 级）约每十次击杀掉落一次；{zone:1447} 与 {zone:1440} 交界处的上层精灵鬼魂（45-46 级）掉率略低；{zone:1452} 的痛苦的上层精灵和 {npc:7523}（54-55 级）约每八次击杀掉落一次。去拍卖行通常更快。",
	["Morphaz in the {area:1417}"] = "{area:1417}中的摩弗拉斯",
	["Morphaz is a level 52 elite green dragon inside the {area:1417}, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. The temple stands in the middle of the {area:74}: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then {npc:5710} below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops."] = "摩弗拉斯是 {area:1417} 内的一条 52 级精英绿龙，这是五人地下城：带上五人小队（60 级小队打起来很轻松）。部落：飞往 {area:75}；联盟：飞往 {zone:1419} 的 {area:1438}，再骑马向北。神庙位于 {area:74} 中央：从南侧台阶上去，游过被淹没的大厅，再沿楼梯走到传送门。进入后，要推进到后段摩弗拉斯才会出现：先杀死上层阳台上的六名巨魔小首领，再杀死下方的 {npc:5710}；这会唤醒献祭之池的德拉维沃尔和德姆塞卡尔，杀死两者后，摩弗拉斯和哈扎斯才会出现。这两条龙一起巡逻，无法拆开引：把它们拉进走廊，由坦克让龙头背对队伍（有吐息和击退）。拾取时要处于小队，而不是团队中：龙血必定掉落。",
	["Mosshoof Coursers (level 52-53, not elite) graze all over {zone:1447}, thickest north-east of {npc:8405} and south of the mountains; about one in three drops a {item:20027}, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any {item:7972} you loot."] = "苔蹄快步者（52-53级，非精英）在{zone:1447}各处吃草，{npc:8405}东北方和山脉以南最多；掉落{item:20027}的概率约为三只出一个，因此凑齐四个预计要击杀十二只。它们在生命值降至30%时会激怒：尽快击杀。杀它们不会损失塞纳里奥议会声望。保留拾取到的所有{item:7972}。",
	["Priest"] = "牧师",
	["{npc:10922} is at the {area:2479} in southern {zone:1448}. Horde: fly to {area:1997} and ride south-east; Alliance: fly to {area:415} in {zone:1440} and ride north into {zone:1448}. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick {item:19990}, {item:20006} or Woestave, and Forever's notes say that choice may be gone."] = "{npc:10922}在{zone:1448}南部的{area:2479}。部落：飞往{area:1997}后向东南骑行；联盟：飞往{zone:1440}的{area:415}后向北骑行，进入{zone:1448}。把血交给她可获得经验和金币。交还前先查看奖励窗口：经典版可选{item:19990}、{item:20006}或悲哀之杖，而无限服的说明称这个选择可能已移除。",
	["{npc:8405}, a furbolg, lives on the clifftop north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up."] = "熊怪{npc:8405}住在{area:1221}东北面的悬崖顶上。联盟飞往{area:3137}，部落飞往{area:1237}。骑马向东，在废墟前的岔路离开道路，然后沿北侧崖边向东找到他：娜迦废墟和下方海滩被悬崖围住，无法从下面上去。",
	["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}：{area:1417}入口",
}

G["forever/class/rogue/ravenholdt"] = {
	["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "24级时，任意主城的潜行者训练师（{zone:1453}的{npc:332}或{npc:918}、{zone:1454}的盖斯特或奥莫克，以及其他主城的训练师）都有{npc:13936}送你的{item:17126}：在交谈窗口中索取。打开后，任务会给你送给{npc:6707}的{item:17125}。若还没学会{spell:1846}，先向训练师学习；进去的路线会考验这个技能。",
	["Back to {npc:13085}"] = "回到{npc:13085}处",
	["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "回到 {npc:13085} 处；提交报告后，他会让你去找匹瑞诺德的传家宝。两座塔楼矗立在 {zone:1416} 中部的 {area:281}，被食人魔占据：盾牌在北塔，剑在南塔，南塔周围有精英食人魔，它们从很远就能发现你。保持潜行；塔内的传家宝旁没有守卫。",
	["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "法库雷斯特的手下在 {area:1057} 南端交接货物，这是阿拉希与 {area:287} 之间的旧城墙。杀死看守箱子的两人，取走 {item:275882}。保留 {item:275706}：{npc:13085} 要你连同货物一起交回。",
	["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "部落飞往{area:272}，联盟飞往{area:271}。通往庄园的小路很难发现：起点在{area:275}北面高地的后方、{area:272}以东，沿路爬上山丘，拐两次弯后到达一条小隧道。隧道内有个箱子：不要打开。在附近施放{spell:1846}，再走近箱子；这样就完成了入门考验（五分钟后刷新）。打开箱子会召来米尔顿·西弗，一名约32级的精英盗贼。穿过隧道就是{area:3486}：{npc:6707}在屋内楼上。不要攻击庄园中的任何人：会损失{npc:13936}声望。",
	["In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "35级左右时，{npc:13085} 还有两项任务，都接下。巴顿 带领一支辛迪加侦察队，位于 {zone:1416} 东部的 {area:280}，在其中一栋房屋内，周围有潜行的辛迪加成员。对他使用偷窃取得报告，不要杀他：他不会掉落报告。如果你等级比他低，他能识破潜行；欺诈高手天赋有帮助，也可以先扰乱他，再消失并绕到背后接近。{spell:921} 可能连续几次未命中。",
	["Lord Tomas"] = "托马斯领主",
	["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "开启{area:3486}——奥特兰克山区隐秘的潜行者宅邸，以及{npc:13085}针对辛迪加的任务。",
	["Pick Pocket Barton for {item:275482}"] = "对巴顿使用搜索，获得{item:275482}",
	["Pick Pocket Syndicate members for {quest:6701}"] = "对辛迪加成员使用搜索，完成{quest:6701}",
	["Ravenholdt"] = "拉文霍特",
	["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "狡诈仪式：在隧道宝箱旁使用 {spell:1846}。",
	["Rogue"] = "盗贼",
	["She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back."] = "没有可供交换的东西，她就不愿交谈。她藏的东西在城堡附近一座房子的楼上：拿走 {item:275709}。如果已经被打开，就等它刷新。",
	["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "激流堡的辛迪加潜伏者和召唤师是精英（35-36级）：36级盗贼可以偷偷绕过，但单挑一个也很吃力，因此保持隐蔽或带朋友来。穿上{item:275706}（在手提箱处接受{quest:96784}时会拿到），伪装成他们的一员；潜行或可疑举动可能使伪装失效。如果手提箱没有给你制服，{npc:266847}会在提供{quest:96785}时给你一件。她不在城堡内部：她站在城墙外侧的凸台上。从凸台旁房子的屋顶跳过去。",
	["The {item:17126}"] = "{item:17126}",
	["one emblem each time, 100 reputation"] = "每次一枚徽记，100声望",
	["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "阿拉希西部的 {area:324} 是辛迪加的据点；要进去，需要一套制服。阿拉希西北部的 {area:313} 被辛迪加路霸、巡路者和雇佣兵（30-32 级）占据：在那里找到 {object:656157}，取走制服，即可完成 {quest:96783}。",
	["{item:17124}, by {spell:921}"] = "{item:17124}，靠{spell:921}取得",
	["{item:275482}: {spell:921} on Barton"] = "{item:275482}：对巴顿使用{spell:921}",
	["{item:275635}, in the southern tower"] = "{item:275635}，在南面的塔楼中",
	["{item:275636}, in the northern tower"] = "{item:275636}，在北面的塔楼内",
	["{item:275709}: Anastasia's Stash"] = "{item:275709}：她的藏匿处",
	["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085}：70银币，300点 {npc:13936} 声望",
	["{npc:13936} reputation"] = "{npc:13936}声望",
	["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} 位于庄园南侧辛迪加堡垒 {area:275} 内；他可能出现在堡内十五个位置中的任意一处，需要搜索。{npc:13085} 要求行动迅速、保持安静。沿途对 20-21 级的辛迪加潜行者、暗影法师和卫兵使用偷窃：他们携带 {quest:6701}，可用于守卫提供的可重复声望任务。",
	["{npc:6766}: {quest:6701}, repeatable"] = "{npc:6766}：{quest:6701}，可重复",
	["{quest:96784}: the {item:275706}"] = "{quest:96784}：{item:275706}",
}

G["forever/class/rogue/the-azure-key"] = {
	["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "联盟飞往{area:3137}，部落飞往{area:1237}。只有{zone:1447}北部熊怪山丘里的50-51级木喉萨满祭司携带袋子（更南面的47-49级熊怪没有）：大约每击杀30个掉落一次。改用{spell:921}偷取就不会损失木喉声望；如果你与{area:1769}的关系为冷淡或更好，先在声望面板勾选“交战”。它们会施放{spell:403}和{spell:6535}，互相治疗，并在低血量时逃跑。",
	["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "50级时，{object:172960}的{npc:3328}提供此任务；{zone:1458}{object:36073}的{npc:4583}也提供。",
	["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "50级时，{zone:1453} 的 {object:2100} 中的 {npc:918} 会提供此任务；{zone:1457} 的塞尤娜和 {zone:1455} 的 {npc:5165} 也会提供。",
	["Back to Xylem"] = "回到克希雷姆处",
	["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "交还前先查看奖励窗口：经典版可选{item:19982}、{item:19984}或{item:20255}，而无限服的说明称这个选择可能已移除。",
	["Lord Ravenholdt"] = "拉文霍德公爵",
	["Morphaz in the {area:1417}"] = "{area:1417}中的摩弗拉斯",
	["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "摩弗拉斯是一只52级精英绿龙，位于 {area:1417} 深处：需要50—54级的五人小队。神庙位于 {area:74}；爬进沉没的建筑，向下游穿过建筑，再沿通道走到传送门。部落：飞往 {area:75}；联盟：飞往 {area:1438} 后骑乘前进。刚抵达时他不会出现：先击杀上层环廊各平台上的六名巨魔守护者（50—52级精英），才会打开通往献祭之坑中 {npc:5710} 的下行道路（从入口左侧坡道下去）。迦玛兰死亡后会出现两条幼龙德拉维沃尔和德姆塞卡尔；两条都死后，摩弗拉斯和哈扎斯会一起出现并联手战斗。它们的 {spell:12533} 造成自然伤害：自然防护药水有帮助；毒药和 {spell:2094} 对它们无效。钥匙必定掉落。50级的猎人、牧师和法师也需要击杀摩弗拉斯：打通一次就能一起完成。",
	["Ravenholdt reputation"] = "拉文霍德声望",
	["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "50级的拉文霍德声望和经验；无限 可能已移除经典版的物品选择。",
	["Rogue"] = "盗贼",
	["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "森林软泥怪（52-53 级，近身会使用 {spell:6907}）有五分之四的概率掉落碎片：数量最多的一群共七只，位于 {zone:1447} 东北部的 {area:2497} 丘陵，{area:1237} 东南方还有四只。击杀前先偷窃，可额外获得一两个碎片。击杀同一地点的雾翼掠夺者和角鹰兽，能让更多软泥怪出现。",
	["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486}藏在{area:272}东侧的山丘中。部落飞往{area:272}，联盟飞往{area:271}。小路从{area:275}北面高地的后方开始，爬上山丘，再穿过一条小隧道进入{zone:1416}；乔拉齐·拉文霍德公爵就在庄园内。不要攻击庄园中的任何人：失去拉文霍德声望会让他拒绝与你交谈。",
	["{item:20022}: Morphaz, inside the temple"] = "{item:20022}：神庙内的摩弗拉斯",
	["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395} 在 {area:1237} 东侧不远的悬崖下扎营，会把你传送上去（先解除骑乘）；上方有一条小路通往大法师克希雷姆的塔。",
	["{quest:8233} (Alliance)"] = "{quest:8233}（联盟）",
	["{quest:8233} (Horde)"] = "{quest:8233}（部落）",
}

G["forever/class/rogue/the-eye-of-bhossca"] = {
	["Back to the dead drop"] = "回到秘密投递点",
	["C's dead drop"] = "C的秘密投递点",
	["C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "C的下一份委托通过信件送达：达到30级并完成号角委托后，前往任意主城，C的信会出现在邮箱里；之后银松森林南部{area:204}附近、{area:236}南边的{object:410369}才会提供该任务。任务资料标注最低25级，但玩家实际在30级才收到信件和委托。",
	["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "把眼睛放进焚木村附近的{object:410369}。下次计划中回主城时，检查邮箱里C的报酬来信，再回这里领取奖励任务。报酬可能不会立刻出现，不要因为暂时没有奖励就重新潜入。",
	["Rogue"] = "盗贼",
	["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "单人路线：墓地偷钥匙→图书馆取信→墓地长椅机关与石棺→图书馆遗物匣取眼睛。先读信再做长椅机关，每次切换区域后检查伪装。",
	["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "修道院位于 {zone:1420} 的东北尽头。必须退出小队，独自进入。进入前，先从修道院后方马厩的补给柜取得并穿戴 {spell:427592}；潜行和可疑举动会使伪装消失，因此每次切换区域后都要重新穿戴。在墓地区的忏悔室（第一个大厅），对 {npc:4293} 或 Scarlet Crier 使用 {spell:921}，取得 {item:210963}。进入图书馆，用它打开馆内的私人信箱，并阅读机密信息。信件会指引你返回墓地区，坐上两座雕像之间的两张长椅。留意机关提示，然后从石棺中取出 {item:210968}：石棺旁有一名精英，后面还有巡逻怪，但你可以站在北侧陵墓旁转动镜头，直到看见箱子，再隔墙点击（互动按键也可用）。陵墓附近有一只精英幽灵来回走动；站在陵墓边缘的残破部分可避开其路线。随后回图书馆，获取上锁圣物匣和眼睛。尽量避免在副本内战斗。",
	["The {area:796}"] = "{area:796}",
	["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "{item:277246}，是C为一次{area:796}单人任务支付的报酬。",
	["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. After the horn job and C's next letter, check it for the new job. The data lists a minimum of 25, but beta players report receiving the invitation at 30 after the horn job and a city visit; this is not a guaranteed mail level. If no new note is offered, continue leveling and check after C writes."] = "{object:410369}是银松森林南部{area:204}附近的箱子，就在{area:236}南边。完成号角委托并收到C的下一封信后，再来查看新委托。资料标注最低25级，但有测试服玩家完成号角委托后，在30级回主城时才收到邀请；这并非保证触发的来信等级。没有新字条时先继续升级，收到来信后再查看。",
}

G["forever/class/rogue/the-horn-of-xelthos"] = {
	["Back to the dead drop"] = "回到秘密投递点",
	["C's dead drop"] = "C的秘密投递点",
	["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "独自进入，在庭院大门处使用 {item:210186}。也有玩家报告，被释放的囚犯会替你打开庭院大门：如果他开门时你死了，先保持死亡状态，等门开了再释放灵魂；释放灵魂后门仍会保持开启。如果已学会消失，进入前带上 {item:5140} 并检查冷却时间，确保接近目标失败时能用它脱身。先在餐厅偷窃妹妹，取得 {item:210213}，再上楼梯并在顶端右转，进入房间偷窃哥哥，取得 {item:210212}（没有消失的 20 级潜行者，可能需要投入欺诈高手天赋才能不被发现地靠近第二人）。在安全地点将两者合并：这会解除潜行。先腾出一个背包空格：背包已满时开箱，可能会消耗钥匙却拿不到号角。返回庭院马厩，用合并后的钥匙打开宝箱，取得号角。避开附近的精英；达到任务最低等级不代表能安全靠近。",
	["Place the horn in the {object:410369} near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered."] = "把号角放进焚木村附近的{object:410369}。报酬可能不会立刻出现：下次计划中回主城时，检查邮箱里C的后续来信，再回这个箱子领取报酬任务。暂时没有报酬任务，不代表需要重新潜入副本。",
	["Rogue"] = "潜行者",
	["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}，是C为一次{area:236}单人任务支付的报酬。",
	["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} 是一只宝箱，位于银松森林南部、{area:236} 以南的 {area:204} 外一间房子里。打开它并阅读 C 的便条：这项工作必须退出小队，独自完成。",
	["{item:210183}, inside {area:236}"] = "{item:210183}，在{area:236}里",
	["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}是一个对双方阵营都友好的地精，站在石爪山脉东部{area:461}的风险投资公司人员中间，位于{area:460}东北方不远处。部落飞往{area:460}；联盟飞往{area:467}。他要一份{item:210187}才肯交出炸药：在他周围干活的风险投资公司伐木工（18级）口袋里带着。潜行到其中一个身后，对其使用{spell:921}；杀死他们不会掉落。",
	["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them."] = "{npc:4086}是一名对双方阵营都友善的地精，站在石爪山脉东部{area:461}的风险投资公司成员中间，位于{area:460}东北不远处。部落飞往{area:460}；联盟飞往{area:467}。他要先拿到{item:210187}才肯交出炸药：在他周围干活的风险投资公司伐木工（18级）身上带着。",
	["{spell:921} a {npc:3989} for a {item:210187}"] = "对{npc:3989}使用{spell:921}，取得{item:210187}",
}

G["forever/class/warlock/enchanted-gold-bloodrobe"] = {
	["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "一件适合30多级的稀有布甲长袍，{npc:6266}会用你带来的材料制作。",
	["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31级时，{object:172960} 的 {npc:3326} 会派你去找 {area:392} 的 {npc:6266}。先买一件 {item:5770} 和一块 {item:3577}（后续步骤要用），免得多跑一趟。",
	["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "达到 31 级后，{object:36082} 中的 {npc:4563} 会让你去找 {area:392} 的 {npc:6266}；从 {zone:1420} 出发的飞艇会飞往 {zone:1411}。先买好一个 {item:5770} 和一个 {item:3577}（见后续步骤），免得多跑一趟。",
	["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31级时，{object:2101} 的 {object:2164} 内的 {npc:461} 会派你去 {area:392} 找 {npc:6266}。先买好一件 {item:5770} 和一块 {item:3577}（见后续步骤），可以省去往返。",
	["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "31级时，{zone:1455}的{npc:5172}会派你去{area:392}找{npc:6266}。先买一个{item:5770}和一个{item:3577}（接下来的步骤会用到），省得多跑一趟。",
	["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "返回 {area:35} 的 {npc:2670} 处：他提供的 {quest:4785} 可以接到后立即交还。他可能没有任务标记，仍然要与他交谈。",
	["Back to {npc:6266}"] = "回到{npc:6266}处",
	["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "带着线、煤和一个 {item:6265} 返回 {npc:6266} 处。随后待在她身旁，等她制作长袍（不要攻击她：任务日志将其描述为击杀），再与她交谈。",
	["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "裁缝可以用稀有图样制作 {item:5770}；采矿者可以用 {item:2776} 熔炼金锭。其他人可在拍卖行购买这两样物品。如果你正穿着这件长袍，先脱下来：{npc:6266} 会将它收走。",
	["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. They resist fire: {spell:686} and Corruption. Below 38 they hit hard; the Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "烈焰流放者（38—39级）是 {zone:1417} 西部 {area:334} 的火元素，煤炭掉率约为三分之一。它们抵抗火焰：使用 {spell:686} 和腐蚀术。未到38级时，它们打人很痛；先打伤它们，再使用 {area:321} 附近水浪流放者掉落的海浪咒符，就能将其消灭。路上用 {spell:1120} 制作一块 {item:6265}。",
	["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25. The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south, drop the stone half the time; they resist fire, so use {spell:686} and Corruption."] = "怨怒萨特（31-32级）盘踞在{zone:1443}最东北端、{area:608}后面的{area:603}：约五只出两瓶，预计需要击杀25只。南部{area:602}的次级地狱火（36-37级）和恶魔之门的卫士（38级）掉石头的概率为一半；它们有火焰抗性，因此使用{spell:686}和腐蚀术。",
	["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "从 {area:392} 出发的船驶往 {area:35}。{npc:2670} 在镇内上层经营 {object:59851}。将 {item:3577} 交给他；他稍后会纺好线。",
	["Vials of Hatefury Blood"] = "怨怒萨特之血",
	["Wait beside {npc:6266} while she finishes the robe"] = "待在 {npc:6266} 身旁，等她完成长袍。",
	["Warlock"] = "术士",
	["You need no thread yet: {npc:6266} wants demon parts from {zone:1443} next."] = "暂时不需要线：接下来{npc:6266}要你去{zone:1443}收集恶魔的身体部件。",
	["{item:3577}: the Auction House"] = "{item:3577}：从拍卖行购买",
	["{item:5770} and a {item:3577}"] = "{item:5770} 和一块 {item:3577}",
	["{item:5770}: the Auction House"] = "{item:5770}：从拍卖行购买",
	["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265}：在一只流放者即将死亡时对其使用 {spell:1120}。",
	["{npc:6266} again"] = "再次找{npc:6266}",
	["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} 站在 {area:392} 上方山坡上、工程师小屋后面的 {npc:6251} 高塔旁。她会收下长袍，然后让你把金锭送给 {area:35} 的 {npc:2670}。",
	["{zone:1443} demons"] = "{zone:1443}的恶魔",
}

G["forever/class/warlock/impsys-request"] = {
	["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "50多级的法杖、副手或长袍；这是{npc:14470}自己的差事，不属于恐惧战马任务线。",
	["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "琥珀巫毒羽毛：加什尔、{npc:5716}",
	["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50级时，{object:172960} 内的 {npc:3326} 会派你带上一块 {item:14256}，去 {zone:1448} 找 {npc:14470}。",
	["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50级时，{object:36082} 内的 {npc:4563} 会派你带上一块 {item:14256}，去 {zone:1448} 找 {npc:14470}。",
	["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50级时，{object:2101} 的 {object:2164} 内的 {npc:461} 会派你带上一块 {item:14256}，去 {zone:1448} 找 {npc:14470}。",
	["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "50级时，{zone:1455}的{npc:5172}会派你带一块{item:14256}去{zone:1448}找{npc:14470}。",
	["Blue Voodoo Feathers: Hukku, Mijan"] = "蓝色巫毒羽毛：胡库、米杉",
	["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "选择 {item:20536}（法杖）、{item:20534}（副手）或 {item:20530}。",
	["Green Voodoo Feathers: Zolo, Loro"] = "绿色巫毒羽毛：祖罗、洛若",
	["One {item:14256}: the Jadefire satyrs of {zone:1448} drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's {quest:8419} or for {npc:14470}'s own {quest:8420}, the same errand: whichever you hold."] = "一份 {item:14256}：{zone:1448} 的碧火萨特掉率约为十四分之一；你为万能的尼比收集精华时猎杀的雷加斯萨特和恶魔卫士哨兵也会掉落。更快的办法是去拍卖行买一份。无论你接的是训练师的 {quest:8419}，还是 {npc:14470} 自己提供的 {quest:8420}，都需要它；两者是同一项差事。",
	["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "{zone:1448}北部、{area:1998}以西{area:1767}的铁木树人（52级）掉落{item:20613}的概率为四分之一；体型巨大的{npc:7149}（55级）经常一次掉3个，但伤害很高，还会造成眩晕。{npc:14470}周围及血毒河沿岸的被污染的软泥怪（51级）掉落精华的概率为五分之一。",
	["The {area:1417}"] = "{area:1417}",
	["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "{area:1417}（{area:1477}，50—56级，五人小队）位于 {area:74} 中央：游入水下神庙，再沿楼梯前往入口。六名巨魔守护者（51—52级精英）站在中央深坑周围的看台上，每名身旁都有其他敌人；每次击杀都必定掉落对应的羽毛：加什尔和 {npc:5716} 掉落琥珀色，胡库和米杉掉落蓝色，祖罗和洛若尔掉落绿色。52级时无法单刷。",
	["Warlock"] = "术士",
	["{item:20613} and Bloodvenom"] = "{item:20613}和血毒",
	["{npc:14470} again"] = "再次找{npc:14470}",
	["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} 现在需要来自 {area:1417} 的六份 {item:20609}：要打一次地下城。",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470}在{area:1997}东北方不远的高地上，站在{npc:14469}旁边：向北过{area:1765}的桥后，经过几只软泥怪，他们就在道路东侧。将训练师的{quest:8419}连同布料一起交给他。接下来他需要十个{item:20613}和四个{item:20614}。",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470}在{area:1997}东北方不远的高地上，站在{npc:14469}旁边：向北过{area:1765}的桥后，经过几只软泥怪，他们就在道路东侧。接受他自己的{quest:8420}，并立即交给他布料。接下来他需要十个{item:20613}和四个{item:20614}。",
}

G["forever/class/warlock/orb-of-orahil"] = {
	["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "三十多级的副手宝珠或法杖，可选地狱犬或地狱火路线。",
	["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "35级时，{object:172960}的{npc:3326}会让你去{area:392}找{npc:6266}。",
	["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "35级时，{object:36082}的{npc:4563}会让你去{area:392}找{npc:6266}。从{zone:1420}出发的飞艇飞往{zone:1411}。",
	["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "35级时，{object:2101}{object:2164}的{npc:461}会让你去{area:392}找{npc:6266}。",
	["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "35级时，{zone:1455}的{npc:5172}会让你去{area:392}找{npc:6266}。",
	["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "带着净化后的宝珠返回 {area:392} 上方高塔中的 {npc:6266} 处。如果走的是地狱猎犬路线，接受她的最后一个任务，留在她身旁等她完成 {item:15108}（不要攻击她：任务日志将其描述为击杀），再与她交谈，选择副手宝珠或法杖。",
	["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "先带着灵魂和宝石返回 {area:392} 上方塔楼里的 {npc:6266} 处：完成后才有她的宝珠任务。",
	["Choose an acolyte"] = "选择一名侍僧",
	["Demon of the Orb"] = "宝珠中的恶魔",
	["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "选择地狱火路线时，接受她的最后一个任务，留在{npc:6266}旁，等她完成{item:15107}，然后再次与她交谈，选择副手宝珠或法杖。",
	["Orb of Orahil"] = "奥拉赫宝珠",
	["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "选一名侍僧：你只能接受其中一人的任务。{npc:6254} 的地狱犬路线最终奖励宝珠或 {item:15106}，属于暗影版本；{npc:6252} 的地狱火路线奖励宝珠或 {item:15105}，属性大致相同，但偏向火焰。大多数术士以暗影伤害为主，不过最好先查看四件物品的提示信息作比较。指南会跟随你所选的任务。保留红宝石或翡翠：之后要交还。",
	["The demon's spirit"] = "恶魔的灵魂",
	["The {item:15107}"] = "{item:15107}",
	["The {item:15108}"] = "{item:15108}",
	["Wait beside {npc:6266} while she makes the orb"] = "在 {npc:6266} 旁等待她制作宝珠",
	["Warlock"] = "术士",
	["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} 占据 {zone:1443} 中南部，位于 {area:2408} 东边。火刃召唤师（38-39 级，带小鬼的术士）必定携带 {item:7291}。收集灵魂时，先用持续伤害把目标恶魔打到低血量，然后对它引导红宝石或翡翠，并保持引导直到它死亡，方法与 {spell:1120} 相同：宝石本身不会造成伤害。红宝石可用于集会所的地狱犬：北部的两只噬法魔犬（37-38 级），以及更南边的法师猎手（38 级）和灵能猎犬（39 级）。翡翠可用于次级地狱火（36-37 级，共十六只，抗火）。",
	["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}，从{npc:4678}、{npc:4681}或{npc:4685}身上获得",
	["{item:12649}, from a {npc:4676}"] = "{item:12649}，来自{npc:4676}",
	["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}，来自{npc:4668}",
	["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}：他给你{item:12646}",
	["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}：她给你{item:12647}",
	["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} 和她的两名侍僧站在 {area:392} 上方山丘上的 {npc:6251} 塔楼里。",
	["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Before you accept Cleansing, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 35-38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546}住在{zone:1445}中部自己的农场里，位于从{zone:1413}过来的道路以南、塞拉摩西南面；旁边站着一名灵魂医者。45级鳄鱼死沼巨鳄在东北不远处的溪流间巡逻。接受 奥拉赫宝珠的净化 前，先清掉她围场周围的蜘蛛和鳄鱼。接受后会开始3分钟倒计时：她走到围场，放出{npc:6549}。它是40级精英：建议组队；40级左右的术士可用恐惧或{spell:710}配合持续伤害单刷，35-38级则带个朋友。击杀后计时仍在继续，务必立刻交还任务。如果超时，放弃任务后重新向{npc:6546}接受。",
}

G["forever/class/warlock/orb-of-soranruk"] = {
	["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "一件适合20多级的稀有副手宝珠或法杖，用两个地下城的碎片换取。",
	["Back to {npc:6247}"] = "回到{npc:6247}处",
	["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "选择副手物品 {item:6898} 或双手武器 {item:15109}。",
	["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "索兰鲁克宝珠的碎片，由里面的暮光侍僧掉落",
	["Warlock"] = "术士",
	["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236}（22-30 级，五人小队）位于 {area:228} 南侧山丘上。释放入口右侧牢房中的囚犯，他会打开通往庭院的路。影牙魔魂狼人（20-21 级，精英）不在庭院中：它们在庭院之后的走廊、向左弯曲的坡道上，以及后面的建筑中活动。每次副本约有十二只，每只掉落 索兰鲁克宝珠的大碎片 的概率为五分之一，因此要清掉所有魔魂狼人，若没掉就再刷一次。",
	["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} 是24—32级的五人地下城，入口在 {zone:1440} 西北海岸废墟中、{area:414} 的水下。暮光侍僧（24—25级精英，会治疗）位于最后几间大厅里，分布在 {npc:4832} 周围及 {npc:4829} 前方的祭坛旁；每名都掉落一块碎片，但每次副本只有三名，且两小时内不会刷新，因此一趟只能满足一名术士的需求：先杀掉他们，免得他们治疗其他敌人。",
	["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}，由内部的影牙魔魂狼人掉落",
	["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247}和{npc:6244}在一起，营地位于{zone:1413}南部、{area:378}东北不远的一顶帐篷旁。联盟术士可从{area:392}或塞拉摩前往；部落术士从十字路口向南走。他需要两个副本的碎片：在去{area:2797}和{area:236}前先接任务。",
	["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the {area:380}. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247}与{npc:6244}一起扎营，帐篷就在{zone:1413}南部{area:378}东北不远处。联盟术士从{area:392}或塞拉摩过来；部落术士则从{area:380}向南走。他要的是两个副本里的碎片：在去{area:2797}和{area:236}之前先接任务。",
}

G["forever/class/warlock/shard-of-the-green-flame"] = {
	["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "五十多级的稀有副手，来自{zone:1448}{npc:14469}和{npc:14470}，这个营地还提供小鬼的请求任务。",
	["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "达到 50 级后，{npc:14469} 和他的小鬼 {npc:14470} 会在 {zone:1448} 中部、{area:1997} 东北不远处的高地等你：从 {area:1765} 的桥向北走，经过几只软泥怪后，他们就在道路东侧。{npc:14469} 会让你去找身旁的 {npc:14470}，后者需要分别来自三处地点的三份无暇的恶魔精华。",
	["Back to {npc:14469}"] = "回到{npc:14469}那里",
	["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "返回{npc:14470}身边。他会给你{item:18626}：保留它，用来唤醒地狱火{npc:14467}。",
	["Kroshius"] = "克罗修斯",
	["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "地狱卫士哨兵（54 级）在 {zone:1419} 南部的 {area:72} 周围巡逻，每名都带着一只地狱猎犬。不要招惹 57 级的拉瑟莱克的仆从：没有它们对应的任务就无法杀死。",
	["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "雷加什萨特（51-53 级）占据 {zone:1447} 北部海岸的雷加什营地。各类萨特的精华掉率都是约四分之三；萨特会燃烧法力，唤魔者会施放火焰之雨，因此要逐个引来击杀。",
	["Warlock"] = "术士",
	["{area:1763} lies just south of {area:1997}, west of the road. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763}就在{area:1997}南面、道路西侧。两座洞穴中，{area:1770}是更靠北、位置更高的那座；另一座没有军团士兵。{area:1770}的隧道向北延伸到山丘下，加德纳尔军团士兵（55级）位于更深处的大厅，从第一段斜坡一直分布到{npc:9516}的房间；它们会对近战范围内的目标使用上勾拳。精华掉落概率为四分之三，但总共只有约11个刷新点：一路清进去，必要时等5分钟刷新。{area:1763}和{area:1770}的教徒全部敌对。",
	["{item:18626}, at {object:179677}"] = "{item:18626}，在{object:179677}",
	["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "{npc:14467} 的遗骸位于 {npc:14469} 北面的焦黑陨坑 {area:1766}：从他的营地沿道路北上，遗骸就在道路稍东侧。在遗骸旁使用 {item:18626}，等待他起身。{npc:14467} 是55级精英：建议组队；55级及以上的术士可以用恐惧配合持续伤害，或用奴役恶魔单独击败他，但火焰法术对他无效，而且他会击退你。如果你死亡，他会回满生命；他死后三分钟会再次出现。遗骸南面的水池附近有精英地狱火巡逻：把 {npc:14467} 拉远再打。他必定掉落核心。弄丢了 {item:18626}？放弃任务，再向 {npc:14470} 重新接受。",
}

G["forever/class/warlock/tome-of-sacrifice"] = {
	["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "60级的稀有副手，是{npc:14463}对你在{zone:1419}捕获{npc:12396}的报酬。",
	["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "60级时，{npc:14463} 在 {zone:1419} 西部、恶魔遍布的洼地 {area:73} 等候。那里到处都是攻击很痛的精英：先给自己绑好灵魂石，再贴着右侧墙壁进去，或者骑坐骑冲过去。{npc:14463} 会同时给你两项差事。",
	["Back to {npc:14463}"] = "回到{npc:14463}处",
	["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "把两样都交给 {npc:14463}，领取 {item:18601}。在 {area:73} 找一只落单的 {npc:12396}（61级精英），从约30码外让虚空行者攻击它，并对它引导监牢约20秒：它会攻击你以挣脱，{spell:45} 还可能打断引导，必要时牺牲虚空行者来获得护盾。建议组队：有另一位玩家扛住就很容易。引导完成后它会变成 {item:18605}：点击它。如果引导中断，就杀掉它或逃跑，再换一只尝试。",
	["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "赫达琳恶魔（57—60级精英）占据了 {zone:1452} 最南端的 {area:2256}：建议组队。过桥后的峡谷由两名屠杀者把守；西侧隧道通往更多新兵，它们是其中最容易对付的（小心它们的 {spell:7645}）。术士可以用恐惧或 {spell:710} 配合持续伤害逐只单杀，但速度较慢。这些恶魔都可能掉落眼泪，掉率约为五分之四。",
	["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "荒野萨特（55-57 级，精英）遍布 {area:2577} 东翼的扭木区：带上五人小队。大约每五只中有四只掉落一份血，但要两小时才会刷新，完整清一遍可能凑不齐十五份；重置后再来一次。{area:2518} 的后门需要 {item:18249}，钥匙就在这一区域掉落；队伍里有人拿到之前，从 {zone:1444} 中部的 {area:2577} 正门进入。",
	["Warlock"] = "术士",
	["{item:18601}, on a {npc:12396}"] = "对 {npc:12396} 使用 {item:18601}",
	["{item:18603}, from the Wildspawn inside"] = "{item:18603}，从内部的荒野系列敌人身上获得",
	["{item:18605}, click it"] = "{item:18605}，点击它",
}

G["forever/class/warrior/quelserrar"] = {
	["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "60级坦克剑：先在{area:2577}获得一本书，再用{npc:10184}的龙息淬炼剑刃（无限的物品中尚未加入此剑）。",
	["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "返回厄运之槌西区图书馆的 {npc:14368} 处：再次用 {item:18249} 从西区大门进入，并组队前往图书馆。",
	["Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit."] = "击杀 {npc:10184}，然后在 20 分钟耗尽前，选中她的尸体并对其使用 {item:18488}。它会变成 {item:18492}，不再有时间限制。",
	["Onyxia"] = "奥妮克希亚",
	["Raid"] = "团队副本",
	["Shen'dralar reputation"] = "辛德拉声望",
	["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "这本书由 {area:2577} 三个区域的首领随机稀有掉落（东区的奥兹恩、海多斯博恩及其他首领，西区的特迪斯、伊琳娜、卡雷迪斯、{npc:11496} 等，以及北区的 {npc:11501} 和卫兵），贡品箱也有极低概率开出；它可以交易，因此拍卖行可能有售。{area:2577} 是位于 {zone:1444} 中部废墟中的五人地下城：需要五人小队。右键点击书本开始任务；书会留在背包里。",
	["click the heated blade on the ground"] = "点击地面上加热过的剑刃",
	["from {item:18401}"] = "来自 {item:18401}",
	["{item:18488}, on her corpse"] = "{item:18488}，在她的尸体上",
	["{item:18489}: plant it in her breath"] = "{item:18489}：把它插在她的吐息中",
	["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} 是 {area:2159} 的 40 人团队首领，该洞穴位于 {zone:1445} 南部的 {area:511}；她每周刷新一次。先告知团队。战斗后期（生命值约剩 10-15%，她再次落地后），使用 {item:18489} 将剑插在她的火焰吐息路径上，通常是主坦克脚边。吐息加热剑后，点击 {object:179562}，取得 {item:18488}：从此时起你有 20 分钟。插剑或拾取时，她的吐息可能会杀死你；若你死亡，且她死前无人复活你，就只能等下周。插错位置了？放弃任务，再从莱德罗斯处重新接受，以取得一把新剑。",
	["{npc:10184}'s breath"] = "{npc:10184} 的吐息",
	["{npc:10184}'s corpse"] = "{npc:10184}的尸体",
	["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} 在厄运之槌西区最深处的图书馆“辛德拉圣殿”，需要经过上层精灵庭院和伊莫塔尔的牢笼。西区大门需要 {item:18249}，钥匙由厄运之槌东区的普希林掉落（他会逃跑，要追上），或者让潜行者开锁。清到图书馆需要五人小队。他会收下书，给你 {item:18513}，当场交回后再给你 {item:18489}。保留这把剑：丢了就只能放弃任务，重新接取。",
	["{npc:14368}, in the Athenaeum"] = "{npc:14368}，在图书馆内",
	["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368}：交还黯淡的精灵剑",
}

G["forever/class/warrior/voodoo-feathers"] = {
	["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{zone:1456}的战士训练师{npc:3041}会让你去{zone:1435}找{npc:7572}。",
	["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{object:172958}的{npc:3354}会让你去{zone:1435}找{npc:7572}。",
	["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{zone:1458}的一位战士训练师{npc:4593}会让你去{zone:1435}找{npc:7572}。",
	["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{zone:1455}的战士训练师{npc:5113}会让你去{zone:1435}找{npc:7572}。",
	["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{object:2100} 战士训练师建筑内、{npc:5480} 身旁的 {npc:5479} 会派你去 {zone:1435} 找 {npc:7572}。",
	["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "50级时，{zone:1457}的战士训练师{npc:7315}会让你去{zone:1435}找{npc:7572}。",
	["Back to the {npc:10996}"] = "回到{npc:10996}那里",
	["Experience"] = "经验",
	["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "50级时获取经验，最终前往{area:1417}；无限 可能已取消经典版的物品选择。",
	["Helboar"] = "地狱野猪",
	["Helboars"] = "{npc:5993}",
	["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "在经典旧世中，{npc:10996} 会在这里让你从 {item:20130}、{item:20521} 或 {item:20517} 中选择奖励。无限服的改动说明称已取消选择，但其任务页面仍列有三项未命名奖励：交还任务前先查看奖励窗口。",
	["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "七只地狱野猪（52-53级，非精英）在{zone:1419}西北部、{area:1438}西南方游荡；有些在路边山坡上的食人魔附近。它们会从25码外冲锋，并施放{spell:8349}。它们与地狱犬和蝎子共用刷新点：如果没有野猪，杀掉这些怪物，之后可能会刷出野猪。五分钟后刷新。",
	["Shadowsworn Adept"] = "暗影誓缚侍僧",
	["Shadowsworn Cultist"] = "暗影誓缚教徒",
	["Shadowsworn Thug"] = "暗影誓缚暴徒",
	["Shadowsworn camps"] = "魔誓营地",
	["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "誓死效忠者在{area:1440}洞口周围扎营，位于{area:1438}南面、通往{area:72}的路上。你需要击杀20名 魔誓专家（52-53级，会吸血并治疗受伤的同伴：优先击杀）、10名 魔誓祭司（51-52级，会远程投掷，要贴近）和20名 魔誓暴徒（52-53级，会痛击和{spell:1766}）。魔誓暴徒 可能比其他两种更难凑齐：沿途的誓死效忠者都要击杀。",
	["The {area:1417}"] = "{area:1417}",
	["The {npc:7572}"] = "{npc:7572}",
	["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "幽灵{npc:7572}站在{zone:1435}西南部通往{zone:1419}的山口，距{area:75}向西南骑行一小段路。部落：飞往{area:75}。联盟：飞往{zone:1419}的{area:1438}，向北骑行穿过山口。途中有高等级野兽游荡。",
	["Warrior"] = "战士",
	["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "需要从{area:1417}阳台上的六名阿塔莱巨魔守护者（51-52级，精英）身上取得每种颜色各两根羽毛，他们维持着{npc:5710}前方的屏障：加什尔和{npc:5716}必掉琥珀色，胡库和米杉必掉蓝色，祖罗和洛若尔必掉绿色；每个接了任务的玩家都能拾取自己的一套。{area:1417}是五人地下城：需要五人小队。它位于{zone:1435}东部的{area:74}：爬上神庙外部台阶，潜入被水淹没的大厅，沿楼梯向下到入口。进入后从楼梯或右侧道路前往阳台，不走螺旋楼梯。胡库会召唤守卫，并施放{spell:9081}和{spell:8282}；米杉会治疗其他守护者（{spell:139}、一个{npc:3560}，以及生命值低于一半时的{spell:331}）：尽快杀掉她或她的守护物；{npc:5716}会顺劈斩。",
	["{item:20606}, from Gasher and {npc:5716}"] = "{item:20606}，由加什尔和{npc:5716}掉落",
	["{item:20607}, from Hukku and Mijan"] = "从胡库和米杉处获取 {item:20607}。",
	["{item:20608}, from Zolo and Loro"] = "从祖罗和洛若尔处获取 {item:20608}。",
}

G["forever/class/warrior/whirlwind-weapon"] = {
	["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "30级时，{zone:1456}的战士训练师{npc:3041}会让你去{zone:1413}的{area:720}找{npc:6236}。",
	["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "30级时，{object:172958}的{npc:3354}会让你去{zone:1413}的{area:720}找{npc:6236}。",
	["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "30级时，{zone:1458}的一位战士训练师{npc:4595}会让你去{zone:1413}的{area:720}找{npc:6236}。",
	["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "30级时，{zone:1455}的战士训练师{npc:5113}会让你去{zone:1413}的{area:720}找{npc:6236}。",
	["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "30级时，{object:2100} 战士训练师建筑内、{npc:5480} 身旁的 {npc:5479} 会派你去 {zone:1413} 的 {area:720} 找 {npc:6236}。",
	["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "回到 {npc:6176} 处。接受 {quest:1713} 后他就会开始仪式，{quest:1712} 会出现在营地正北方。{quest:1712} 是40级精英：建议组队，需要两到三名40级左右的玩家。它会造成自然伤害（可以用 {item:6052} 吸收）、旋转攻击，并用 {spell:10101} 将你击飞很远；当你跑回来时，它会自行治疗：战斗时背靠山坡或岩石。{item:6894} 必定掉落。如果失败，{npc:6176} 就不再回应：放弃 {quest:1713} 再重接，即可重新召唤；不需要再次收集之前的物品。",
	["Big Will"] = "大个子威尔",
	["Bloodscalp Tusks"] = "血顶巨魔的獠牙",
	["Cyclonian"] = "塞克罗尼安",
	["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "飞往 {area:392}，再沿 {area:391} 南下。{area:720} 是东南近海的岛屿：沿浅水沙洲涉水过去；偏离沙洲后水很深，会开始出现疲劳。{npc:6236} 站在竞技场旁。",
	["Put the 24 charms into {object:89931}: it hands you the {quest:1714}."] = "把24个咒符放入{object:89931}：它会给你{quest:1714}。",
	["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite, and hit hard at 30-33: bring a friend or come at 35 or more. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "大锅需要每种咒符各 8 个，总共 24 个；每只流放者掉落对应咒符的概率约为三分之一，因此预计需要击杀约 70 只。它们都是 38-39 级的非精英怪，但对 30-33 级玩家伤害很高：带朋友来，或等到 35 级及以上。烈焰流放者（火）位于西北部的 {area:334} 旁、{area:320} 西北方；雷霆流放者（风）位于 {area:320} 东南方的 {area:336} 旁，会从 40 码外施放 {spell:403}；水浪流放者（水）位于 {area:321} 西北方的 {area:333} 旁，会使用 {spell:122}。每种约十二只，不到 7 分钟就会刷新。咒符可以交易，也能在拍卖行买卖；使用一种咒符可暂时放逐另一种流放者（烈焰对雷霆、雷霆对水浪、水浪对烈焰）。",
	["The exiles of Arathi"] = "阿拉希的流放者",
	["Warrior"] = "战士",
	["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "你有10分钟。先吃喝回满，再站到人群中央的栅格上：{npc:6248} 会宣布挑战者入场（26—27级），每次一名，间隔15—20秒，而且只有你站在栅格附近时才会出场。每杀一名，先走下栅格吃东西或打绷带；准备好迎接下一名再站回去。一共六名，之后 {npc:6238}（33级，非精英）会走出来；在你主动攻击前他会保持中立，因此先吃东西或打绷带。不要用 {spell:1160}：它会让挑战者逃跑，导致更多挑战者同时涌入。如果没有开始，先离开栅格再站上去，或放弃任务后重新接受。",
	["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "需要 30 根獠牙。荆棘谷西北部的所有血顶巨魔（33-37 级）都有约三分之一的概率掉落一根，预计要杀约 80 只：前往 {area:117} 北边和西北的营地及遗迹，以及海岸 {area:123} 周围。它们在生命值低于 30% 时会狂暴，战士还会缴械；5 分钟刷新。",
	["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "需要8株 {item:3357}。草药师可以在 {zone:1437}、{zone:1417} 和 {zone:1434} 的河流、湖泊旁采集；其他人可在拍卖行购买。草药商人每次只存一株，每两小时补货：{zone:1453} 的 {npc:1302} 和 {npc:1313}、艾尔文森林东部路上的 {npc:844}、石爪山脉 {area:460} 的基达，以及 {zone:1441} 的莫塔尔。荆棘谷北部的库尔森巫医也会掉落，概率约为十二分之一。",
	["{item:4479}, from Burning Exiles"] = "{item:4479}，由烈焰流放者掉落",
	["{item:4480}, from Thundering Exiles"] = "{item:4480}，由雷霆流放者掉落",
	["{item:4481}, from Cresting Exiles"] = "{item:4481}，由水浪流放者掉落",
	["{item:6894}, from {quest:1712}"] = "{item:6894}，来自{quest:1712}",
	["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {quest:1714} from his cauldron. Click the cauldron for that quest."] = "{npc:6176}在流经{area:272}的河流东岸废墟旁扎营，从镇子往东北走不远、刚过边界进入{zone:1416}即可找到；他的大锅就在旁边。部落飞往{area:272}。联盟飞往{area:271}，再沿河向北；{area:272}的守卫是42级精英，远离镇子。接受{quest:1712}可获得{item:6929}，上面列出他需要的材料：8个{item:3357}、30个血顶巨魔的獠牙，以及从大锅取得的{quest:1714}。点击大锅接受该任务。",
	["{npc:6176}: {item:6975}, Sword or Warhammer"] = "{npc:6176}：{item:6975}、剑或战锤",
	["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}，从 {npc:6176} 旁的锅中获得",
	["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "30级的{spell:2458}，以及40级的{spell:1680}斧、剑或战锤。",
}

G["forever/collectibles/mounts/neutral/deathcharger"] = {
	["Deathcharger"] = "死亡战马",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Stratholme {object:175461}"] = "斯坦索姆{object:175461}",
	["{area:2279} is a group of five, level 58-60. The {object:175461} at {object:175440}, in north-western {zone:1423}, leads to the undead side; {npc:10440} waits in the Slaughter House at its end. Our data gives the reins a 0.02% drop chance (pfQuest, Era): one in about five thousand kills. Nothing shows Forever changing it."] = "{area:2279}是五人小队地下城，58-60级。{zone:1423}西北部{object:175440}的{object:175461}通往亡灵区；{npc:10440}在尽头的屠宰场等着。我们的数据显示缰绳掉落率为0.02%（pfQuest，怀旧服）：大约五千次击杀掉一次。没有迹象表明无限 改动过。",
	["{item:13335} needs level 60 and Journeyman {skill:762} to ride (Forever client). Train it at your race's riding trainer; see the Level 60 mount guides."] = "{item:13335}需要60级和中级{skill:762}才能骑乘（无限 客户端）。在你种族的骑术训练师处学习；地点见60级坐骑指南。",
}

G["forever/collectibles/mounts/neutral/galestrider"] = {
	["20g"] = "20金",
	["Any race can buy Galestriders, but riding one also takes {spell:1285849}, which only the Skyborne get with {skill:762}. Other races can learn it too, but how is not known yet: in Classic another race's riding needed Exalted with its home faction, here the High Order (Alliance) or the Windshapers (Horde). Ask {npc:265756} before you buy."] = "任何种族都能购买疾风陆行鸟，但骑乘还需要 {spell:1285849}，只有天裔学习 {skill:762} 时会一并获得。其他种族也能学习，但具体方法尚不清楚：经典怀旧服要求对应种族主城声望崇拜；这里对应的是高阶会（联盟）或塑风者码头管理员（部落）。购买前先询问 {npc:265756}。",
	["Galestrider"] = "疾风陆行鸟",
	["Galestriders need level 40 and {skill:762}. Train it at your own race's riding trainer; see the Level 40 mount guides for where."] = "骑乘风行者需要 40 级和 {skill:762}。请向自己种族的骑术训练师学习；具体位置见 40 级坐骑指南。",
	["Learn to ride"] = "学习骑术",
	["Skyboat from {area:279}"] = "从{area:279}乘天空飞船",
	["Skyboat from {zone:1456}"] = "从{zone:1456}乘天空飞船",
	["Skyboat to {zone:2521}"] = "乘天空飞船前往{zone:2521}",
	["Skyborne learn {skill:762} from {npc:265756} himself for 100g, and it comes with a Galestrider. He stands at the {area:17684} in {area:16638}, near the skyboat docks."] = "天裔可直接花费 100 金币向 {npc:265756} 学习 {skill:762}，并同时获得一只风行者。他站在 {area:16638} 的 {area:17684}，靠近飞船码头。",
	["{npc:265756} is at the {area:17684} in {area:16638}, the island's harbour town, near the skyboat docks. The Forever client lists each Galestrider at 20g; choose one."] = "{npc:265756} 位于岛上港口城镇 {area:16638} 的 {area:17684}，靠近飞空艇码头。无限服客户端中每只疾风陆行鸟的标价为20金币；选一只即可。",
	["{npc:265756}, riding trainer"] = "{npc:265756}，骑术训练师",
	["{skill:762} with {npc:265756}"] = "向 {npc:265756} 学习 {skill:762}。",
	["{spell:1285849} for other races"] = "其他种族学习{spell:1285849}",
	["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521}是天裔的起始岛屿；任何人都可以前往。大约每五分钟有一艘天空飞船从{zone:1456}北边、{area:17045}南侧的悬崖出发（另一艘从{area:279}起飞；两个阵营都可以乘坐任意一艘）。如果你已经在岛上，跳过此步。",
	["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521}是天裔的起始岛屿；任何人都可以前往。大约每五分钟有一艘天空飞船从{area:279}北侧出发（另一艘从{zone:1456}北边起飞；两个阵营都可以乘坐任意一艘）。如果你已经在岛上，跳过此步。",
}

G["forever/collectibles/mounts/neutral/spectral-bear"] = {
	["55 Legacy Points"] = "55点传承点数",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, professions, PvP, exploring) is worth one, and every point the account earns counts here, spent or not. The Legacy Challenges guide plans them. The Progress Track gives the {item:281060} at 15, the {npc:268840} at 25, the {item:277717} at 40 and the reins at 55. Claim each one from {npc:6791} at the inn in {area:392}, on the {zone:1413} coast: he offers a \"Legacy Reward\" quest once you have the points."] = "传承点数为账号共享：每项传承挑战（某个职业达到25、45和60级，以及专业、PvP、探索等挑战）各值一点，账号获得的每一点都会计入这里，无论是否已经花掉。传承挑战指南可帮你规划。进度路线会在15点奖励 {item:281060}，25点奖励 {npc:268840}，40点奖励 {item:277717}，55点奖励缰绳。到 {zone:1413} 海岸 {area:392} 的旅店找 {npc:6791} 领取各项奖励：点数足够后，他会提供“传承奖励”任务。",
	["The bear runs at full speed: riding it needs level 60 and Journeyman {skill:762} (Forever client), from your race's riding trainer; see the Level 60 mount guides."] = "这只熊以全速奔跑：骑乘需要60级和中级 {skill:762}（无限服客户端），向本族骑术训练师学习；详见60级坐骑指南。",
	["from {npc:6791}"] = "由 {npc:6791} 掉落",
}

