G["forever/collectibles/mounts/neutral/warlock-dreadsteed"] = {
	["At 60 {npc:5520}, the demon trainer in the {object:2164}, sends you to {quest:7562} in the {zone:1428}."] = "60级时，{object:2164} 的恶魔训练师 {npc:5520} 会派你去找 {zone:1428} 的 {quest:7562}。",
	["At 60 {npc:5753}, the demon trainer in the {object:36082}, sends you to {quest:7562} in the {zone:1428}."] = "60级时，{object:36082} 的恶魔训练师 {npc:5753} 会派你去找 {zone:1428} 的 {quest:7562}。",
	["At 60 {npc:5815}, the demon trainer in the {object:172960}, sends you to {quest:7562} in the {zone:1428}."] = "60级时，{object:172960} 的恶魔训练师 {npc:5815} 会派你去找 {zone:1428} 的 {quest:7562}。",
	["At 60 {npc:6382}, the demon trainer in {zone:1455}, sends you to {quest:7562} in the {zone:1428}."] = "60级时，{zone:1455}的恶魔训练师{npc:6382}会派你去{zone:1428}找{quest:7562}。",
	["Back to {npc:14436}: he gives you the {item:18591} for {npc:14437} beside him. Then {npc:14436} asks for the bell, the wheel and the candle, and {npc:14437} sends you to {quest:7623} in {area:1763}: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after {npc:14523}, and a spare in case one runs out) and bring 150 gold for the stardust."] = "返回{npc:14436}处：他会给你{item:18591}，让你交给旁边的{npc:14437}。然后{npc:14436}会索要铃铛、车轮和蜡烛，{npc:14437}则让你去{area:1763}做{quest:7623}：为这趟行程向他购买3瓶暗影药水（每瓶6金币：一瓶用于进入，一瓶在见过{npc:14523}后使用，另备一瓶以防效果耗尽），并带150金币购买星尘。",
	["Back to {npc:14437} with the stardust; with the {quest:7630} also done he gives you the {item:18688} for the {area:2057}. Put a group of five together now: a party, not a raid group."] = "带着星尘返回{npc:14437}处；如果也完成了{quest:7630}，他会给你前往{area:2057}所需的{item:18688}。现在组一个五人小队：必须是小队，不能是团队。",
	["Back to {npc:14437}, then {npc:14436} hands you his instructions. Buy {item:18663} (150 gold), the {item:18629} (50) and the {item:18670} (50) from {npc:14437}; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards."] = "回到{npc:14437}处，然后{npc:14436}会给你说明。向{npc:14437}购买{item:18663}（150金币）、{item:18629}（50金币）和{item:18670}（50金币）；也可以让已经拥有这些物品的术士朋友带来。每位负责为节点充能的其他术士都需要自备一块磁石。携带至少15块灵魂碎片。",
	["Every owlbeast of {zone:1452} (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. {area:2250}, in the north-east, and the {area:2242}'s surroundings are packed with them, and they respawn in five and a half minutes."] = "{zone:1452}的所有枭兽（53-58级，均非精英）都有约三分之一概率掉落血液：收集30份约需击杀90只。东北面的{area:2250}和{area:2242}周围分布密集，刷新时间为5分半。",
	["Hand the three pieces to {npc:14437}. He then wants 3 Arcanite Bars for the {item:18629}: alchemists transmute them (an {item:12363} and a {item:12359} each, on a long cooldown); everyone else buys them."] = "将三块碎片交给{npc:14437}。接着他需要3块奥金锭来制作{item:18629}：炼金师可以转化（每块需要一个{item:12363}和一个{item:12359}，冷却时间很长）；其他人直接购买。",
	["Immol'thar"] = "伊莫塔尔",
	["Into Dire Maul West"] = "进入厄运之槌西区。",
	["Stand on the dais and use {item:18663}: {npc:14500} sets out the Bell, the Wheel and the Candle. The Bell heals warlocks, the Wheel shields the party, the Candle burns the imps: ignore the imps and kill the Dread Guards (elite felguards, about ten, sometimes two at once); Banish or Enslave helps. Give one player each node to watch: when one sags, tilts and sounds, a warlock with a Lodestone recharges it, a 3-second cast that any hit breaks (a {item:6265} each), so keep attackers off them. If all three fail, the ritual ends and you start again; while one stands it survives even a wipe. After about six minutes nine symbols glow and a red vortex closes the circle: walk out and the remaining demons vanish at its edge. Rest, then use the {item:18670}. Kill the {npc:14502} (level 62, elite); at half health {npc:14506} joins, a hard hitter who knocks you back. Speak to the {npc:14504}: every warlock in the party who is on this quest can bind it."] = "站在高台上使用 {item:18663}：{npc:14500} 会摆出铃、轮盘和蜡烛。铃会治疗术士，轮盘保护小队，蜡烛灼烧小鬼：不用管小鬼，专心击杀恐惧守卫（精英恶魔卫士，约十只，有时会同时来两只）；放逐或奴役会有所帮助。每个装置安排一名玩家看守：装置下沉、倾斜并发出声音时，需要由带着磁石的术士重新充能，施法3秒，受到任何攻击都会中断（每次消耗一个 {item:6265}），因此要挡住攻击者。三个装置全部失效，仪式就会结束，必须重来；只要还有一个正常运作，即使全灭也能维持。大约六分钟后，九个符文亮起，一道红色漩涡封闭法阵：走出去，剩下的恶魔会在边缘消失。休整后使用 {item:18670}。击杀 {npc:14502}（62级精英）；生命值降到一半时，{npc:14506} 会加入战斗，他攻击很重，还会击退你。与 {npc:14504} 交谈：队里所有正在做这个任务的术士都可以与其缔结契约。",
	["The ritual"] = "仪式",
	["The ritual pieces"] = "仪式物品",
	["The {area:2057}"] = "{area:2057}",
	["The {area:2057} (level 58-60, a group of five) lies under {area:2298}, the island town in the south-east of the {zone:1422}: someone needs the {item:13704} or a rogue to open the door. Fight down to {npc:10508}'s room and use the {item:18688} at the alchemy lab tables to the right: {npc:14500} makes the parchment. You need not kill Ras, but it only counts at this lab and only in a party."] = "{area:2057}（58-60级，五人小队）位于{zone:1422}东南方岛上城镇{area:2298}的地下：需要有人带{item:13704}，或由盗贼开门。一路打到{npc:10508}的房间，在右侧炼金实验室的桌旁使用{item:18688}：{npc:14500}会制作卷轴。不必杀死莱斯，但只有在这间实验室、且身处小队中才算完成。",
	["Ulathek"] = "乌拉泰克",
	["Use the {item:18688} at the alchemy lab inside"] = "在里面的炼金实验室使用{item:18688}",
	["Warlock"] = "术士",
	["Warlock Dreadsteed"] = "术士恐惧战马",
	["Xorothian Dreadsteed"] = "克索诺斯恐惧战马",
	["Your epic mount at 60, summoned anywhere: no epic horse to buy and no 1,000g Journeyman Riding needed."] = "60级的史诗坐骑，随处可召唤：无需购买史诗战马，也无需花1,000g学习中级骑术。",
	["he gives you the {item:18591}"] = "他会给你{item:18591}",
	["{area:1763} lies just south of {area:1997} in western {zone:1448}, west of the road; of its two caves, {area:1770} is the northern one, further up the hill. Drink a {item:18802} at its mouth: for 20 minutes the Shadow Council there treat you as one of their own ({spell:23179}). The oozes in the red pool and the succubus Rakaiah beyond them still attack: hug the wall past them. Go down past the second, red pool, up the ramp and across two bridges to {quest:7623}, a great winged dreadlord at the back. He talks to you only while the potion lasts."] = "{area:1763} 位于 {zone:1448} 西部、{area:1997} 南面不远处，在道路西侧；这里有两个洞穴，{area:1770} 是北面的那个，位置更高。在洞口喝一瓶 {item:18802}：接下来的20分钟里，那里的暗影议会会将你视为自己人（{spell:23179}）。红色水池里的软泥怪和后面的魅魔拉凯雅仍会攻击：贴墙绕过它们。向下经过第二个红色水池，再上坡，过两座桥，到最深处找 {quest:7623}，他是一位长着巨大翅膀的恐惧魔王。只有药水生效时，他才会与你交谈。",
	["{area:2577} stands in the ruins of central {zone:1444}: from the gate at the foot of the ruins, walk up through the outer courtyards to the west wing's door at the north end. That door and an inner door need the {item:18249} (it drops from Pusillin in Dire Maul East) or a rogue with 300 Lockpicking. Bring a party of five. Lower {npc:11496}'s shield by killing the guardians of the five pylons (two stand in his own room), then kill {npc:11496}: his dais is the summoning circle. Rest and rebuff before you start."] = "{area:2577}位于{zone:1444}中部的废墟中：从废墟脚下的大门进入，穿过外围庭院向上走，到北端的西翼门口。这扇门和内部另一扇门需要{item:18249}（厄运之槌东区的普希林掉落），或开锁技能300的盗贼。带上五人小队。击杀五座水晶塔的守卫（其中两座在他自己的房间里），解除{npc:11496}的护盾，再击杀{npc:11496}：他的高台就是召唤法阵。开始前先休息并补齐增益。",
	["{item:12360}: the Auction House"] = "{item:12360}：从拍卖行购买",
	["{item:14344}: the Auction House"] = "{item:14344}：从拍卖行购买",
	["{item:18629}, 50 gold"] = "{item:18629}，50 金",
	["{item:18663}, 150 gold"] = "{item:18663}，150 金",
	["{item:18663}, on {npc:11496}'s dais"] = "{item:18663}，在{npc:11496}的高台上使用",
	["{item:18670}, 50 gold"] = "{item:18670}，50 金",
	["{item:18670}, once the circle is complete"] = "法阵完成后使用 {item:18670}。",
	["{item:18687}, from {npc:14522}"] = "{item:18687}，来自{npc:14522}",
	["{item:18802}, from {npc:14437}"] = "{item:18802}，来自{npc:14437}",
	["{item:9264}: the Auction House"] = "{item:9264}：从拍卖行购买",
	["{npc:11496}, inside the west wing"] = "{npc:11496}，在西区内部",
	["{npc:14437} wants 10 Elixirs of Shadow Power ({skill:171}: 3 Ghost Mushrooms and a {item:8925} each), 6 Large Brilliant Shards ({skill:333}: disenchant level 51+ blue items), 25 {item:11370} ({skill:186} 230: the Dark Iron Deposits of the {zone:1428} and {area:1584}) and 35 Black Dragonscales ({skill:393}: the black dragonkin of the {zone:1428}, a few percent a kill, best from the {npc:7043}). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales."] = "{npc:14437} 需要10瓶暗影之力药剂（{skill:171}：每瓶需3个幽灵菇和一个 {item:8925}）、6块大块魔光碎片（{skill:333}：分解51级以上的蓝色物品）、25块 {item:11370}（{skill:186} 230：来自 {zone:1428} 和 {area:1584} 的黑铁矿脉），以及35片黑龙鳞片（{skill:393}：来自 {zone:1428} 的黑龙类，每只掉率为百分之几，最适合刷 {npc:7043}）。能用自己专业制作或采集的就自己解决，其余去拍卖行买；凑齐35片鳞片可能要花些时间。",
	["{npc:14522}, beside {quest:7623}, sells the {item:18687} for 150 gold. He deals with you only while a {item:18802} is active."] = "{quest:7623} 身旁的 {npc:14522} 以150金币出售 {item:18687}。只有在 {item:18802} 生效期间，他才会与你交易。",
	["{npc:14523} waits in a small side room up a bridge you passed on the way down. Speak to him and he and four guards attack (all level 57, none elite): let your voidwalker hold the guards and burn {npc:14523}, sacrificing it if you must. Or click off your {spell:23179} aura to start the fight, kill {npc:14523}, then drink another potion: the guards stop at once. Take his heart back to {npc:9516} with a potion active."] = "{npc:14523}在一座桥上方的小侧室里，你下行时经过了那座桥。与他交谈后，他和四名守卫会攻击你（全部57级，均非精英）：让虚空行者抗住守卫，集中火力击杀{npc:14523}，必要时牺牲虚空行者。也可以点掉{spell:23179}光环来开战，杀死{npc:14523}，然后再喝一瓶药水：守卫会立刻停手。在药水生效时，将他的心脏带回{npc:9516}处。",
	["{quest:7562} and his goblin {npc:14437} camp on the hill across the road from the {area:255}, in the far north-west of the {zone:1428}, west of {area:254}. The chain is long: about 420 gold in {npc:14437}'s and {npc:14522}'s goods, a pile of crafted materials, the {area:2057} and {area:2577}. Start buying or gathering the materials of the next steps now."] = "{quest:7562} 和他的地精 {npc:14437} 驻扎在 {zone:1428} 最西北、{area:254} 西边，隔路面对 {area:255} 的山坡上。任务链很长：需要购买 {npc:14437} 和 {npc:14522} 出售的货物，共约 420 金币，还要大量制造材料，并进入 {area:2057} 和 {area:2577}。现在就开始购买或收集后续步骤的材料。",
	["{quest:7625}, from {npc:14522}"] = "{quest:7625}，由 {npc:14522} 提供",
}

G["forever/collectibles/mounts/neutral/warlock-felsteed"] = {
	["At 40 {npc:3326}, in the {object:172960}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40 级时，{object:172960} 内的 {npc:3326} 会让你去 {area:392} 找 {npc:6251}。没有任务可接？先完成地狱猎犬任务链：玩家反映坐骑任务会在它之后开放。",
	["At 40 {npc:4563}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}; {area:392} is a short flight from {zone:1454}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40 级时，{object:36082} 内的 {npc:4563} 会让你去 {area:392} 找 {npc:6251}。从 {zone:1420} 出发的飞艇飞往 {zone:1411}；从 {zone:1454} 飞到 {area:392} 只需很短时间。没有任务可接？先完成地狱猎犬任务链：玩家反映坐骑任务会在它之后开放。",
	["At 40 {npc:461}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40级时，{object:2101}的{object:2164}地下室里的{npc:461}会让你去找{area:392}的{npc:6251}。没有任务可接？先完成地狱猎犬任务链：玩家报告说坐骑任务在那之后才开放。",
	["At 40 {npc:5172}, by the warlock trainers in {zone:1455}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "40 级时，{zone:1455} 术士训练师旁的 {npc:5172} 会让你去 {area:392} 找 {npc:6251}。没有任务可接？先完成地狱猎犬任务链：玩家反映坐骑任务会在它之后开放。",
	["Warlock"] = "术士",
	["Warlock Felsteed"] = "术士地狱战马",
	["Your own mount at 40, summoned anywhere: no 100g riding training needed."] = "40级时获得你自己的坐骑，随处召唤：无需花100金学习骑术。",
	["{area:392} is the goblin port on the {zone:1413} coast, east of the Crossroads; from the Alliance side take the boat from {area:35}. {npc:6251} stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own {quest:3631} and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing."] = "{area:392}是{zone:1413}海岸的地精港口，在十字路口以东；联盟从{area:35}坐船前往。{npc:6251}站在镇子上方山丘的小塔旁，不在下面的码头。交完任务，再接他提供的{quest:3631}并直接交回，即可学会坐骑。无需战斗，任务也不要求任何物品。",
	["{area:392} is the goblin port on the {zone:1413} coast, east of the {area:380}; from the Alliance side take the boat from {area:35}. {npc:6251} stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own {quest:3631} and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing."] = "{area:392}是{zone:1413}海岸上的地精港口，位于{area:380}以东；联盟一方从{area:35}坐船过去。{npc:6251}站在镇上山丘的小塔旁，不在下面的码头。先交任务，再接他自己的{quest:3631}并立刻交回：那会教你召唤坐骑。无需战斗，任务也不要任何物品。",
	["{npc:6251} in {area:392}"] = "{area:392}的{npc:6251}",
}

G["forever/collectibles/pets/baby-crocolisk"] = {
	["The {npc:3581} is a rare level 50 crocolisk, much tougher than a normal mob of its level. It swims {zone:1453}'s canals and appears at one of six spots, about two hours after it last died; the arrow takes you round them. Below 60, bring a group; at 60, a well-geared character can try it alone. It drops the {item:282047} about once in 70 kills, and the pet binds when picked up, so the Auction House never has it. Horde players can farm it too, but inside an enemy capital."] = "{npc:3581} 是一只50级稀有鳄鱼，比同级普通怪物强得多。它在 {zone:1453} 的运河里游动，上次死亡约两小时后会在六个位置之一出现；箭头会带你逐个查看。未到60级时请组队；60级且装备较好的角色可以尝试单杀。{item:282047} 的掉率约为七十分之一，而且宠物拾取后绑定，因此拍卖行不会有售。部落玩家也能刷，但需要进入敌方主城。",
}

G["forever/collectibles/pets/bitter-baitling"] = {
	["1 {item:274026}"] = "1个{item:274026}",
	["Back to {npc:15077}"] = "返回{npc:15077}处",
	["Hurry back and hand the 40 Tastyfish to {npc:15077}: the first players to do so win, and the winners get the coin with their prize. If you are too late to win, {npc:15078} still pays a little gold for every 5 Tastyfish."] = "尽快返回，将 40 条可口鱼交给 {npc:15077}：最先完成的玩家获胜，获胜者会随奖品一起得到硬币。如果来不及获胜，{npc:15078} 仍会按每 5 条可口鱼支付少量金币。",
	["Schools of Tastyfish"] = "可口鱼群",
	["The winner's coin, from {npc:15077}"] = "胜者的硬币，来自 {npc:15077}",
	["The {item:276275} costs one {item:274026}, the prize for winning the Stranglethorn Fishing Extravaganza. The contest runs on Sundays from 2 to 4 pm server time: be on the {area:35} docks when it starts and take {quest:8193} from {npc:15077}. Bring your best {skill:356} skill and lures so no fish gets away, a mount and empty bags, and bind your hearthstone in {area:35}."] = "{item:276275}需要一个{item:274026}兑换，后者是赢得荆棘谷钓鱼大赛的奖励。比赛时间为服务器时间每周日下午2点到4点：开始时到{area:35}码头，向{npc:15077}接受{quest:8193}。尽量提高{skill:356}技能并带上鱼饵，避免鱼逃脱；带上坐骑、腾空背包，并将炉石绑定在{area:35}。",
	["While the contest runs, schools of {item:19807} appear along the Stranglethorn coast, none inside {area:35}. Fish 40 {item:19807} from them; each school lasts only a few casts, so ride on to the next as soon as one is gone. The arrow takes you up the west coast north of {area:35}; more schools lie further north and just south of {area:35}."] = "比赛期间，荆棘谷海岸沿线会出现{item:19807}鱼群，{area:35}里面没有。从鱼群钓取40条{item:19807}；每个鱼群只能钓几竿，消失后立即骑马寻找下一个。箭头会带你沿{area:35}北面的西海岸向北走；更北面以及{area:35}正南面还有更多鱼群。",
	["{npc:15077}, during the contest"] = "{npc:15077}，比赛期间",
	["{npc:15078}, {npc:15077}'s apprentice, stands beside him on the {area:35} docks and trades the {item:276275} for the coin."] = "{npc:15077} 的学徒 {npc:15078} 站在他旁边的 {area:35} 码头上，可以用硬币兑换 {item:276275}。",
}

G["forever/collectibles/pets/condor-hatchling"] = {
	["{npc:14268} is a rare level 15-16 condor in south-eastern {zone:1432}. He appears at one of four spots, hours after he last died; the arrow takes you round them. He drops the {item:282637} only about once in 500 kills, so this is a pet for players who pass through {zone:1432} often: check his spots each time, and kill him whenever you see him."] = "{npc:14268} 是 {zone:1432} 东南部的一只 15-16 级稀有秃鹫。死亡数小时后，它会在四个刷新点之一出现；箭头会带你逐点查看。{item:282637} 的掉率只有约五百分之一，因此这只宠物适合经常经过 {zone:1432} 的玩家收集：每次都查看刷新点，见到它就杀。",
}

G["forever/collectibles/pets/dark-whelpling"] = {
	["Black whelps"] = "黑色雏龙",
	["The Searing Whelps of the {area:511} in southern {zone:1445} (level 42-43) and the Scalding Whelps of eastern {zone:1418} (level 41-43) drop it about once in 900 kills. The waypoint is the {area:511}, where the whelps stand thickest; the {zone:1418} whelps are the same grind. The whelpling can be traded, so the Auction House may be quicker."] = "{zone:1445}南部{area:511}的灼热雏龙（42-43级）和{zone:1418}东部的滚烫的雏龙（41-43级）约每击杀900只掉落一次。路径点设在雏龙最密集的{area:511}；在{zone:1418}刷雏龙也同样费工夫。雏龙宠物可以交易，因此拍卖行可能更快。",
	["The {area:511}"] = "{area:511}",
}

G["forever/collectibles/pets/disgusting-oozeling"] = {
	["Oozes"] = "软泥怪",
	["Oozes drop the {item:20768} about once in 20-30 kills; the best are the Vile Slimes, Devouring Oozes and the {npc:12387} in the ooze field of eastern {zone:1422} (level 54-57). Open every bag: most hold potions or herbs, and only about one bag in 50 holds the {item:20769}, so expect over a thousand kills. Both the bags and the pet can be traded: unopened bags on the Auction House are lottery tickets, the pet itself the sure buy."] = "软泥怪大约每击杀 20-30 只会掉落一个 {item:20768}；最佳目标是 {zone:1422} 东部软泥怪聚集地的可憎的软泥怪、吞噬淤泥怪和 {npc:12387}（54-57 级）。每个袋子都要打开：大多数装的是药水或草药，只有约五十分之一的袋子装有 {item:20769}，因此预计要击杀上千只。袋子和宠物都可以交易：拍卖行未打开的袋子如同彩票，直接买宠物才是稳妥的办法。",
	["Open your Oozing Bags"] = "打开你的沾满淤泥的袋子",
}

G["forever/collectibles/pets/flik"] = {
	["Darkmoon Faire Frogs"] = "暗月马戏团青蛙",
	["{item:11026}, 1g"] = "{item:11026}，1金",
	["{item:11027}, 1g"] = "{item:11027}，1金",
	["{npc:14860} at the Darkmoon Faire"] = "暗月马戏团的{npc:14860}",
	["{npc:14860} sells two frogs (1g each) while the Darkmoon Faire is in town; Forever has not shown the Faire yet. In Classic it sets up south of {area:87} in {zone:1429} one month and near {zone:1456} in {zone:1412} the next; go to whichever is up. {npc:14860} runs all over the Faire grounds, so look around for him. He carries only one {item:11027} at a time and restocks it about every 30 minutes: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "暗月马戏团来到当地时，{npc:14860} 会出售两种青蛙（每种 1 金币）；无限目前尚未出现马戏团。在经典旧世中，马戏团一个月在 {zone:1429} 的 {area:87} 南侧，次月则在 {zone:1412} 的 {zone:1456} 附近；去当前开放的那一处。{npc:14860} 会在马戏团场地内四处跑动，需要找一找。他一次只有一个 {item:11027}，约每 30 分钟补货：没货就说明刚被人买走。使用每个宠物物品后即可学会召唤对应的小伙伴；之后目标仍会保持勾选。",
}

G["forever/collectibles/pets/green-wing-macaw"] = {
	["Defias Pirates, on the ship"] = "船上的迪菲亚海盗",
	["{area:1581} is a group of five at level 17-26, under {area:20}: go in at the {area:20} mine and follow the tunnel down to the instance portal. The Defias Pirates (elite, level 19-20) on and around the ship at the far end drop the macaw about once in 30 kills, so plan on several runs; a character well past the dungeon's level clears it alone. The cage can be traded: look at the Auction House too."] = "{area:1581}位于{area:20}下方，适合17-26级的五人小队：从{area:20}矿洞进入，沿隧道下行到副本传送门。最深处船上及周围的迪菲亚海盗（精英，19-20级）约每击杀30名掉落一只金刚鹦鹉，预计要多刷几次；等级远高于地下城的角色可以单刷。鸟笼可以交易，也看看拍卖行。",
	["{area:1581} portal, at the bottom of the mine"] = "{area:1581}传送门，位于矿井底部",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
	["{area:1581}: Defias Pirates"] = "{area:1581}：迪菲亚海盗",
}

G["forever/collectibles/pets/hyacinth-macaw"] = {
	["Bloodsail camp, the {area:43}"] = "血帆营地，{area:43}",
	["Bloodsail pirates"] = "血帆海盗",
	["Every Bloodsail pirate on the Stranglethorn coast (level 39-45) can drop it, but only about once in 5,000 kills; the Swabbies on the ships off the southern tip, about once in 2,500. That is a grind of many hours, so most players kill pirates while doing something else there, or buy the cage on the Auction House. The waypoint is the Swashbucklers' and Warlocks' camp on the {area:43}, south of {area:35}. Every pirate kill also lowers your Bloodsail Buccaneers standing."] = "荆棘谷海岸的所有血帆海盗（39-45级）都有可能掉落，但概率仅约为5,000只出一个；最南端外海船上的水手约为2,500只出一个。需要刷很多小时，因此大多数玩家会在当地做其他事情时顺便杀海盗，或直接在拍卖行买鸟笼。路径点位于{area:35}南方{area:43}的流氓和术士营地。每杀一名海盗都会降低你的血帆海盗声望。",
}

G["forever/collectibles/pets/lil-timmy"] = {
	["Horde players buy the {npc:7386} (60s) from {npc:262471}, a trader new in Forever, at {area:2539}, the Darkspear camp at the southern tip of {zone:1442}, on the way up from the {zone:1413}. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "部落玩家从{npc:262471}处购买{npc:7386}（60银）。他是无限新增的商人，位于{area:2539}，即{zone:1442}南端的暗矛营地，从{zone:1413}上来的路上。每件宠物物品在使用时都会教会对应的伙伴；之后该目标仍保持打勾。",
	["{item:8489}, 60s"] = "{item:8489}，60银",
	["{npc:8666} sells the {npc:7386} (60s). He starts at {object:2098} and walks through the {object:2096}, {object:2100} and the {object:28027} before he vanishes near the square again; if he is not around, wait for him at {object:2098}. By beta reports he carries one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "{npc:8666}出售{npc:7386}（60银）。他从{object:2098}出发，经过{object:2096}、{object:2100}和{object:28027}，随后又在广场附近消失；如果没找到，就在{object:2098}等他。根据测试服玩家反馈，他每次只带一只小猫：如果没货，就是刚被别人买走。使用每个宠物物品即可学会召唤对应伙伴；之后目标会保持勾选。",
}

G["forever/collectibles/pets/magus-tirth"] = {
	["{item:11023}, 1g"] = "{item:11023}，1金",
	["{npc:6548} at the {area:2240}, the goblin and gnome racetrack in the {area:439} of south-eastern {zone:1441}, sells the {item:11023} (1g) to both sides. The nearest flight paths are {area:484} (Horde) and {area:976} in {zone:1446} (both sides); from {area:976}, ride north into the {area:439}. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "{npc:6548}在{area:2240}向双方阵营出售{item:11023}（1金币）；那里是{zone:1441}东南部{area:439}中的地精与侏儒赛车场。最近的飞行点是{area:484}（部落）以及{zone:1446}的{area:976}（双方均可）；从{area:976}骑马向北进入{area:439}即可。使用每个宠物物品都会学会对应的小伙伴；之后目标会保持勾选。",
}

G["forever/collectibles/pets/mechanical-chicken"] = {
	["Each robot starts with a distress beacon that mobs in its zone drop, about one kill in 40 to 100 in Classic's data. In {zone:1444} the best are the Coast Crawl Snapclaws and Deepseers (levels 43-45) on the {area:1108} and the Sprite Dragons (47-48), about 2.5%; ogres, harpies, naga and Grimtotems drop it about 1%. You can loot it from level 40."] = "每个机器人的任务都始于一枚求救信号器，由所在地区的怪物掉落，经典版数据中的概率约为40到100只出一个。{zone:1444}最适合刷的是{area:1108}的海滩利爪龙虾人和海滩龙虾人先知（43-45级），以及精龙（47-48级），掉率约2.5%；食人魔、鹰身人、纳迦和恐怖图腾的掉率约为1%。40级起就能拾取。",
	["Escort OOX-09/HL"] = "护送自动导航机器人OOX-09/HL",
	["Escort OOX-17/TN"] = "护送自动导航机器人OOX-17/TN",
	["Escort OOX-22/FE"] = "护送自动导航机器人OOX-22/FE",
	["Most {zone:1425} mobs drop OOX-09/HL's beacon about once in 100 kills: Silvermane wolves, owlbeasts, Highvale elves, Witherbark and Vilebranch trolls. You can loot it from level 43."] = "{zone:1425} 的大多数怪物约每击杀100只掉落一次 OOX-09/HL 的定位器，包括银鬃狼、枭兽、高原 精灵、枯木巨魔和邪枝巨魔。43级起可拾取。",
	["OOX-09/HL waits on the largest island of the lake west of {area:351}. Its escort to the shore beyond Overlook Cliff has two ambushes of three: Marauding Owlbeasts, then Vilebranch Ambushers; the robot warns you just before each."] = "OOX-09/HL 在 {area:351} 西边湖中最大的岛上等候。护送它到望海崖另一侧的岸边时，会遭遇两次伏击，每次三只：先是狂暴的枭兽，再是邪枝伏击者；每次伏击前机器人都会提醒你。",
	["OOX-17/TN stands in the hills near the {area:981} in south-east {zone:1446}. Its escort to {area:977} has two ambushes: three scorpids near the start, three Wastewander bandits near the end. The robot has about 3,000 health and stops to fight what you attack, so it can tank for a moment while you recover. Its turn-in is in {area:35} too."] = "OOX-17/TN 位于 {zone:1446} 东南、{area:981} 附近的山中。护送到 {area:977} 的途中有两次伏击：开始不久遇到三只蝎子，快到终点时遇到三名废土强盗。机器人约有 3,000 生命值，会停下与你攻击的敌人交战，所以你恢复时它能暂时扛一下。这个任务同样在 {area:35} 交还。",
	["Rescue OOX-09/HL"] = "营救自动导航机器人OOX-09/HL",
	["Rescue OOX-17/TN"] = "营救自动导航机器人OOX-17/TN",
	["Rescue OOX-22/FE"] = "营救自动导航机器人OOX-22/FE",
	["Right-click the beacon. OOX-22/FE sits in a cave near {area:1105}, among yetis and apes. Its escort runs west along the road to the dock on the {area:1108} with three ambushes: three yetis, then three gorillas, then four or five gnolls with a caster. Bring a friend if you are under 47. The robot keeps walking unless it is hit, so stay close; if it will not move, another player has it: wait for it to come back. Its turn-in is in {area:35}; keep the quest for later."] = "右键点击定位器。OOX-22/FE 在 {area:1105} 附近的洞穴中，周围是雪人和猿。护送路线沿道路向西，到 {area:1108} 的码头，途中有三次伏击：先是三只雪人，再是三只大猩猩，最后是四五只豺狼人，其中有施法者。低于 47 级就带位朋友。机器人只要没被攻击就会一直走，注意跟紧；如果它不肯动，说明其他玩家正在护送，等它回来。任务在 {area:35} 交还，先留着以后再交。",
	["{item:8623} in {zone:1446}"] = "{zone:1446}的{item:8623}",
	["{item:8704} in the {zone:1425}"] = "{zone:1425}的{item:8704}",
	["{item:8705} in {zone:1444}"] = "{zone:1444}的{item:8705}",
	["{npc:7406} in {area:35}"] = "{area:35}的{npc:7406}",
	["{npc:7406} is in {area:35}, upstairs in the building north of the inn, above {npc:2490}. Hand in all three rescues; at level 45 he then offers {quest:3721}, which you turn straight back in for the {item:10398}."] = "{npc:7406} 在 {area:35}，旅店北面建筑的楼上，位于 {npc:2490} 上方。交还全部三次营救任务后，到45级时他会提供 {quest:3721}，接到后立即交还即可获得 {item:10398}。",
	["{zone:1446} mobs drop OOX-17/TN's beacon about one kill in 50 to 150. Best: the Treasure Hunting Pirates and Buccaneers on the south shore (44-45) and the Ground Pounders in the north (41-43), about 2%. You can loot it from level 43."] = "{zone:1446} 的怪物掉落 OOX-17/TN 定位器的概率约为每 50 至 150 次击杀一次。最佳目标：南岸的寻宝海盗和海盗（44-45 级），以及北部的震地者（41-43 级），掉率约 2%。43 级起可拾取。",
}

G["forever/collectibles/pets/minimule"] = {
	["1,500 Merchant's Favor"] = "1,500 商人青睐",
	["Azeroth Commerce Authority"] = "艾泽拉斯贸易局",
	["Durotar Supply and Logistics"] = "杜隆塔尔补给后勤部",
	["Minimule"] = "迷你骡",
	["The Alliance camp is at {area:1002} in western {zone:1433}. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to {npc:214101}, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with the Azeroth Commerce Authority. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there."] = "联盟营地位于 {zone:1433} 西部的 {area:1002}。商人青睐来自10级起怪物掉落的遭劫的板条箱：按箱上清单填入一组所需物资，再交给 {npc:214101}，每箱获得5至30点商人青睐。零食需要1,500点商人青睐，且根据测试版商人清单，还要求与艾泽拉斯贸易局达到崇敬。箱子不提供声望：声望来自工匠文书，从中立到崇敬需要21,000点。补给阵营声望指南可带你达成。",
	["The Horde camp is just outside the west gate of the Crossroads. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another {npc:256384} stands in the {zone:1458}; this is the one at the camp.)"] = "部落营地就在十字路口西门外。商人青睐来自10级起怪物掉落的遭劫的板条箱：按箱子列出的要求装入一批物资，再交给多基米，每箱获得5至30点商人青睐。零食需要1,500点商人青睐，按测试版商人列表，还需要杜隆塔尔补给后勤部声望达到崇敬。板条箱不给声望：声望来自工匠文书，从中立到崇敬共需21,000点。补给阵营声望指南会带你完成。（{zone:1458}还有另一名{npc:256384}；这里指的是营地里的那名。）",
	["The Horde camp is just outside the west gate of the {area:380}. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another {npc:256384} stands in the {zone:1458}; this is the one at the camp.)"] = "部落营地就在{area:380}西门外。商人的恩惠来自10级起怪物掉落的被劫的板条箱：按箱内列出的包裹装满一箱，交给多基米，每箱可得5到30点恩惠。该零食用1,500点恩惠购买；据测试服的商人列表，还需要对杜隆塔尔补给与后勤达到崇敬。板条箱不给声望：声望来自工匠令状，从中立到崇敬共21,000点。《补给阵营声望》指南会带你走完。（{zone:1458}里还有另一个{npc:256384}；这里说的是营地那个。）",
}

G["forever/collectibles/pets/musical-gustjumper"] = {
	["From {area:16635} follow the road south, then cut across the field to the top of the waterfall: five frogs sit together on a rock there, by a log. Mobs patrol nearby, so a level 1 character should watch its back. Stand by the rock, target a frog and type /sing. The frogs sing back, the group disappears and one frog hops onto the log beside you: click it to take the {item:268109}, then use it to learn the pet. The item is not bound until you use it, so a friend on the island can sing again and trade you one."] = "从 {area:16635} 沿路向南，再穿过田地来到瀑布顶：那里的岩石上聚着五只青蛙，旁边有根原木。附近有怪物巡逻，1级角色要小心身后。站在岩石旁，选中一只青蛙并输入 /sing。青蛙会回唱，随后这群青蛙消失，其中一只会跳到你身旁的原木上：点击它领取 {item:268109}，再使用物品学会该宠物。物品使用前不绑定，因此岛上的朋友可以再唱一次，把获得的宠物交易给你。",
	["Sing to the frogs"] = "对青蛙唱歌",
	["Skyboat from {area:279}"] = "从{area:279}乘天空飞船",
	["Skyboat from {zone:1456}"] = "从{zone:1456}乘天空飞船",
	["Skyboat to {zone:2521}"] = "乘天空飞船前往{zone:2521}",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either)."] = "{zone:2521}是天裔的初始岛屿；据测试版玩家报告，任何人都可以前往。{area:17045}南面、{zone:1456}北面的悬崖约每5分钟有一艘空中船出发（{area:279}也有另一艘；两个阵营都可乘坐任意一艘）。",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either)."] = "{zone:2521} 是天裔的起始岛；据测试版玩家报告，任何人都可以前往。{area:279} 北侧约每五分钟有一班飞船出发（{zone:1456} 北侧也有一条航线；两个阵营都能乘坐任意一条）。",
}

G["forever/collectibles/pets/narkk"] = {
