	["{item:8496}, 40s"] = "{item:8496}，40银",
	["{npc:2663}'s Parrots"] = "{npc:2663}的鹦鹉",
	["{npc:2663}, the pirate supplier in {area:35}, sells two parrots (40s each), with no stock limit. He stands next to {npc:2664}, the cook. {area:35} is neutral: the boat from {area:392} and the Stranglethorn road both arrive there. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{area:35}的海盗用品商{npc:2663}出售两种鹦鹉（每种40银），库存不限。他站在厨师{npc:2664}旁。{area:35}是中立地区：从{area:392}来的船和荆棘谷的道路都能到达。使用每个宠物物品即可学会召唤对应伙伴；之后目标会保持勾选。",
}

G["forever/collectibles/pets/shadowgale-squirrel"] = {
	["50s"] = "50银",
	["Revered with the {faction:2758}"] = "{faction:2758}崇敬",
	["Skyboat from {area:279}"] = "从{area:279}乘天空飞船",
	["Skyboat from {zone:1456}"] = "从{zone:1456}乘天空飞船",
	["Skyboat to {zone:2521}"] = "乘天空飞船前往{zone:2521}",
	["{npc:254151}, the druids' quartermaster, waits inside their den in the {area:16631}, the cave just north-east of {npc:257944}'s camp. He sells the squirrel (50s) once you are Revered with the {faction:2758}. Get there young: the Shadowgale storyline and {npc:254151}'s first ear quest take you to Friendly, and his repeatable pays 1000 for five Al'Aketh Cultist's Ears up to level 18 but, by Classic's rules, only 200 from level 22. From Friendly to Revered that is about 80 ears at level 18 and about 400 at 22 or above. The Nightclaw Druids Reputation guide walks you through it."] = "德鲁伊军需官 {npc:254151} 在 {area:16631} 的兽穴内等候，洞穴就在 {npc:257944} 营地东北面不远处。与 {faction:2758} 达到崇敬后，他会出售松鼠（50银币）。尽量低等级时完成：影风 故事线和 {npc:254151} 的首次耳朵任务可让你达到友善；18级及以下时，他的重复任务每交五只 奥拉凯斯教徒的徽饰 奖励1000声望，但按经典旧世规则，22级起只奖励200声望。从友善到崇敬，18级时大约需要80只耳朵，22级及以上则约需400只。夜爪德鲁伊声望指南会带你完成。",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either)."] = "{zone:2521}是天裔的初始岛屿；据测试版玩家报告，任何人都可以前往。{area:17045}南面、{zone:1456}北面的悬崖约每5分钟有一艘空中船出发（{area:279}也有另一艘；两个阵营都可乘坐任意一艘）。",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either)."] = "{zone:2521} 是天裔的起始岛；据测试版玩家报告，任何人都可以前往。{area:279} 北侧约每五分钟有一班飞船出发（{zone:1456} 北侧也有一条航线；两个阵营都能乘坐任意一条）。",
}

G["forever/collectibles/pets/siamese-cat"] = {
	["Cookie"] = "曲奇",
	["Siamese Cat"] = "猫笼（黑尾白猫）",
	["{area:1581} is a group of five under {area:20}: the mine mouth is in {area:20}, the instance portal deep inside the mine. Cookie, the murloc cook, waits on a small island under the pirate ship at the far end, an optional boss; his cooking heals him, so interrupt it. He drops the Siamese about 15% of the time in Classic's data: expect several runs. The carrier can be traded, so check the Auction House too."] = "{area:1581} 是位于 {area:20} 下方的五人地下城：矿洞入口在 {area:20}，副本传送门则在矿洞深处。可选首领曲奇是一名鱼人厨师，在最深处海盗船下方的小岛上等待；他的烹饪会治疗自己，要打断。按经典旧世数据，他掉落暹罗猫的概率约为 15%：预计要刷几次。猫笼可以交易，也可以看看拍卖行。",
	["{area:1581} portal, inside the {area:20} mine"] = "{area:1581}传送门，在{area:20}的矿洞里",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
	["{area:1581}: Cookie"] = "{area:1581}：曲奇",
}

G["forever/collectibles/pets/smolderweb-carrier"] = {
	["Back to {npc:10260}"] = "回到{npc:10260}处",
	["Lower {area:1583}"] = "{area:1583}下层",
	["Lower {area:1583} is a group of five, level 55-60, inside {area:254}. The Spire Spider Eggs lie around {npc:10596}'s nest in the Skitterweb Tunnels, the spider halls: click them until you have 15 (each gives one to three). Hard-hitting spiderlings can hatch as you loot. By player reports the eggs cannot be looted in a raid group, so keep the party at five or fewer."] = "{area:1583} 下层是位于 {area:254} 内、适合 55-60 级的五人地下城。尖塔蜘蛛卵分布在蛛网隧道蜘蛛大厅内的 {npc:10596} 巢穴周围：持续点击，直到收集到 15 个（每次可获得一至三个）。拾取时可能会孵出伤害很高的小蜘蛛。据玩家报告，团队状态下无法拾取蜘蛛卵，因此队伍人数要保持在五人或以下。",
	["{npc:10260} at {area:251}"] = "{area:251}的{npc:10260}",
	["{npc:10260} stands inside the cave at {area:251}, the camp in northern {zone:1428} east of {area:254}. He also gives {npc:10260}'s Exotic Pets (the {item:12264}): take both, they are done in the same run."] = "{npc:10260}站在{area:251}营地的洞穴中，营地位于{zone:1428}北部、{area:254}以东。他还提供{npc:10260}的特殊宠物任务（{item:12264}）：两个都接，一趟可以一起完成。",
}

G["forever/collectibles/pets/spectral-bear-cub"] = {
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, a crafting profession at 150, 225 and 300, PvP ranks and battleground reputations, exploring, dungeons and raids) is worth one, and the track counts points earned, not spent. It gives the {item:281060} at 15, the {item:277714} at 25, the {item:277717} at 40 and the {item:277718} at 55. The rewards are claimed as quests from {npc:6791} in the inn at {area:392}, the goblin port on the {zone:1413} coast (Alliance players come by the boat from {area:35}): with 25 points he offers {quest:96383}; hand it straight back for the cub."] = "传承点数为账号共享：每项传承挑战（某职业达到25、45、60级，制造专业达到150、225、300点，PvP军衔和战场声望、探索、地下城及团队副本）各奖励一点，进度按累计获得的点数计算，不扣除已花费的点数。达到15点奖励 {item:281060}，25点奖励 {item:277714}，40点奖励 {item:277717}，55点奖励 {item:277718}。奖励以任务形式在 {area:392} 旅店的 {npc:6791} 处领取，这座地精港口位于 {zone:1413} 海岸（联盟玩家可从 {area:35} 坐船前往）：达到25点时，他会提供 {quest:96383}；接取后立即交还即可获得幼崽。",
	["Without PvP one character can earn 17 points: its class at 25, 45 and 60, two professions to 300, the two adventure challenges, the three dungeon tiers and the three raids. A second class or more professions on an alt make up the rest; the Legacy Challenges guide plans them."] = "不参与PvP，单个角色可以获得17点：本职业达到25、45和60级，两个专业升到300点，两项冒险挑战、三个地下城档次和三个团队副本。用小号再练一个职业或更多专业，即可补足其余点数；传承挑战指南会为你安排。",
	["{npc:6791} in {area:392}"] = "{area:392}的{npc:6791}",
}

G["forever/collectibles/pets/tallstrider-hatchling"] = {
	["The {npc:2172} is a rare level 20 tallstrider in southern {zone:1439}, near the {area:449}. Kill counts so far give her about 0.6% per kill, roughly one in 170, and in Classic she comes back only every few hours: check her spot whenever you pass, rather than camping. The hatchling binds when you loot it, so it never reaches the Auction House."] = "{npc:2172} 是一只20级稀有陆行鸟，出现在 {zone:1439} 南部、{area:449} 附近。目前的击杀统计显示，每次击杀掉率约为0.6%，即约一百七十分之一；在经典版中，她每隔数小时才刷新一次：每次路过顺便查看，不必蹲守。幼鸟拾取后绑定，因此不会出现在拍卖行。",
}

G["forever/collectibles/pets/tiny-crimson-whelpling"] = {
	["The red whelps live in the hills of the eastern {zone:1437}, towards {area:1037}: about 50 of them, back about five minutes after a kill in Classic's data. Red Whelps (levels 23-24) and Crimson Whelps (25-26) drop the whelpling about once in 650 kills, the Flamesnorting Whelps (26-27) mixed in with them only once in 1,600, so expect a long farm. It can be traded, so the Auction House may be quicker."] = "红色雏龙生活在 {zone:1437} 东部、靠近 {area:1037} 方向的丘陵中：大约 50 只，按经典旧世数据，击杀后约五分钟刷新。红色雏龙（23-24 级）和深红雏龙（25-26 级）掉落雏龙宠物的概率约为 650 分之一，混在其中的喷火雏龙（26-27 级）则只有约 1,600 分之一，因此要做好长时间刷取的准备。宠物可以交易，在拍卖行购买可能更快。",
	["{zone:1437} whelps"] = "{zone:1437}的雏龙",
}

G["forever/collectibles/pets/tiny-emerald-whelpling"] = {
	["Dreaming Whelps"] = "睡梦雏龙",
	["The Dreaming Whelps (levels 35-36) live in western {zone:1435}, near the {zone:1430} border. They drop it about once in 1,250 kills, and there are only a handful, back about every five minutes, so expect days of farming; it can be traded, so the Auction House may be quicker."] = "睡梦雏龙（35-36 级）生活在 {zone:1435} 西部、靠近 {zone:1430} 边界的地方。掉落概率约为 1,250 分之一，而且只有少数几只，约每五分钟刷新，因此可能需要刷上好几天；宠物可以交易，在拍卖行购买可能更快。",
}

G["forever/collectibles/pets/weevil-k-neevil"] = {
	["Back to {npc:217412}"] = "返回{npc:217412}处",
	["Hand {npc:217412} the three specimens: she gives you {item:280456} and 35s."] = "把三份标本交给 {npc:217412}：她会给你 {item:280456} 和 35 银币。",
	["The Arbor Tarantulas sit in northern Stranglethorn. Use the kit's tool on one to catch it."] = "树栖狼蛛在荆棘谷北部。对其中一只使用套装里的工具即可捕捉。",
	["The Flesh Pickers feed in the {area:596} in the middle of southern {zone:1443}. Use the kit's tool on one."] = "剔肉蝎在 {zone:1443} 南部中央的 {area:596} 觅食。对其中一只使用工具包中的工具。",
	["The Hay Weevils crawl in the north-west of {zone:1417}. Use the kit's tool on one."] = "干草象鼻虫在{zone:1417}西北部爬行。对其中一只使用工具包中的工具。",
	["{npc:217412}, a Forsaken bug collector, keeps her menagerie in western {zone:1435}. She hands you an Entomology Starter Kit: open it for the tools that catch the three bugs. The bugs are far apart (northern Stranglethorn, {zone:1417} and {zone:1443}), so do them while you pass. If you lose the kit, she sells another for 50s."] = "{npc:217412} 是一名被遗忘者昆虫收集者，她的虫舍位于 {zone:1435} 西部。她会给你一个昆虫学入门工具包：打开后取得捕捉三只虫子的工具。三只虫子相距很远（荆棘谷北部、{zone:1417} 和 {zone:1443}），因此经过时顺手完成即可。如果丢了工具包，她出售的补发包价格是 50 银币。",
	["{npc:217588} in {zone:1434}"] = "{zone:1434}的{npc:217588}",
	["{npc:217589} in {zone:1417}"] = "{zone:1417}的{npc:217589}",
	["{npc:217590} in {zone:1443}"] = "{zone:1443}的{npc:217590}",
}

G["forever/collectibles/pets/worg-carrier"] = {
	["Back to {npc:10260}"] = "回到{npc:10260}处",
	["Lower {area:1583}"] = "{area:1583}下层",
	["Lower {area:1583}: Halycon's pups"] = "{area:1583} 下层：哈雷肯的幼崽",
	["The pups are in Lower Blackrock Spire (a group of five, level 55-60), not Upper: they run with Halycon, the great worg, deep in the dungeon beyond {npc:10584}'s ogres. Use the cage on a living {npc:10221} before the pack is dead. Taking damage interrupts the cast, so let the tank hold the pups and cage one from the side. A rogue or druid can sneak in, cage a pup from a corner, then vanish."] = "幼崽位于黑石塔下层（五人小队，55-60 级），不是上层：它们跟着大座狼哈雷肯，位于地下城深处、{npc:10584} 的食人魔后方。狼群被杀光前，对一只活着的 {npc:10221} 使用笼子。受到伤害会打断施法，因此让坦克拉住幼崽，从侧面捕捉一只。潜行者或德鲁伊可以潜入，从角落捕捉一只后再脱身。",
	["{npc:10260} at {area:251}"] = "{area:251}的{npc:10260}",
	["{npc:10260} stands inside the cave at {area:251}, the camp in northern {zone:1428} east of {area:254}. He gives you an {item:12262}. He also gives En-Ay-Es-Tee-Why (the {item:12529}): take both, they are done in the same run."] = "{npc:10260}站在{area:251}营地的洞穴中，营地位于{zone:1428}北部、{area:254}以东。他会给你一个{item:12262}。他还提供蜘蛛卵任务（{item:12529}）：两个都接，一趟可以一起完成。",
}

