G["forever/professions/herbalism"] = {
	["Any {skill:182} trainer of your faction teaches Apprentice {skill:182} at any level (10c), and so does the Junior Herbalism Trainer in each starting area; the arrow picks the nearest. Turn on {spell:2383} (spellbook, General tab) so herbs show on the minimap. Forever's starting areas also have {object:656160} and {object:656161} (skill 1). The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) offers {item:247841} as a reward: reading it gives 2 skill, up to 15. Trade goods vendors sell the {item:277113}, a four-slot bag for herbs (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:182}: hand it in to the herbalism trainer it names once you reach skill 20, for the {spell:1229705} recipe."] = "本阵营的任意 {skill:182} 训练师都能在任何角色等级教授初级 {skill:182}（10铜币），各起始地区的初级草药学训练师也一样；箭头会选择最近的一位。开启 {spell:2383}（法术书的综合分页），让草药显示在微缩地图上。无限服起始地区还有 {object:656160} 和 {object:656161}（技能1）。各起始地区最初一小时内的任务（鼠辈泛滥、寒脊山谷的送信任务、森林守护者、高尔加的 {item:11584}、一件琐事、玛拉的遗愿）会提供奖励 {item:247841}：阅读后增加2点技能，最高可到15。杂货商出售 {item:277113}，这是四格草药包（25铜币）。如果你曾为“广阔天地”坐在起始地区的营火旁，那里的露营向导还会提供露营 101：{skill:182}：技能达到20后，将其交还给任务指定的草药学训练师，获得 {spell:1229705} 配方。",
	["Artisan {skill:182}"] = "专家级{skill:182}",
	["Artisan {skill:182} raises the cap to 300; it needs skill 200 and no character level, and costs 5g: train it as soon as you reach 200. The arrow picks the nearest {skill:182} trainer of your faction."] = "大师级 {skill:182} 将上限提高到300；需要技能200，无角色等级要求，费用5金币：达到200就立即学习。箭头会选择本阵营最近的 {skill:182} 训练师。",
	["Expert {skill:182}"] = "高级{skill:182}",
	["Expert {skill:182} raises the cap to 225; it needs skill 125 and no character level, and costs 50s: train it as soon as you reach 125. The arrow picks the nearest {skill:182} trainer of your faction."] = "高级{skill:182}将技能上限提高到225；需要技能125，无角色等级要求，费用50银币：达到125后立刻学习。箭头指向本阵营最近的{skill:182}训练师。",
	["Journeyman {skill:182}"] = "中级{skill:182}",
	["Journeyman {skill:182} raises the cap to 150; it needs skill 50 and no character level, and costs 5s: train it as soon as you reach 50. The arrow picks the nearest {skill:182} trainer of your faction. {spell:1229705}, Forever's camping item for {skill:182}, is taught from skill 20 (1s, or free from Camping 101: {skill:182}): a {item:2447} and a {item:765} each, it gives points until 25; placed beside a campfire it gives everyone at the camp a buff for an hour."] = "中级 {skill:182} 将上限提高到 150；要求技能 50，无角色等级要求，费用 5 银币：一到 50 就去学。箭头会选择本阵营最近的 {skill:182} 训练师。无限的 {skill:182} 露营物品 {spell:1229705} 在技能 20 起可学（1 银币，或通过露营 101: {skill:182} 免费学习）：每次需要一个 {item:2447} 和一个 {item:765}，制作可涨技能至 25；放在营火旁，会给予营地内所有人持续一小时的增益。",
	["Learn {skill:182}"] = "学习{skill:182}",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "采集沿途所有 {item:2447}（技能 1，橙色）、{item:765}（技能 1，橙色）、{item:2449}（技能 15 起），沿路径点循环采集，直到 {skill:182} 达到 50。地区等级为 1-10 级。提升这 49 点预计需要采集约 60 株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-15. Expect about 60 herbs for these 49 points."] = "采集沿途每一株 {item:2447}（1，橙色）、{item:765}（1，橙色）、{item:2449}（15起可采），沿路径点循环，直到 {skill:182} 达到50。地区等级1—15。提升这49点预计需采集约60株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "沿途遇到的 {item:2447}（1，橙色）、{item:765}（1，橙色）、{object:656161}（1，橙色）、{object:656160}（1，橙色）和 {item:2449}（15 起）都采，沿路径点循环，直到 {skill:182} 50。地区等级 1-10。提升这 49 点预计需要采约 60 株草药。",
	["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange, rare), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "采集沿途每一株 {item:2447}（1，橙色）、{item:765}（1，橙色）、{object:656161}（1，橙色，稀有）、{object:656160}（1，橙色）、{item:2449}（15起可采），沿路径点循环，直到 {skill:182} 达到50。地区等级1—10。提升这49点预计需采集约60株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "采集沿途每一株 {item:2447}（1，黄色）、{item:765}（1，黄色）、{item:2449}（15，黄色）、{item:785}（50，橙色）、{item:2450}（70起），沿路径点循环采集，直到 {skill:182} 100。{item:785} 和 {item:2450} 有时还会附带 {item:2452}。地区等级10—20。提升这50点预计需要采集约140株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. A quest here needs {skill:182}: Root Samples (level 16, {npc:3446}). Zone level 10-25. Expect about 110 herbs for these 50 points."] = "沿途遇到的 {item:2447}（1，黄色）、{item:765}（1，黄色）、{item:2449}（15，黄色）、{item:785}（50，橙色）、{item:2450}（70 起）和 {item:3820}（85 起）都采，沿路径点循环，直到 {skill:182} 100。采集 {item:785} 和 {item:2450} 有时还会获得 {item:2452}。{item:3820} 生长在沿岸水下：注意呼吸。这里有个任务要求 {skill:182}：根须样本（16 级，{npc:3446}）。地区等级 10-25。提升这 50 点预计需要采约 110 株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 130 herbs for these 50 points."] = "采集沿途所有{item:2447}（1，黄色）、{item:765}（1，黄色）、{item:2449}（15，黄色）、{item:785}（50，橙色）、{item:2450}（70起）和{item:3820}（85起），沿路径点循环，直到{skill:182}100。采集{item:785}和{item:2450}时，有时还会获得{item:2452}。{item:3820}长在岸边水下：注意呼吸时间。地区等级10-20。这50点预计需采约130株草药。",
	["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "采集沿途每一株 {item:2447}（1，黄色）、{item:765}（1，黄色）、{item:2449}（15，黄色）、{item:785}（50，橙色）、{item:2450}（70起可采）、{item:3820}（85起可采），沿路径点循环，直到 {skill:182} 达到100。采集 {item:785} 和 {item:2450} 时有时还会获得一株 {item:2452}。{item:3820} 长在岸边水下：留意呼吸。地区等级10—20。提升这50点预计需采集约140株草药。",
	["Pick every {item:2449} (15, green), {item:785} (50, green), {item:2450} (70, yellow), {item:2453} (100, orange) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 15-25. Expect about 60 herbs for these 25 points."] = "采集沿途每一株 {item:2449}（15，绿色）、{item:785}（50，绿色）、{item:2450}（70，黄色）、{item:2453}（100，橙色），沿路径点循环采集，直到 {skill:182} 125。{item:785} 和 {item:2450} 有时还会附带 {item:2452}。地区等级15—25。提升这25点预计需要采集约60株草药。",
	["Pick every {item:2450} (70, green, rare), {item:3820} (85, green), {item:2453} (100, green, rare), {object:1623} (115, yellow, rare), {item:3356} (125, yellow), {item:3357} (150, orange), {item:3818} (160, orange), {item:3821} (from 170) you pass and circle the waypoints until {skill:182} 185. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 35-45. Expect about 40 herbs for these 25 points."] = "采集沿途每一株 {item:2450}（70，绿色，稀有）、{item:3820}（85，绿色）、{item:2453}（100，绿色，稀有）、{object:1623}（115，黄色，稀有）、{item:3356}（125，黄色）、{item:3357}（150，橙色）、{item:3818}（160，橙色）、{item:3821}（170起可采），沿路径点循环，直到 {skill:182} 达到185。采集 {item:785} 和 {item:2450} 时有时还会获得一株 {item:2452}。{item:3820} 长在岸边水下：留意呼吸。地区等级35—45。提升这25点预计需采集约40株草药。",
	["Pick every {item:2453} (100, green, rare), {object:1623} (115, green, rare), {item:3356} (125, green), {item:3357} (150, yellow), {item:3818} (160, yellow), {item:3821} (170, orange), {object:2043} (185, orange) you pass and circle the waypoints until {skill:182} 200. Zone level 35-45. Expect about 20 herbs for these 15 points."] = "采集沿途每一株 {item:2453}（100，绿色，稀少）、{object:1623}（115，绿色，稀少）、{item:3356}（125，绿色）、{item:3357}（150，黄色）、{item:3818}（160，黄色）、{item:3821}（170，橙色）、{object:2043}（185，橙色），沿路径点循环采集，直到 {skill:182} 200。地区等级35—45。提升这15点预计需要采集约20株草药。",
	["Pick every {item:3357} (150, green, rare), {item:3818} (160, green, rare), {item:3821} (170, green), {object:2043} (185, yellow, rare), {item:8831} (210, orange), {item:8838} (230, orange), {item:8845} (from 245) you pass and circle the waypoints until {skill:182} 260. {item:8845} grows in caves and dark hollows: look inside as well. {item:8831} sometimes gives a {item:8153} as well. Zone level 40-50. Expect about 50 herbs for these 30 points."] = "采集沿途每一株 {item:3357}（150，绿色，稀少）、{item:3818}（160，绿色，稀少）、{item:3821}（170，绿色）、{object:2043}（185，黄色，稀少）、{item:8831}（210，橙色）、{item:8838}（230，橙色）、{item:8845}（245起），沿路径点循环采集，直到 {skill:182} 260。{item:8845} 生长在洞穴和阴暗洼地里：也要进去看看。{item:8831} 有时还会附带 {item:8153}。地区等级40—50。提升这30点预计需要采集约50株草药。",
	["Pick every {item:3820} (85, yellow), {object:1623} (115, orange), {item:3356} (125, orange), {item:3357} (from 150) you pass and circle the waypoints until {skill:182} 160. {item:3820} grows underwater along the shore: watch your breath. Zone level 30-45. Expect about 70 herbs for these 35 points."] = "采集沿途每一株 {item:3820}（85，黄色）、{object:1623}（115，橙色）、{item:3356}（125，橙色）、{item:3357}（150起），沿路径点循环采集，直到 {skill:182} 160。{item:3820} 生长在岸边水下：注意呼吸。地区等级30—45。提升这35点预计需要采集约70株草药。",
	["Pick every {item:3821} (170, green), {object:2043} (185, green, rare), {item:8831} (210, green), {item:8838} (230, yellow), {item:8845} (245, orange), {item:13464} (260, orange) you pass and circle the waypoints until {skill:182} 285. {item:8845} grows in caves and dark hollows: look inside as well. {item:8831} sometimes gives a {item:8153} as well. Zone level 40-50. Expect about 70 herbs for these 25 points."] = "采集沿途每一株 {item:3821}（170，绿色）、{object:2043}（185，绿色，稀少）、{item:8831}（210，绿色）、{item:8838}（230，黄色）、{item:8845}（245，橙色）、{item:13464}（260，橙色），沿路径点循环采集，直到 {skill:182} 285。{item:8845} 生长在洞穴和阴暗洼地里：也要进去看看。{item:8831} 有时还会附带 {item:8153}。地区等级40—50。提升这25点预计需要采集约70株草药。",
	["Pick every {item:765} (1, green, rare), {item:2449} (15, green, rare), {item:785} (50, green), {item:2450} (70, yellow), {item:3820} (85, orange), {item:2453} (100, orange), {object:1623} (from 115) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 20-30. Expect about 40 herbs for these 25 points."] = "沿途遇到的 {item:765}（1，绿色，稀少）、{item:2449}（15，绿色，稀少）、{item:785}（50，绿色）、{item:2450}（70，黄色）、{item:3820}（85，橙色）、{item:2453}（100，橙色）和 {object:1623}（115 起）都采，沿路径点循环，直到 {skill:182} 125。采集 {item:785} 和 {item:2450} 有时还会获得 {item:2452}。{item:3820} 生长在沿岸水下：注意呼吸。地区等级 20-30。提升这 25 点预计需要采约 40 株草药。",
	["Pick every {item:785} (50, green), {item:2450} (70, yellow), {item:2453} (100, orange), {object:1623} (from 115) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 15-27. Expect about 40 herbs for these 25 points."] = "采集沿途所有{item:785}（50，绿色）、{item:2450}（70，黄色）、{item:2453}（100，橙色）和{object:1623}（115起），沿路径点循环，直到{skill:182}125。采集{item:785}和{item:2450}时，有时还会获得{item:2452}。地区等级15-27。这25点预计需采约40株草药。",
	["Pick every {item:8836} (220, green), {item:8838} (230, green), {item:13463} (270, orange), {item:13465} (280, orange), {item:13466} (285, orange) you pass and circle the waypoints until {skill:182} 300. Zone level 51-58. Expect about 20 herbs for these 15 points."] = "采集沿途每一株 {item:8836}（220，绿色）、{item:8838}（230，绿色）、{item:13463}（270，橙色）、{item:13465}（280，橙色）、{item:13466}（285，橙色），沿路径点循环，直到 {skill:182} 达到300。地区等级51—58。提升这15点预计需采集约20株草药。",
