	["{npc:4641}: 20 Gelkis"] = "{npc:4641}：20 点吉尔吉斯声望",
	["{npc:4648}: 20 Magram"] = "{npc:4648}：20名玛格拉姆半人马",
	["{npc:4649}: 20 Magram"] = "{npc:4649}：20名玛格拉姆半人马",
