G["forever/reputation/hydraxian-waterlords"] = {
	["Ancient Core Hound"] = "上古熔火犬",
	["At Revered the Duke gives you the {item:22754}: it does the {item:17333}'s work and is not used up, so you never come back for another vial."] = "崇敬后，公爵会给你 {item:22754}：它的作用与 {item:17333} 相同，而且不会消耗，再也不必回来领取新的水瓶。",
	["Back to {npc:13278}"] = "回到{npc:13278}处",
	["Back to {npc:13278}. {quest:6823} is done the moment you are Honored."] = "回去找 {npc:13278}。声望一到尊敬，{quest:6823} 就会完成。",
	["Baron Geddon"] = "迦顿男爵",
	["Desert Rumbler"] = "沙漠奔行者",
	["Dust Stormer"] = "尘暴元素",
	["Dust Stormers and Desert Rumblers drift around the {area:2740} in the north-west of {zone:1451}. Each kill also pays 5 reputation while you are Neutral or Friendly, so stay if you mean to farm (next steps)."] = "灰尘风暴和沙漠奔行者在 {zone:1451} 西北面的 {area:2740} 周围游荡。中立或友善时，每次击杀还给5声望，因此如果打算刷怪（见后续步骤），可以留在这里。",
	["Elementals to Honored"] = "刷元素至尊敬",
	["Firelord"] = "火焰领主",
	["Firewalker"] = "火焰行者",
	["Flameguard"] = "烈焰守卫",
	["Garr"] = "加尔",
	["Gehennas"] = "基赫纳斯",
	["Golemagg the Incinerator"] = "焚化者古雷马格",
	["Hand in the hands, then dive under the surf at the southern foot of the island: {object:179551} holds your ring and pays the only quest reputation the Waterlords give, 200. From now on, while you are Honored or better, the Duke hands you {item:17333}: pour it on a rune in the {area:2717} to douse it. With every rune doused, {npc:12018} comes out, and after him {npc:11502}."] = "交还手掌，然后潜入小岛南侧山脚的海水中：{object:179551}中有你的戒指，并奖励海达希亚水元素唯一的任务声望，共200。从此以后，只要声望保持尊敬或更高，公爵就会给你{item:17333}：将它倒在{area:2717}的符文上即可熄灭符文。所有符文都熄灭后，{npc:12018}就会出现，之后是{npc:11502}。",
	["Honored to Revered is 12,000 reputation. The trash still counts, so a full clear pays about 3,360 plus 700 from the seven bosses, 150 from {npc:11988} and 200 from {npc:11502}: about three clears. {npc:9017} (15) and {npc:9816} (50) count too while you are Honored. The trash stops at 11,999 of 12,000 Honored; the bosses carry you over."] = "从尊敬到崇敬需要12,000声望。小怪仍提供声望，因此完整通关一次，小怪约给3,360，七名首领共700，另有 {npc:11988} 的150和 {npc:11502} 的200：大约三次即可。尊敬时，{npc:9017}（15）和 {npc:9816}（50）也提供声望。小怪到尊敬11,999/12,000时停止提供声望；靠首领跨过最后一点。",
	["Huricanian"] = "飓风元素",
	["Hydraxian Waterlords Reputation"] = "海达希亚水元素声望",
	["Lava Elemental"] = "熔岩元素",
	["Lava Surger"] = "熔岩奔腾者",
	["Lord Incendius"] = "因森迪斯领主",
	["Lucifron"] = "鲁西弗隆",
	["Magmadar"] = "玛格曼达",
	["Molten Giant"] = "熔火巨人",
	["Neutral to Honored is 9,000 reputation, and {quest:6823} asks for Honored. One {area:2717} clear pays about 4,000 of it. Without a raid it comes from the elementals: 5 per {npc:11744}, {npc:11746} or {npc:7032} (the {zone:1428}), about 1,800 kills from Neutral. They stop at 5,999 of 6,000 Friendly, one point short, so the last point needs a kill that still counts there: {npc:14478}, a rare air elemental in the {area:2740} (25), or {npc:9017} at the {object:174825} in {area:1584} (15, a five-player dungeon). Those two and {npc:9816} keep paying through Honored as well."] = "从中立到尊敬需要9,000声望，而 {quest:6823} 要求达到尊敬。通关一次 {area:2717} 大约可得4,000。没有团队时就刷元素：每只 {npc:11744}、{npc:11746} 或 {npc:7032}（{zone:1428}）给5点，从中立起约需1,800次击杀。它们到友善5,999/6,000时不再提供声望，差最后一点，所以要击杀此时仍有声望的目标：{area:2740} 的稀有空气元素 {npc:14478}（25点），或五人地下城 {area:1584} 中 {object:174825} 处的 {npc:9017}（15点）。这两个目标和 {npc:9816} 在尊敬阶段也会继续提供声望。",
	["Ragnaros"] = "拉格纳罗斯",
	["Reputation · Raids and dungeons"] = "声望 · 团队副本与地下城",
	["Revered to Exalted is 21,000 reputation. The trash has stopped, but all nine bosses still pay while you are Revered: 100 each from the seven, 150 from {npc:11988} and 200 from {npc:11502}, 1,050 a clear: about 20 clears. The seven stop at 20,999 of 21,000 Revered, so the last point comes from {npc:11988} or {npc:11502}, and from Exalted on only those two pay."] = "从崇敬到崇拜需要21,000声望。小怪已不再提供，但崇敬时全部九名首领仍有声望：七名各100，{npc:11988} 给150，{npc:11502} 给200，每次通关1,050：大约20次。七名首领到崇敬20,999/21,000时停止提供，所以最后一点要靠 {npc:11988} 或 {npc:11502}；达到崇拜后，也只有这两名继续提供声望。",
	["Shazzrah"] = "沙斯拉尔",
	["Sulfuron Harbinger"] = "萨弗隆先驱者",
	["The {item:22754}"] = "{item:22754}",
	["Use the {item:17310} on a {npc:8521} or a {npc:8522}: it turns into a {npc:13279}. Kill the surge and loot its {item:17309}. Twelve are needed, and the vial must still be in your bags at the turn-in."] = "对一只 {npc:8521} 或 {npc:8522} 使用 {item:17310}：它会变成 {npc:13279}。击杀变出的元素并拾取其 {item:17309}。共需十二个，而且交还任务时瓶子仍必须在背包中。",
	["{area:2717} to Exalted"] = "在 {area:2717} 提升至崇拜",
	["{area:2717} to Revered"] = "在 {area:2717} 提升至崇敬。",
	["{item:17310}, on the poisoned elementals"] = "对中毒的元素使用{item:17310}",
	["{item:17332}: raid of 40"] = "{item:17332}：40人团队",
	["{item:17333} to douse the {area:2717}'s runes, the reusable {item:22754} at Revered and a fire resistance ring."] = "可获得用来熄灭{area:2717}符文的{item:17333}、崇敬时可重复使用的{item:22754}，以及一枚火焰抗性戒指。",
	["{item:17333}, ask the Duke"] = "{item:17333}，向公爵索取",
	["{item:18412}, at the portal in {area:1584}"] = "{item:18412}，在{area:1584}的传送门旁",
	["{item:22754}, ask the Duke"] = "{item:22754}，向公爵索取",
	["{npc:11502}, 200"] = "{npc:11502}，200",
	["{npc:11658}: raid of 40"] = "{npc:11658}：40人团队",
	["{npc:11666}, 40"] = "{npc:11666}，40",
	["{npc:11667}, 40"] = "{npc:11667}，40",
	["{npc:11744}, 5"] = "{npc:11744}，5",
	["{npc:11746}, 5"] = "{npc:11746}，5",
	["{npc:11982}, 100"] = "{npc:11982}，100",
	["{npc:11988}, 150"] = "{npc:11988}，150",
	["{npc:12056}, 100"] = "{npc:12056}，100",
	["{npc:12057}, 100"] = "{npc:12057}，100",
	["{npc:12076}, 40"] = "{npc:12076}，40",
	["{npc:12098}, 100"] = "{npc:12098}，100",
	["{npc:12118} and the other bosses, 100: they carry you past 11,999"] = "{npc:12118} 及其他首领，100点：可让你越过11,999点门槛",
	["{npc:12118}, 100"] = "{npc:12118}，100",
	["{npc:12118}, {npc:12259}, {npc:12264} and {npc:12098} are {area:2717} bosses: each drops his hand for the quest."] = "{npc:12118}、{npc:12259}、{npc:12264}和{npc:12098}都是{area:2717}首领：各自会掉落任务所需的手。",
	["{npc:12259}, 100"] = "{npc:12259}，100",
	["{npc:12264}, 100"] = "{npc:12264}，100",
	["{npc:13278} stands on a small island off the east coast of {zone:1447}; swim out to him. Everyone starts Neutral with the Waterlords, and nearly all of their reputation comes from killing the servants of fire, air and earth: the quests themselves pay nothing until the last one. Take both quests: the chain goes on only when both are done. Everything past Honored happens in the {area:2717}, a raid of 40 that is not among the first raids Blizzard has announced for Forever; until it opens, Honored is as far as the Waterlords go. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%."] = "{npc:13278} 站在 {zone:1447} 东海岸外的一座小岛上；游过去找他。所有人的海达希亚水元素声望都从中立开始，几乎全部声望都来自击杀火、风和土的仆从：任务本身直到最后一个才奖励声望。两个任务都接：全部完成后，任务链才会继续。尊敬之后的内容都在 {area:2717} 内，这是一个 40 人团队副本，不在暴雪已公布的无限首批团队副本之列；开放前，海达希亚水元素声望最多只能到尊敬。本指南的数值不包括传承天赋“外交家”最多额外 10% 的加成。",
	["{npc:14387} in {area:254} attunes you to the {area:2717}: bring him a {item:18412} from beside the {area:2717}'s portal at the bottom of {area:1584}. Once attuned, he can send you straight into the {area:2717}."] = "{area:254}的{npc:14387}能为你取得{area:2717}的入场资格：从{area:1584}底部、{area:2717}传送门旁带回一个{item:18412}给他。取得资格后，他就能直接将你传入{area:2717}。",
	["{npc:14478}, rare, 25"] = "{npc:14478}，稀有，25",
	["{npc:9017}, {area:1584}: 15, group up"] = "{npc:9017}，{area:1584}：15 点声望，组队完成",
	["{npc:9816} is a boss in Upper Blackrock Spire, inside {area:254}: a group of up to ten, and someone needs the {item:12344} to open the door. He drops the Eye and pays 50 reputation per kill up to 11,999 of 12,000 Honored. {npc:9017} in {area:1584} pays 15 the same way."] = "{npc:9816} 是黑石塔上层的首领，位于 {area:254} 内：小队最多十人，需要有人持有 {item:12344} 才能开门。他会掉落眼睛，每次击杀奖励50点声望，直到尊敬12,000中的11,999点。{area:1584} 的 {npc:9017} 以同样规则奖励15点。",
	["{quest:6821}: raid of ten"] = "{quest:6821}：10 人团队",
	["{quest:6822} is a raid of 40. Kill one {npc:11658}, {npc:11668}, {npc:11673} and {npc:12101} for {npc:13278}. Every elemental there pays: Firewalkers, Flameguards, Lava Elementals, Lava Reavers and Molten Destroyers 40, Firelords, Lava Surgers, Molten Giants and Ancient Core Hounds 20, up to 11,999 of 12,000 Honored; about 3,360 for a full clear of the trash. The bosses pay 100 each ({npc:11988} 150, {npc:11502} 200)."] = "{quest:6822} 需要40人团队。为 {npc:13278} 各击杀一只 {npc:11658}、{npc:11668}、{npc:11673} 和 {npc:12101}。那里的所有元素怪都会奖励声望：火焰行者、烈焰守卫、熔岩元素、熔岩掠夺者和熔核摧毁者各40点，火焰之王、熔岩奔腾者、熔核巨人和上古熔火恶犬各20点，直到尊敬12,000中的11,999点；完整清掉普通怪约获3,360点。首领各奖励100点（{npc:11988} 为150点，{npc:11502} 为200点）。",
}

G["forever/reputation/merchants-favor"] = {
	["A {item:18662} for the writ"] = "用{item:18662}交一份令状",
	["A {item:18662} for the writ again"] = "再用{item:18662}交一份令状",
	["A {item:7371} for the writ"] = "为文书准备一份 {item:7371}",
	["A {item:7371} for the writ again"] = "再次为文书准备一份 {item:7371}",
	["After the {quest:98247}, Friendly is 1000 more: 14 Journeyman writs, 8 Expert or 5 Artisan. Expert and Artisan customers are mostly not in Polestar's data yet: follow the mark the quest puts on your map. Journeyman envelopes drop from mobs of about level 11 to 31; Expert and Artisan ones from higher mobs."] = "完成 {quest:98247} 后，到友善还需 1000 点：14 份中级订单、8 份高级订单或 5 份大师级订单。高级和大师级订单的顾客大多尚未收录在 Polestar 数据中：跟着任务在地图上标出的地点走。中级信封由约 11 至 31 级怪物掉落；高级和大师级信封来自更高等级怪物。",
	["All five stand at the {area:2240} on the {area:439}, south-east of {area:484}: {npc:4720}, the chicken \"Plucky\" Johnson, {npc:4706}, the {npc:4496} and {npc:6548}. Customers show no quest mark: right-click them anyway."] = "五名目标都在 {area:484} 东南方、{area:439} 上的 {area:2240}：{npc:4720}、小鸡胆大的约翰森、{npc:4706}、{npc:4496} 和 {npc:6548}。顾客头上没有任务标记：直接右键点击他们。",
	["All four stand around {area:431}: {npc:257315} about 850 yards south-west of it, {npc:257322} to the south, the {npc:257316} about 350 yards south-east and {npc:257317} about 650 yards north-east. Customers show no quest mark: right-click them anyway."] = "4位都在{area:431}周围：{npc:257315}在其西南约850码，{npc:257322}在南面，{npc:257316}在东南约350码，{npc:257317}在东北约650码。客户不会显示任务标记：直接右键点击即可。",
	["An {item:4384} for the writ"] = "用{item:4384}交一份令状",
	["An {item:4384} for the writ again"] = "再用{item:4384}交一份令状",
	["Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, named in its quest (not always the writ's title: a {item:3388} writ wants a Strong Troll's Blood Potion). Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for."] = "工匠令状就是营地声望：中级令状75点，高级令状125点，大师级令状200点。每份都要求一件制成品，名称写在它的任务里（不一定与令状标题相同：一份{item:3388}令状要的是强效巨魔之血药水）。自己制作或在拍卖行购买；不需要学会该专业。每份令状每天可完成一次，不同令状数量不限。只接你已经拥有物品、或顺路会买到的令状任务（右键点击令状），把令状留在包里，然后勾选此项：后续步骤会带你去见每一位你持有令状的顾客。",
	["Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, named in its quest (not always the writ's title: a {spell:3176} writ wants a {item:3388}). Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for."] = "工匠令状就是营地声望：中级令状75点，高级令状125点，大师级令状200点。每份都要求一件制成品，名称写在它的任务里（不一定与令状标题相同：一份{spell:3176}令状要的是{item:3388}）。自己制作或在拍卖行购买；不需要学会该专业。每份令状每天可完成一次，不同令状数量不限。只接你已经拥有物品、或顺路会买到的令状任务（右键点击令状），把令状留在包里，然后勾选此项：后续步骤会带你去见每一位你持有令状的顾客。",
	["Elixir of Ogre's Strength, 75 reputation"] = "食人魔力量药剂，75点声望",
	["Elixir of Water Breathing, 75 reputation"] = "水下呼吸药剂，75点声望",
	["Engineers make the {item:4384}; {npc:789} sells it in {area:69} (Alliance). Otherwise buy one at the Auction House."] = "{item:4384}由工程学制造；{npc:789}在{area:69}出售（联盟）。否则就在拍卖行买一个。",
	["Exalted"] = "崇拜",
	["Exalted opens the camp's tabard (200 Favor) at {npc:256389} or {npc:256384}, and the {item:262766} (6,000 Favor; the mount needs level 60 and Journeyman mount training) at {npc:256736} in {area:1002} or Okamache at the Crossroads camp. The {npc:10636} guide under Collectibles leads you there."] = "崇拜后可向{npc:256389}或{npc:256384}购买营地战袍（200 Merchant's Favor），向{area:1002}的{npc:256736}或十字路口营地的奥卡玛什购买{item:262766}（6,000 Merchant's Favor；坐骑需要60级及中级骑术）。收藏品下的{npc:10636}指南会带你前往。",
	["Exalted opens the camp's tabard (200 Favor) at {npc:256389} or {npc:256384}, and the {item:262766} (6,000 Favor; the mount needs level 60 and Journeyman mount training) at {npc:256736} in {area:1002} or Okamache at the {area:380} camp. The {npc:10636} guide under Collectibles leads you there."] = "崇拜后可在{npc:256389}或{npc:256384}处购买营地战袍（200点恩惠），并可在{area:1002}的{npc:256736}或{area:380}营地的奥卡马奇处购买{item:262766}（6,000点恩惠；坐骑需要60级和中级骑术）。收藏品分类下的{npc:10636}指南会带你去那里。",
	["Forever's trade camps: their best recipes, the Minimule and the {npc:10636} need standing, not only Merchant's Favor."] = "无限的贸易营地：最好的配方、迷你骡子和{npc:10636}需要声望等级，而不仅仅是商人青睐。",
	["Friendly opens the first gated recipes at the camp's profession vendors ({skill:197} 25, {skill:165} 17, {skill:333} 13, {skill:164} 10, {skill:202} 10, {skill:171} 5, {skill:185} 2) and the Uncertified Scribe: {npc:256742} at {area:1002}, {npc:256672} at the south end of the Crossroads camp. The scribe's {item:262902} (15 Merchant's Favor) turns an empty {item:248549} into a {item:262917}; hand it to {npc:256390} or {npc:256386} for 50 reputation ({quest:93862}). Any crate works, so buy the cheapest one the Auction House has. Honored is 6000 more: 80 Journeyman writs, 48 Expert, 30 Artisan, or 120 crate returns (1,800 Favor and 120 crates). Mix both: every writ you can fill, returns with spare Favor. The Legacy perk Diplomat adds up to 10% to every gain."] = "友善后可在营地专业商人处购买第一批有声望要求的配方（{skill:197} 25、{skill:165} 17、{skill:333} 13、{skill:164} 10、{skill:202} 10、{skill:171} 5、{skill:185} 2），还可使用Uncertified Scribe的服务：{npc:256742}在{area:1002}，{npc:256672}在十字路口营地南端。其出售的{item:262902}（15 Merchant's Favor）可将空的{item:248549}变成{item:262917}；交给{npc:256390}或{npc:256386}可获得50声望（{quest:93862}）。任何箱子都行，买拍卖行最便宜的即可。到尊敬还需6000声望：相当于80份中级文书、48份高级文书、30份大师级文书，或归还120个箱子（需要1,800 Merchant's Favor和120个箱子）。两种方式搭配：能交的文书都交，用多余的Merchant's Favor归还箱子。Legacy特长Diplomat可使每次声望获取最多提高10%。",
	["Friendly opens the first gated recipes at the camp's profession vendors ({skill:197} 25, {skill:165} 17, {skill:333} 13, {skill:164} 10, {skill:202} 10, {skill:171} 5, {skill:185} 2) and the Uncertified Scribe: {npc:256742} at {area:1002}, {npc:256672} at the south end of the {area:380} camp. The scribe's {item:262902} (15 Merchant's Favor) turns an empty {item:248549} into a {item:262917}; hand it to {npc:256390} or {npc:256386} for 50 reputation ({quest:93862}). Any crate works, so buy the cheapest one the Auction House has. Honored is 6000 more: 80 Journeyman writs, 48 Expert, 30 Artisan, or 120 crate returns (1,800 Favor and 120 crates). Mix both: every writ you can fill, returns with spare Favor. The Legacy perk Diplomat adds up to 10% to every gain."] = "友善解锁营地专业供应商处的第一批门槛配方（{skill:197}25、{skill:165}17、{skill:333}13、{skill:164}10、{skill:202}10、{skill:171}5、{skill:185}2），以及无证抄写员：{area:1002}的{npc:256742}、{area:380}营地南端的{npc:256672}。抄写员的{item:262902}（15点商人的恩惠）能把一个空的{item:248549}变成{item:262917}；把它交给{npc:256390}或{npc:256386}可得50点声望（{quest:93862}）。任何板条箱都行，所以买拍卖行里最便宜的那个。到尊敬还需6000点：80份中级令状、48份高级令状、30份大师级令状，或交还120个板条箱（1800点恩惠和120个箱子）。两者混合：能填的令状都做，剩余的恩惠用交箱补。传承特长“外交家”可使每次获取量最多提高10%。",
	["Friendly to Honored"] = "友善到尊敬",
	["From level 10, mobs anywhere drop Waylaid Crates and sealed writs (Journeyman's, Expert's and Artisan's). Fill a crate with one of the bundles it lists (right-click it), or open a sealed writ: by beta reports, the first time you do either you also get a {quest:98247}. Right-click the label to start its quest. Crates and writs can be traded, so the Auction House sells them too."] = "从 10 级起，任何地方的怪物都可能掉落遭劫的板条箱和密封文书（中级、高级和大师级）。按箱子列出的选项装入一批物资（右键点击箱子），或打开一份密封文书：据测试版报告，首次进行其中任意一种操作时，还会获得 {quest:98247}。右键点击标签可开始其任务。板条箱和文书可以交易，因此拍卖行也有出售。",
	["Gather your writs"] = "收集你的文书。",
	["Gather your writs again"] = "再次收集文书",
	["Honored opens the rest of the gated recipes ({skill:165} 28, {skill:164} 21, {skill:333} 16, {skill:171} 15, {skill:202} 9, {skill:197} 6, {skill:185} 1), the {item:270887} (1,200 Favor from {npc:256389} or {npc:256384}: it starts the quest for a Tradeskill Sign toy) and the scribe's {item:262896} (15 Favor), which swaps a writ you cannot fill for a random one of the same rank. Revered is 12000 more: 160 Journeyman writs, 96 Expert, 60 Artisan, or 240 crate returns (3,600 Favor). Forever's quest data sets no standing limit on Journeyman writs: their customers are the ones in the zone steps above."] = "尊敬可解锁其余有声望门槛的配方（{skill:165}28个、{skill:164}21个、{skill:333}16个、{skill:171}15个、{skill:202}9个、{skill:197}6个、{skill:185}1个）、{item:270887}（向{npc:256389}或{npc:256384}花1,200点商人青睐购买：它会开启获得商业技能路标玩具的任务），以及铭文师的{item:262896}（15点商人青睐），可将无法完成的文书随机换成同阶另一张。到崇敬还需12000声望：160张中级文书、96张高级文书、60张大师级文书，或交还240箱（3,600点商人青睐）。无限服任务数据没有给中级文书设置声望上限：其客户就是上方各地区步骤中的人。",
	["Honored to Revered"] = "尊敬到崇敬",
	["Leatherworkers make the {item:18662}, and the Auction House has it. Its only vendor is {npc:14860} at the Darkmoon Faire, which Forever has not shown yet: go there only if the Faire is in town."] = "{item:18662}由制皮制作，拍卖行有售。它唯一的供应商是暗月马戏团的{npc:14860}，而 无限 目前尚未开放马戏团：只有马戏团来到城里时才去那里。",
	["Leatherworkers make the {item:7371}; the bow and gun vendors of {zone:1453}, {zone:1455} and the {zone:1458} sell it. Otherwise buy one at the Auction House."] = "制皮可制作{item:7371}；{zone:1453}、{zone:1455}及{zone:1458}的弓箭和枪械商人也有出售。否则可在拍卖行买一个。",
	["Neutral to Friendly"] = "中立到友善",
	["Profession recipes at Friendly and Honored"] = "友善和尊敬时的专业配方",
	["Reputation · World"] = "声望 · 世界",
	["Revered opens the {item:284664}, the Minimule pet (1,500 Favor from {npc:256389} or {npc:256384}). Exalted is 21000 more: 280 Journeyman writs, 168 Expert, 105 Artisan, or 420 crate returns (6,300 Favor). Keep 6,000 Favor for the {npc:10636} if you want it."] = "崇敬后开放 {item:284664}，即迷你骡宠物（向 {npc:256389} 或 {npc:256384} 支付 1,500 商人青睐）。到崇拜还需 21000 点：280 份中级订单、168 份高级订单、105 份大师级订单，或归还 420 个箱子（6,300 商人青睐）。如果想要 {npc:10636}，留着 6,000 商人青睐。",
	["Revered to Exalted"] = "崇敬到崇拜",
	["Strong Troll's Blood Potion, 75 reputation"] = "强效巨魔之血药水，75点声望",
	["Supply Factions Reputation"] = "补给阵营声望",
	["Take the quests of the writs you can fill"] = "接受你能完成的文书任务",
	["The {faction:2586} camp is at {area:1002}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet in western Redridge. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to {npc:256390} too, but they pay only Merchant's Favor and silver, never reputation."] = "{faction:2586} 的营地位于赤脊山西部的 {area:1002}，{zone:1429}、{zone:1431} 和 {area:69} 来的道路在此交会。标签一次性提供2000声望（据测试反馈还给50点商人青睐）：已完成到友善所需进度的三分之二。装满的箱子也交给 {npc:256390}，但只奖励商人青睐和银币，绝不提供声望。",
	["The {faction:2587} camp stands just outside the west gate of the Crossroads. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to {npc:256386} too, but they pay only Merchant's Favor and silver, never reputation."] = "{faction:2587}的营地就在十字路口西门外。货运标签可一次性获得2000声望（据测试服反馈，还会获得50 Merchant's Favor），达到友善所需声望的三分之二。装满的箱子也交给{npc:256386}，但只奖励Merchant's Favor和银币，不给声望。",
	["The {faction:2587} camp stands just outside the west gate of the {area:380}. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to {npc:256386} too, but they pay only Merchant's Favor and silver, never reputation."] = "{faction:2587}的营地就在{area:380}西门外。该标签一次性给2000点声望（据测试服报告，还有50点商人的恩惠）：相当于到友善的三分之二。装满的板条箱也交给{npc:256386}，但只给商人的恩惠和银币，从不给声望。",
	["Your first {item:248549} or writ"] = "你的第一个{item:248549}或文书",
	["bring it: craft it or buy it at the Auction House"] = "带上它：自己制作，或在拍卖行购买",
	["{area:1002}: the {quest:98247}"] = "{area:1002}：{quest:98247}",
	["{area:35} holds three customers: \"Sea Wolf\" MacKinley (on the inn's top floor), {npc:7853} at the zeppelin-style transporter pad and {npc:2663}. {npc:14508} stands about 800 yards south of {object:3202}, by the {area:1741}; {npc:261961} is in northern Stranglethorn. Customers show no quest mark: right-click them anyway."] = "{area:35}有三位顾客：“海狼”马金利（在旅店顶层）、在飞艇式传送平台的{npc:7853}，以及{npc:2663}。{npc:14508}站在{object:3202}以南约800码处，靠近{area:1741}；{npc:261961}在荆棘谷北部。顾客头上没有任务标记：照样右键点击他们。",
	["{area:35} holds three customers: \"Sea Wolf\" MacKinley (on the inn's top floor), {npc:7853}, the goblin transporter's engineer, and {npc:2663}. {npc:14508} stands at the {area:1741}, about 800 yards south of {object:3202}; {npc:261961} is in northern Stranglethorn. Customers show no quest mark: right-click them anyway."] = "{area:35}有三位顾客：“海狼”马金利（在旅店顶层）、地精传送器的工程师{npc:7853}，以及{npc:2663}。{npc:14508}站在{area:1741}，位于{object:3202}以南约800码处；{npc:261961}在荆棘谷北部。顾客头上没有任务标记：照样右键点击他们。",
	["{area:380} camp: the {quest:98248}"] = "{area:380} 营地：{quest:98248}",
