G["forever/reputation/timbermaw-hold"] = {
	["At Exalted, {npc:11555}, in the tunnel by {npc:11557}, gives {quest:8481}: plant his {item:21144} in the mouth of {npc:10738}'s cave and defeat the demon {npc:15623} (level 62, elite: bring a group). The reward is {item:21326}, a trinket that calls a Timbermaw ally, and 200 reputation."] = "崇拜后，隧道内 {npc:11557} 身边的 {npc:11555} 会给予 {quest:8481}：把他的 {item:21144} 插在 {npc:10738} 的洞口，击败恶魔 {npc:15623}（62 级精英：带上小队）。奖励为可召唤木喉盟友的饰品 {item:21326}，以及 200 点声望。",
	["Back to {npc:11554}"] = "回到{npc:11554}那里",
	["Back to {npc:11556}"] = "回到{npc:11556}那里",
	["Back to {npc:15395}"] = "回到{npc:15395}那里",
	["Chieftain Bloodmaw"] = "血牙酋长",
	["Deadwood Avenger"] = "死木复仇者",
	["Deadwood Den Watcher"] = "死木巢穴守望者",
	["Deadwood Gardener"] = "死木园丁",
	["Deadwood Headdress Feathers: keep them"] = "死木头饰羽毛：保留",
	["Deadwood Pathfinder"] = "死木探路者",
	["Deadwood Shaman"] = "死木萨满祭司",
	["Deadwood Warrior"] = "死木战士",
	["Friendly to Honored"] = "友善到尊敬",
	["Friendly to Honored is 6,000: 1,200 kills. Keep all feathers and beads. Honored opens at {npc:11557}: {item:19445} (3 gold), and for 2 gold 20 silver each Pattern: {item:19043} and {item:19044} ({skill:165}) and {item:19047} ({skill:197})."] = "友善到尊敬是6,000点：1,200次击杀。所有羽毛和念珠都留着。尊敬后可在{npc:11557}处购买：{item:19445}（3金），以及每张2金20银的图样：{item:19043}和{item:19044}（{skill:165}）以及{item:19047}（{skill:197}）。",
	["Friendly to Honored is 6,000: 1,200 kills. Keep all feathers and beads. Honored opens at {npc:11557}: {item:19445} (3 gold), and for 2 gold 20 silver each {item:19202} and {item:19044} ({skill:165}) and {item:19047} ({skill:197})."] = "友善到尊敬需要6,000声望：击杀1,200只。保留所有羽毛和珠串。尊敬后可向{npc:11557}购买：{item:19445}（3金币），以及每份2金20银的{item:19202}和{item:19044}（{skill:165}）、{item:19047}（{skill:197}）。",
	["Grizzle Snowpaw"] = "灰鬃雪爪",
	["High Chief Winterfall"] = "冬泉大酋长",
	["Honored to Revered"] = "尊敬到崇敬",
	["Honored to Revered is 12,000: 2,400 kills, the last ones that count. Kills stop at 11,999 of 12,000 Honored and never tip you into Revered: when they stop, hand in one set of 5 feathers or beads to cross over. Saving every feather and bead pays off now: about 4,800 kills from the start to the end of Honored leave you with about 2,100 feathers and beads, and that is all of Revered to Exalted. Turning them in early would cost you about 2,400 more kills."] = "从尊敬到崇敬需要12,000声望：2,400次击杀，这是最后能靠击杀获得的声望。到尊敬11,999/12,000时，击杀不再提供声望，无法靠它升到崇敬：此时交一组5根羽毛或5颗珠子跨过上限。之前保留的所有羽毛和珠子现在派上用场：从起点刷到尊敬上限，约4,800次击杀会留下约2,100个羽毛和珠子，足以覆盖崇敬到崇拜的全部需求。提前交还会让你多刷约2,400只怪。",
	["Kills stopped at the end of Honored. Revered to Exalted is 21,000: 420 turn-ins, 2,100 feathers and beads. Hand in the feathers to {npc:15395} at the tunnel or {npc:11554} in the south, the beads to {npc:11556}, five at a time. The named furbolgs (Ror, Bloodmaw, {npc:14342}, {npc:10199}, {npc:10738}) still count. Revered opens at {npc:11557}, for 4 gold each: Pattern: {item:19048} and {item:19049} ({skill:165}) and {item:19050} ({skill:197})."] = "击杀在尊敬结束处停止。崇敬到崇拜是21,000点：420次上交，2,100根羽毛和念珠。羽毛交给隧道里的{npc:15395}或南边的{npc:11554}，念珠交给{npc:11556}，每次五个。那些有名有姓的熊怪（罗尔、血牙、{npc:14342}、{npc:10199}、{npc:10738}）仍然计数。崇敬后可在{npc:11557}处购买，每张4金：图样{item:19048}和{item:19049}（{skill:165}）以及{item:19050}（{skill:197}）。",
	["Kills stopped at the end of Honored. Revered to Exalted is 21,000: 420 turn-ins, 2,100 feathers and beads. Hand in the feathers to {npc:15395} at the tunnel or {npc:11554} in the south, the beads to {npc:11556}, five at a time. The named furbolgs (Ror, Bloodmaw, {npc:14342}, {npc:10199}, {npc:10738}) still count. Revered opens at {npc:11557}, for 4 gold each: {item:19204} and {item:19049} ({skill:165}) and {item:19050} ({skill:197})."] = "尊敬满后，击杀普通怪不再奖励声望。崇敬到崇拜需要21,000声望：交还420次，共2,100个羽毛和珠串。羽毛交给隧道旁的{npc:15395}或南面的{npc:11554}，珠串交给{npc:11556}，每次五个。具名熊怪（主宰洛尔、血喉酋长、{npc:14342}、{npc:10199}、{npc:10738}）仍会奖励声望。崇敬后可向{npc:11557}以每份4金币购买：{item:19204}和{item:19049}（{skill:165}）、{item:19050}（{skill:197}）。",
	["Neutral to Friendly"] = "中立到友善",
	["Neutral to Friendly is 3,000: 600 kills. Keep all feathers and beads."] = "中立到友善需要3,000：击杀600只。保留所有羽毛和珠串。",
	["Overlord Ror"] = "罗尔霸主",
	["Ragepaw"] = "怒爪",
	["Recipes for Leatherworkers, Tailors, Enchanters and Alchemists from Friendly to Revered"] = "友善到崇敬期间可获得制皮、裁缝、附魔和炼金术配方",
	["Reputation · World"] = "声望 · 世界",
	["Revered to Exalted"] = "崇敬到崇拜",
	["Safe passage through the tunnels, agility enchants and furbolg recipes; the trinket at Exalted."] = "安全穿过隧道，获得敏捷附魔和熊怪配方；崇拜时可获得饰品。",
	["Tailors with skill 290: {npc:11557} takes 2 {item:14342} once for 100 reputation and teaches the {item:15802}."] = "技能290的裁缝：{npc:11557} 会一次性收取2块 {item:14342}，奖励100声望，并教授 {item:15802}。",
	["The Deadwood furbolgs (level 48-50) hold the village at the south end of {zone:1448}. Keep every {item:21377}: they are worth 10 reputation each later and never stop counting. {npc:9464} (15 reputation) and the rare {npc:14342} (25) live here and count until Exalted. In Classic, quests 6 or more levels below you pay less and grey mobs give about a fifth: at level 60 {quest:8460} paid 30 instead of 150 and these furbolgs about 1 a kill. Do it while leveling if you can."] = "死木熊怪（48-50级）占据{zone:1448}南端的村庄。每根{item:21377}都留着：之后每根值10点声望，而且永远不会停止计数。{npc:9464}（15点声望）和稀有的{npc:14342}（25点）住在这里，且计数直到崇拜。经典旧世中，比你低6级或更多的任务收益会减少，灰名怪物只给约五分之一：60级时{quest:8460}只给30点而非150点，这些熊怪每只约1点。可以的话边升级边做。",
	["The Winterfall furbolgs rarely drop a {quest:8471} (3-4%). {npc:11558} takes it in the tunnel too: 150 reputation and three Major Healing and Mana Potions."] = "冬泉熊怪有小概率掉落 {quest:8471}（3-4%）。隧道里的 {npc:11558} 也会收取它：奖励 150 点声望，以及特效治疗药水和法力药水各三瓶。",
	["The northern Deadwood (level 53-55) camp just south of the tunnel. They drop feathers about half the time: the best feather spot. {npc:9462} gives 15 until Exalted."] = "北部的死木熊怪（53—55级）就在隧道南边不远处扎营。羽毛掉率约为一半：这是刷羽毛最好的地点。击杀 {npc:9462} 奖励15点，直到崇拜。",
	["The northern Deadwood rarely drop a {quest:8470} (about 3%). From Neutral, {npc:11558} takes it in the tunnel, on the {zone:1448} side: 150 reputation and two Major Healing and Mana Potions."] = "北部的死木熊怪有较低概率掉落 {quest:8470}（约 3%）。从中立起，可交给隧道中 {zone:1448} 一侧的 {npc:11558}：奖励 150 点声望，以及特效治疗药水和特效法力药水各两瓶。",
	["These quests and their kills bring you just past Unfriendly (500 from the start). If {quest:8460} paid you less (at level 60 in Classic: 30), kill about 40 more northern Deadwood. From Unfriendly the Timbermaw in the tunnel leave you alone."] = "这些任务及沿途击杀会让你刚刚进入冷淡（从初始声望起增加 500 点）。如果 {quest:8460} 给你的奖励较少（经典怀旧服中，60 级为 30 点），就再杀约 40 只北部死木熊怪。到冷淡后，隧道内的木喉熊怪就不会主动攻击你。",
	["Timbermaw Hold Reputation"] = "木喉要塞声望",
	["Unfriendly to Neutral"] = "冷淡到中立",
	["Unfriendly to Neutral is 3,000: about 540 more kills after these quests. Three camps: the northern Deadwood by the {zone:1448} mouth of the tunnel; the Winterfall camps around {area:2246} and {area:2243}, just south and south-east of {npc:11556} (Pathfinders give 6 a kill, Den Watchers and Totemics 5, the shortest walk to a turn-in); and {area:2244} in the east. Pick the least crowded. Keep all feathers and beads."] = "冷淡到中立需要3,000：完成这些任务后还需击杀约540只。有三处营地：北部死木熊怪营地，靠近隧道的{zone:1448}一端；{area:2246}和{area:2243}周围的冬泉营地，就在{npc:11556}南方及东南方不远处（探路者每只6点，巢穴守卫和图腾师每只5点，离交还点最近）；以及东部的{area:2244}。选人最少的。保留所有羽毛和珠串。",
	["Walk through the tunnel to its {zone:1452} mouth; {npc:11556} stands just outside. Do not attack any Timbermaw: each one costs 25 reputation."] = "穿过隧道来到 {zone:1452} 一侧的出口；{npc:11556} 就站在洞外。不要攻击任何木喉熊怪：每杀一只会损失25点声望。",
	["Winterfall Den Watcher"] = "冬泉巢穴守望者",
	["Winterfall Pathfinder"] = "冬泉探路者",
	["Winterfall Pathfinders, {area:2246}"] = "冬泉探路者，{area:2246}",
	["Winterfall Shaman"] = "冬泉萨满祭司",
	["Winterfall Ursa"] = "冬泉巨熊",
	["Xandivious"] = "赞迪维斯",
	["{area:2244} lies in the east of {zone:1452}, just past {area:2255}. Keep every {item:21383} you loot (10 reputation each later). The Shamans, Den Watchers and Ursas share their spawn points, so kill every furbolg in the village to make the ones you need appear; more Ursas walk the ridge just south-west of the village. {npc:10199} (rare) and {npc:10738}, in the cave at the back, give 25 until Exalted. Alliance: the Wintersaber Trainers' Winterfall Intrusion asks for the same Shamans and Ursas."] = "{area:2244} 位于 {zone:1452} 东部，刚过 {area:2255} 就到。保留所有拾取到的 {item:21383}（之后每个值10声望）。萨满祭司、冬泉巢穴守卫 和 冬泉巨熊怪 共用刷新点，因此要击杀村内所有熊怪，让需要的种类刷出来；村庄西南面不远的山脊上还有更多 冬泉巨熊怪。{npc:10199}（稀有）和后方洞穴内的 {npc:10738} 各给25声望，直到崇拜。联盟：冬刃豹训练师的“冬泉熊怪的侵扰”也要求击杀这些萨满祭司和 冬泉巨熊怪。",
	["{area:2244}, the cave at the back. Clear the furbolgs around the mouth first, plant the torch, kill {npc:15623} and loot the Essence from his Demon Bag."] = "{area:2244}，后方的洞穴。先清掉洞口周围的熊怪，再插下火把，杀死 {npc:15623}，从他的恶魔之包里拾取精华。",
	["{faction:576} starts at Hostile (2,500 of 3,000), so its furbolgs attack you in their tunnels; {npc:11554}, {npc:15395} and {npc:11556} talk to everyone. {npc:11554} waits by the road in the south of {zone:1448}, near the {area:2479}. Every Deadwood and Winterfall furbolg you kill gives 5 reputation up to the last point of Honored, so the quests below pay twice. The Legacy perk Diplomat adds up to 10% to every gain."] = "{faction:576} 的初始声望为敌对（3,000 点中的 2,500 点），因此隧道里的熊怪会攻击你；{npc:11554}、{npc:15395} 和 {npc:11556} 则愿意与所有人交谈。{npc:11554} 在 {zone:1448} 南部、{area:2479} 附近的路旁等候。每杀一只死木或冬泉熊怪可获得 5 点声望，直到尊敬的最后一点，因此下面的任务既有任务声望，也有击杀声望。传承天赋“外交家”使每次获取量最多额外提高 10%。",
	["{item:19445} ({skill:333}), 3 gold"] = "{item:19445}（{skill:333}），3 金",
	["{item:21383}: keep them"] = "{item:21383}：保留它们",
	["{npc:10199}, rare"] = "{npc:10199}，稀有",
	["{npc:10738}, elite"] = "{npc:10738}，精英",
	["{npc:11557} stands in the tunnel, near its {zone:1448} mouth. From Friendly he sells: {item:13484} (1 gold 50 silver), {item:22392} (2 gold 50 silver), {item:20253} (1 gold 60 silver) and {item:15065} (2 gold). He also takes 30 {quest:6031} once for 100 reputation and a choice of shoulders or gauntlets, and Tailors with skill 290 can bring him 2 {item:14342} for 100 more and the {item:15802} pattern."] = "{npc:11557} 站在隧道里，靠近 {zone:1448} 一侧的出口。从友善起，他会出售：{item:13484}（1金币50银币）、{item:22392}（2金币50银币）、{item:20253}（1金币60银币）和 {item:15065}（2金币）。他还会一次性收取30份 {quest:6031}，奖励100点声望，并可选择肩甲或护手；技能290的裁缝还能带给他2块 {item:14342}，再获得100点声望及 {item:15802} 图样。",
	["{npc:14342}, rare"] = "{npc:14342}，稀有",
	["{npc:15395} stands at the {zone:1448} mouth of the Timbermaw tunnel, at the top of the road in the north of {zone:1448}."] = "{npc:15395} 站在木喉隧道的 {zone:1448} 一侧入口，位于 {zone:1448} 北部道路的顶端。",
	["{npc:15623}, 25 reputation"] = "{npc:15623}，25声望",
	["{quest:6031} drops from the humanoids of the level 50-60 zones, the Deadwood and Winterfall furbolgs among them."] = "{quest:6031} 由 50-60 级地区的人型生物掉落，包括死木熊怪和冬泉熊怪。",
	["{quest:6031} for {npc:11557}"] = "{quest:6031}，交给 {npc:11557}",
	["{quest:6031}: 30 {quest:6031}"] = "{quest:6031}：30个{quest:6031}",
	["{quest:8466}, {quest:8467} and {quest:8469} are open now: 50 reputation for 5 feathers or 5 beads, as often as you like. Do not hand them in yet."] = "现在已可接受 {quest:8466}、{quest:8467} 和 {quest:8469}：每 5 根羽毛或 5 颗珠串换取 50 点声望，可以无限重复。先不要交还。",
	["{quest:8466}: 5 feathers, 50 reputation"] = "{quest:8466}：5根羽毛，50声望",
	["{quest:8467}: 5 feathers, 50 reputation"] = "{quest:8467}：5根羽毛，50声望",
	["{quest:8467}: once your kills stop, 5 feathers into Revered"] = "{quest:8467}：击杀不再涨声望后，交 5 根羽毛进入崇敬",
	["{quest:8469}: 5 beads, 50 reputation"] = "{quest:8469}：5 颗珠串，50 点声望。",
	["{quest:8469}: or 5 beads"] = "{quest:8469}：或5串珠串",
}

G["forever/reputation/warsong-gulch"] = {
	["Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: {item:19578} (plate), {item:19582} (mail), {item:19587} (leather) and {item:19595} (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Outrider's legs in plate, chain, mail, leather, lizardhide and silk (16g57s to 25g33s). The {item:19505} is 5g."] = "崇拜后可获得传承点数“战歌峡谷主宰”，并解锁史诗装备：适用于 40、50 和 60 级的 {item:19578}（板甲）、{item:19582}（锁甲）、{item:19587}（皮甲）和 {item:19595}（布甲）（2 金 47 银至 12 金 11 银），以及 60 级的侦察骑兵护腿，分为板甲、链甲、锁甲、皮甲、蜥蜴皮和丝质（16 金 57 银至 25 金 33 银）。{item:19505} 售价 5 金。",
	["Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: {item:19578} (plate), {item:19582} (mail), {item:19587} (leather) and {item:19595} (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Sentinel's legs in plate, lamellar, chain, leather, lizardhide and silk (16g63s to 24g22s). The {item:19506} is 5g."] = "崇拜可获得传承点数“战歌峡谷主宰”，并解锁史诗装备：40、50和60级的{item:19578}（板甲）、{item:19582}（锁甲）、{item:19587}（皮甲）和{item:19595}（布甲）（2金47银到12金11银），以及60级哨兵腿甲，分为板甲、层叠板甲、链甲、皮甲、蜥蜴皮和丝质款式（16金63银到24金22银）。{item:19506}售价5金币。",
	["Flag captures and Marks of Honor raise it; Exalted gives a Legacy Point and epic bracers and legs."] = "夺旗和荣誉奖章可提升声望；崇拜可获得1点传承点数以及史诗护腕和腿甲。",
	["Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at {npc:14753} beside {npc:14733}: the {item:21567} and {item:21565} trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). She also gives one Sentinel care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages."] = "友善到尊敬需要6000声望，按经典版速率约赢39场。友善时，{npc:14733}旁的{npc:14753}开放首批奖励：饰品{item:21567}和{item:21565}（20级版2金币，40级版4金币），以及战场内可用的食物、绷带和饮剂（5银到20银）。友善时她还会给一个哨兵补给包（选适合自身等级的）：奖励10声望，以及一袋战场食物和绷带。",
	["Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at {npc:14754} beside {npc:14781}: the {item:21567} and {item:21565} trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). He also gives one Outrider care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages."] = "友善到尊敬需要 6000 点声望，按经典怀旧服的获取速度约需获胜 39 次。友善后可在 {npc:14781} 身边的 {npc:14754} 处购买首批奖励：饰品 {item:21567} 和 {item:21565}（20 级 2 金币，40 级 4 金币），以及战场内可用的食物、绷带和药剂（5 至 20 银币）。友善时，他还会给予一份战歌侍从补给包（选适合自己等级的）：奖励 10 点声望，以及一袋战场食物和绷带。",
	["Honored to Revered is 12000 reputation, about 78 wins. Honored opens the {item:19526}, {item:19534} (neck), {item:19518} and {item:19510}, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 9g6s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s)."] = "从尊敬到崇敬需要12000点声望，约78次胜利。尊敬可解锁 {item:19526}、{item:19534}（项链）、{item:19518} 和 {item:19510}，每种均有18、28、38、48及58级版本出售（披风36银币50铜币至9金币6银币，其余2金币至7金币50银币），以及特效治疗和法力药膏（10银币）。",
	["Honored to Revered is 12000 reputation, about 78 wins. Honored opens the {item:19530} (cloak), {item:19538} (neck), {item:19522} and {item:19514}, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 8g55s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s)."] = "从尊敬到崇敬需要12000声望，大约78场胜利。尊敬后可购买 {item:19530}（披风）、{item:19538}（项链）、{item:19522} 和 {item:19514}，每件都有18、28、38、48和58级版本（披风36银50铜至8金币55银币，其余2金币至7金币50银币），以及特效治疗药膏和特效法力药膏（10银币）。",
	["Master of Warsong Gulch: a Legacy Point at Exalted"] = "战歌峡谷大师：崇拜时获得1点传承点数",
	["Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Brigadier General: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, {npc:14733}'s one-mark quest and the Brigadier General's {quest:8372} come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks."] = "中立到友善需要3000声望。经典旧世中，以夺旗3次获胜奖励105，其3枚奖章在准将处还能换50：每胜约155，因此约需20胜。即使失败，小队每夺取一面旗帜仍奖励35。无限未公布战场声望倍率，因此场次数量仅供粗略参考。50级以下，{npc:14733}的单枚奖章任务和准将的{quest:8372}会提供对应等级段版本（分别从20级和10级起）：一次性200，之后每3枚奖章分别奖励100和50。",
	["Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Warbringer: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, {npc:14781}'s one-mark quest and the Warbringer's {quest:8368} come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks."] = "从中立到友善需要3000点声望。经典版中，夺旗3次获胜可得105点，3枚奖章交给战争使者还能获得50点：每次胜利约155点，因此约需20胜。失败时，己方每次成功夺旗仍可获得35点。无限服尚未公布战场声望倍率，因此场次只能作为粗略参考。50级以下时，{npc:14781} 的单枚奖章任务和战争使者的 {quest:8368} 会提供适合你等级段的版本（分别从20级和10级开始）：首次200点，之后每3枚奖章首次100点、后续每次50点。",
	["Reputation · Battlegrounds"] = "声望 · 战场",
	["Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: {item:19542} (dagger), {item:19550}, {item:19558} and {item:19566} (91s to 35g9s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Outrider Wolf mount (level 25, 10g) with no standing listed."] = "崇敬到崇拜需要21000声望，约136场胜利：占整个提升过程的一半。崇敬后解锁18至58级武器：{item:19542}（匕首）、{item:19550}、{item:19558}和{item:19566}（91银至35金9银）。无限的军需官还出售这4种武器的25级版本、20级头部装备（坚韧的布质头带、坚韧的皮甲面具或坚韧的锁甲头盔，各2金50银）及 新手的护卫之狼 坐骑（25级，10金币），未列出声望等级要求。",
	["Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: {item:19546} (dagger), {item:19554}, {item:19562} and {item:19570} (91s to 35g61s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Sentinel Nightsaber mount (level 25, 10g) with no standing listed."] = "崇敬到崇拜需要21000声望，约赢136场：占整个过程的一半。崇敬时开放18到58级的武器：{item:19546}（匕首）、{item:19554}、{item:19562}和{item:19570}（91银到35金61银）。无限服军需官还出售这四种武器的25级版本、20级头部装备（坚韧的布质头带、坚韧的皮甲面具或坚韧的锁甲头盔，各2金50银），以及新手的哨兵夜刃豹坐骑（25级，10金币），未列出声望要求。",
	["The {npc:15350} pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more ({quest:8368}). One stands right here at Mor'shan; others in {zone:1454}, {zone:1456} (and on the plain below it) and the {zone:1458}, at {area:321} in the {zone:1417} and at the {zone:1459} gate in the {zone:1416}. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 {zone:1460} marks: hand in or spend them before you reach that."] = "向{npc:15350}首次交还3枚战歌峡谷荣誉奖章可获100声望，之后每3枚奖励50声望（{quest:8368}）。莫尔杉这里就有一位；其他位于{zone:1454}、{zone:1456}（及其下方平原）、{zone:1458}、{zone:1417}的{area:321}，以及{zone:1416}的{zone:1459}大门旁。无限服PvP装备除荣誉外也消耗荣誉奖章：交还前先决定要买什么。{zone:1460}奖章最多携带30枚：达到上限前及时交还或花掉。",
	["The {npc:15351} pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more ({quest:8372}). One stands right here at {area:3319} beside {npc:14733}; others in {zone:1453}, {zone:1455} and {zone:1457}, at {area:320} in the {zone:1417} and at both gates of {zone:1459}. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 {zone:1460} marks: hand in or spend them before you reach that."] = "{npc:15351} 首次接受 3 枚战歌峡谷荣誉奖章时，会提供 100 点声望，之后每 3 枚提供 50 点（{quest:8372}）。这里 {area:3319} 的 {npc:14733} 旁就有一位；其他人在 {zone:1453}、{zone:1455} 和 {zone:1457}，以及 {zone:1417} 的 {area:320} 和 {zone:1459} 两侧大门处。无限的 PvP 装备除了荣誉外也需要荣誉奖章：交还前先决定想换什么。你最多只能携带 30 枚 {zone:1460} 奖章：达到上限前就要交还或花掉。",
	["Warsong Gulch Reputation"] = "战歌峡谷声望",
	["one {item:20558}: play a game"] = "一枚 {item:20558}：打一场战场。",
	["three Warsong Gulch Marks of Honor"] = "三枚战歌峡谷荣誉奖章",
	["{faction:889} to Exalted"] = "{faction:889}刷到崇拜",
	["{faction:889} to Friendly"] = "{faction:889}刷到友善",
	["{faction:889} to Honored"] = "{faction:889}刷到尊敬",
	["{faction:889} to Revered"] = "{faction:889}刷到崇敬",
	["{faction:890} to Exalted"] = "{faction:890}刷到崇拜",
	["{faction:890} to Friendly"] = "{faction:890}刷到友善",
	["{faction:890} to Honored"] = "{faction:890}刷到尊敬",
	["{faction:890} to Revered"] = "{faction:890}刷到崇敬",
	["{item:19505}, 5g"] = "{item:19505}，5金币",
	["{item:19506}, 5g"] = "{item:19506}，5金币",
	["{npc:14753}: Friendly rewards"] = "{npc:14753}：友善奖励",
	["{npc:14753}: Honored rewards"] = "{npc:14753}：尊敬奖励",
	["{npc:14753}: Revered rewards"] = "{npc:14753}：崇敬奖励",
	["{npc:14754}: Friendly rewards"] = "{npc:14754}：友善奖励",
	["{npc:14754}: Honored rewards"] = "{npc:14754}：尊敬奖励",
	["{npc:14754}: Revered rewards"] = "{npc:14754}：崇敬奖励",
	["{npc:15350}: 50 reputation for 3 marks"] = "{npc:15350}：3枚徽章换50声望",
	["{npc:15350}: {quest:8368} again, 50 reputation for 3 marks"] = "{npc:15350}：再次交还 {quest:8368}，3 枚奖章换 50 点声望",
	["{npc:15351}: 50 reputation for 3 marks"] = "{npc:15351}：3枚徽章换50声望",
	["{npc:15351}: {quest:8372} again, 50 reputation for 3 marks"] = "{npc:15351}：再次交还 {quest:8372}，3 枚奖章换 50 点声望",
	["{zone:1460} is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen. In Classic every flag your team captures pays everyone 35 reputation (45 on the {zone:1460} holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. {npc:14733} pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide."] = "{zone:1460} 是 10 对 10 的夺旗战场，10 级起可参加。在主城任意战场军官处，或从战场界面排队。经典怀旧服中，队伍每夺得一面旗，所有队员都获得 35 点声望（{zone:1460} 战场节日周末为 45 点）；每场获胜奖励 3 枚战歌峡谷荣誉奖章，失败奖励 1 枚。{npc:14733} 会收取一枚奖章，奖励 200 点声望，每个角色仅一次：这是你能交出的最划算的一枚奖章。无限的传承天赋“外交家”使本指南的每项数值最多额外提高 10%。",
	["{zone:1460} is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen; the Horde gate is here at {area:1599}. In Classic every flag your team captures pays everyone 35 reputation (45 on the {zone:1460} holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. {npc:14781} pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide."] = "{zone:1460} 是 10 对 10 的夺旗战场，10 级起即可参加。可向主城内任意战场军官报名，或从战场界面排队；部落入口就在这里的 {area:1599}。经典旧世中，己方每夺取一面旗帜，全队每人获得 35 点声望（{zone:1460} 节日周末为 45 点），每场胜利奖励 3 枚战歌峡谷荣誉奖章，失败奖励 1 枚。{npc:14781} 每个角色可用一枚奖章一次性换取 200 点声望：这是最划算的一次交还。无限的传承天赋“外交家” 特权可让本指南中每个数值最多提高 10%。",
}

G["forever/reputation/zandalar-tribe"] = {
	["100"] = "100",
	["200"] = "200",
	["25 and a token"] = "25 点声望和一枚奖券",
	["At Exalted your necklace takes its last upgrade, Rin'wosho sells {item:20013} (5g), and Rin'wosho trades 15 Zandalar Honor Tokens for one Signet of the Zandalar, the shoulder enchant: Might (attack power), Mojo (spell damage) or Serenity (healing)."] = "崇拜后，你的项链可进行最后一次升级，林沃斯会出售 {item:20013}（5 金），还可用 15 枚赞达拉荣誉勋章向林沃斯兑换一个赞达拉徽记，即肩部附魔：力量（攻击强度）、魔精（法术伤害）或宁静（治疗）。",
	["At Friendly your class's trainer on the isle gives a necklace for free (100 reputation); the same NPC upgrades it at Honored, Revered and Exalted (100 each) with no raid item needed. Friendly also opens Rin'wosho's first recipes ({item:19766}, {item:19687}, {item:19778}, {item:19695}, {item:20001}, {item:20012}, 5g each; {item:20757}, 4g) and the Paragons of Power bracers (150 for the Primal Hakkari bracer token of your class)."] = "友善后，岛上对应你职业的训练师会免费给一条项链（100声望）；同一NPC会在尊敬、崇敬和崇拜时升级项链（每次100声望），无需团队副本物品。友善还会解锁商人林沃斯的首批配方（{item:19766}、{item:19687}、{item:19778}、{item:19695}、{item:20001}、{item:20012}，各5金币；{item:20757}，4金币），以及权力珍宝护腕（提交本职业的原始哈卡莱护腕兑换物，奖励150声望）。",
	["Destroy one bijou at the {object:180367}, the stone altar on the west side of {area:3357} (right-click the bijou there), then tell {npc:15070}: 150 reputation and an extra {item:19858}, once. From then on every bijou you destroy at the altar pays 75 reputation and a token, and every set of three coins {npc:15070} takes pays 25 and a token. They never stop counting."] = "在{object:180367}摧毁一颗宝石，那是{area:3357}西侧的石祭坛（在那里右键点击宝石），然后告诉{npc:15070}：一次性奖励150声望和一个额外的{item:19858}。此后每在祭坛摧毁一颗宝石，都奖励75声望和一枚奖章；{npc:15070}每收取一组三枚硬币，则奖励25声望和一枚奖章。这些奖励永远有效。",
	["Exalted: the {quest:8246}"] = "崇拜：{quest:8246}",
	["Friendly to Honored is 6,000: one and a half clears. Honored opens {item:19683}, {item:19686}, {item:19689}, {item:19691}, {item:19694} and {item:20004} (5g each), {item:20000} (12g), {item:20756} (4g) and {spell:471400} (4g), the Paragons of Power belts and mantles (150 each), {quest:8196} (one Honor Token) and The {item:22635}."] = "友善到尊敬需要 6,000 点声望：约通关一次半。尊敬后解锁 {item:19683}、{item:19686}、{item:19689}、{item:19691}、{item:19694} 和 {item:20004}（各 5 金币）、{item:20000}（12 金币）、{item:20756}（4 金币）及 {spell:471400}（4 金币），以及权力珍宝腰带和衬肩（各 150）、{quest:8196}（一枚赞达拉荣誉勋章）和 {item:22635}。",
	["Friendly to Honored is 6,000: one and a half clears. Honored opens {item:19683}, {item:19686}, {item:19689}, {item:19691}, {item:19694} and {spell:24361} (5g each), {item:20000} (12g), {item:20756} (4g) and {spell:471400} (4g), the Paragons of Power belts and mantles (150 each), {quest:8196} (one Honor Token) and The {item:22635}."] = "友善到尊敬是6,000点：一趟半副本。尊敬会开放{item:19683}、{item:19686}、{item:19689}、{item:19691}、{item:19694}和{spell:24361}（每张5金）、{item:20000}（12金）、{item:20756}（4金）和{spell:471400}（4金），以及力量典范腰带和披肩（各150点）、{quest:8196}（一枚荣誉徽章）和{item:22635}。",
	["Friendly: your class necklace"] = "友善：你的职业项链",
	["Honored to Revered is 12,000: about three clears. Two one-time quests help: {quest:8201} ({npc:14910} on the isle: 200 for five Channeler's Heads from the High Priests, strung on his {item:19883}) and {quest:8183} (one per kill, for whoever loots it; {npc:14875} on the isle pays 200 and a Zandalarian Hero badge, charm or medallion). Revered opens {item:19682}, {item:19685}, {item:19688}, {item:19690}, {item:19693} and {item:20007} (5g each), the Paragons of Power chests and mantles (150) and {quest:8243}."] = "尊敬到崇敬需要 12,000 点声望：约通关三次。两个一次性任务有助于提升：{quest:8201}（岛上的 {npc:14910}：用他的 {item:19883} 串起高阶祭司掉落的五个导魔师的头颅，奖励 200）和 {quest:8183}（每次击杀只掉一个，由拾取者获得；岛上的 {npc:14875} 奖励 200，以及赞达拉英雄徽记、护符或勋章之一）。崇敬后解锁 {item:19682}、{item:19685}、{item:19688}、{item:19690}、{item:19693} 和 {item:20007}（各 5 金币）、权力珍宝胸甲和衬肩（150）以及 {quest:8243}。",
	["Honored to Revered is 12,000: about three clears. Two one-time quests help: {quest:8201} ({npc:14910} on the isle: 200 for five Channeler's Heads from the High Priests, strung on his {item:19883}) and {quest:8183} (one per kill, for whoever loots it; {npc:14875} on the isle pays 200 and a Zandalarian Hero badge, charm or medallion). Revered opens {item:19682}, {item:19685}, {item:19688}, {item:19690}, {item:19693} and {spell:24365} (5g each), the Paragons of Power chests and mantles (150) and {quest:8243}."] = "尊敬到崇敬是12,000点：约三趟副本。两个一次性任务能帮上忙：{quest:8201}（岛上的{npc:14910}：用五位高阶祭司的五个引导者之头，串在他的{item:19883}上，给200点）和{quest:8183}（每次击杀一个，谁拾取归谁；岛上的{npc:14875}给200点和一个赞达拉英雄徽章、护符或奖章）。崇敬会开放{item:19682}、{item:19685}、{item:19688}、{item:19690}、{item:19693}和{spell:24365}（每张5金）、力量典范胸甲和披肩（150点）以及{quest:8243}。",
	["Honored: necklace, {item:22635} and mangoes"] = "尊敬：项链、{item:22635} 和芒果",
	["Reputation · Raids and dungeons"] = "声望 · 团队副本与地下城",
	["Revered: necklace, coins and bijous"] = "崇敬：项链、硬币与宝石",
	["Shoulder and head enchants, a class necklace upgraded at every standing, and {area:19}'s set pieces."] = "肩部和头部附魔、每个声望等级都会升级的职业项链，以及{area:19}的套装部件。",
	["Trash stopped counting at 11,999 Honored. Revered to Exalted is 21,000: bosses give about 1,350 a clear, and now the saved coins and bijous pay: 75 per bijou (280 bijous alone), 25 per coin set. Coins and bijous are tradeable, so the auction house is the only solo way. Each Paragons piece pays 150, each {npc:15042} enchant 100, each {item:22635} 200. Rin'wosho trades one of {npc:15042}'s potables (Spirit, Sheen or {item:20081}) for an Honor Token."] = "普通怪到尊敬11,999点就不再奖励声望。从崇敬到崇拜需要21,000点：首领每次全通约奖励1,350点，现在就可以交还攒下的硬币和宝石：每颗宝石75点（只交宝石需280颗），每套硬币25点。硬币和宝石都能交易，因此拍卖行是唯一的单人途径。权力珍宝每个部件奖励150点，每次 {npc:15042} 附魔100点，每个 {item:22635} 200点。在商人林沃斯处可用一枚荣誉勋章兑换 {npc:15042} 的一种药剂（精神、光泽或 {item:20081}）。",
	["Your class's necklace at Friendly, upgraded at Honored, Revered and Exalted"] = "友善时获得本职业项链，尊敬、崇敬和崇拜时升级",
	["Zandalar Tribe Reputation"] = "赞达拉部族声望",
	["your class's {item:19813}"] = "你所属职业的 {item:19813}。",
	["{area:19} is the troll city in the north-east of {zone:1434}: a 20-player raid. Trash pays 3 to 5 each until 11,999 of 12,000 Honored, one point short of Revered; the Speakers 15, Ohgan 15, the {area:3398} boss 25, {npc:15114} and the five High Priests 100, {npc:11382} and Jin'do 200 and Hakkar 400, all the way to Exalted. A full clear is about 4,050: one clear reaches Friendly (3,000). Loot every coin, bijou, {item:22637}, {item:19881} and Primal Hakkari set piece. Coins and bijous pay the same at any standing: save them until the trash stops counting, except one bijou for {quest:8240}."] = "{area:19}是{zone:1434}东北部的巨魔城市：20人团队副本。小怪每只奖励3到5点声望，直到尊敬11,999/12,000、距崇敬还差一点；发言者15、奥根15、{area:3398}首领25、{npc:15114}和五名高阶祭司各100、{npc:11382}和金度各200、哈卡400，这些一直奖励到崇拜。全通一次约4,050：通一次即可到友善（3,000）。拾取所有硬币、宝石、{item:22637}、{item:19881}和原始哈卡莱套装兑换部件。硬币和宝石在任何声望阶段奖励相同：除了{quest:8240}所需的一颗宝石外，都留到小怪不再奖励声望时再用。",
	["{area:19} to Friendly"] = "{area:19}到友善",
	["{area:19} to Honored"] = "{area:19}至尊敬",
	["{area:19} to Revered"] = "在 {area:19} 提升至崇敬。",
	["{area:3357} is the small island off the north-west coast of {zone:1434}, west of the {area:122}: swim over from the coast. Everyone starts Neutral with the {faction:270}. {npc:15070} takes coins and bijous, {npc:14921} sells the recipes and trades Honor Tokens, and {npc:14902}, {npc:14903}, {npc:14904} and {npc:14905} hand out the class necklaces and the set pieces. Almost all Zandalar reputation comes from {area:19}, a 20-player raid, and {area:19} is not among the first raids Blizzard has announced for Forever: until it opens there is no Zandalar reputation to earn, and no coins or bijous on the auction house either. Once it is open, the only solo way is buying coins and bijous on the auction house (75 per bijou, 25 per set of three coins). The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it."] = "{area:3357} 是 {zone:1434} 西北海岸外、{area:122} 西侧的小岛：从岸边游过去。所有角色与 {faction:270} 的初始关系都是中立。{npc:15070} 收取硬币和宝石，{npc:14921} 出售配方并兑换荣誉勋章，{npc:14902}、{npc:14903}、{npc:14904} 和 {npc:14905} 提供职业项链和套装部件。几乎所有赞达拉声望都来自20人团队副本 {area:19}，而 {area:19} 不在暴雪已公布的无限服首批团队副本中：开放之前无法获取赞达拉声望，拍卖行也不会有硬币或宝石。开放后，独自获取的唯一方式是从拍卖行购买硬币和宝石（每颗宝石75声望，每组三枚硬币25声望）。传承特权外交家会使每次声望获取最多提高10%；本指南的数值未计入该加成。",
	["{item:19707}; any of the nine colours does"] = "{item:19707}；九种颜色中的任意一种都可以。",
	["{item:22637}, Jin'do or Mandokir"] = "{item:22637}，金度或曼多基尔",
