G["forever/class/rogue/ravenholdt"] = {
	["{npc:6766}: one emblem each time, 100 reputation"] = "{npc:6766}：每次一枚徽记，100声望",
	["{npc:6766}: {quest:6701}, repeatable; take it now, the emblems are quest items"] = "{npc:6766}：{quest:6701}，可重复；现在就接上，徽记是任务物品",
}

G["forever/collectibles/pets/lil-timmy"] = {
	["Horde players buy the {npc:7386} (60s) from {npc:262471}, a trader new in Forever, at {area:2539}, the Darkspear camp at the southern tip of {zone:1442}, on the way up from the {zone:1413}. He keeps one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "部落玩家从{npc:262471}处购买{npc:7386}（60银）。他是无限新增的商人，位于{area:2539}，即{zone:1442}南端的暗矛营地，从{zone:1413}上来的路上。他一次只养一只小猫：如果他没有，就是刚被人买走了。每件宠物物品在使用时都会教会对应的伙伴；之后该目标仍保持打勾。",
}

G["forever/reputation/argent-dawn"] = {
	["The Plaguelands quests pay in full at 60 from level 55 up and never stop counting, about 1,500 in all; the leveling guides walk them. The cauldron chain from {npc:11053} at {area:3197} (Horde: {npc:11055} at the {area:152}): 150 per cauldron with its return, then Mission Accomplished! 200. Alas, Andorhal 150 ({npc:1852}, elite). At {area:2268}, {npc:11063}'s {area:2262} quests (Brother Carlin 50 from Chromie in Andorhal, Villains of Darrowshire 100, Marauders of Darrowshire 100) and {npc:10926}'s Hidden Treasures 200 at the end of the {area:2262} story; {npc:12250} 75 from {npc:11038}. After Mission Accomplished!, each cauldron takes a repeatable delivery: 25 reputation every time, until Exalted. {npc:11056} at {area:3197} (Horde: {npc:11057} at the {area:152}) gives you a {item:13370}, without which the reagents never drop, and sells Arcane Quickeners for 50 silver (one per delivery; it crumbles after 30 minutes, so buy it last). Each delivery also takes 4 {item:14047}. Farm {area:201}: its ghosts drop an {item:13354} about one time in four, so about 16 kills fill a delivery; the other cauldrons want 5 or 6 reagents that drop one time in ten or less. Once the Plaguelands Scourge stop counting, this earns about four times what their Scourgestones alone do."] = "瘟疫之地的任务在60级时从55级起就全额给，且永远算数，总共约1,500；升级指南会带你做。{area:3197}的{npc:11053}（部落：{area:152}的{npc:11055}）的瘟疫锅系列：每口瘟疫锅连同回程给150，然后是“任务完成！”给200。接着是“唉，安多哈尔”150（{npc:1852}，精英）。在{area:2268}，{npc:11063}的{area:2262}任务（卡林兄弟50，来自安多哈尔的克罗米；达尔隆郡的恶棍100；达尔隆郡的掠夺者100）和{npc:10926}在{area:2262}故事末尾的“隐藏的宝藏”200；{npc:12250}给75，来自{npc:11038}。完成“任务完成！”后，每口瘟疫锅可重复交付：每次25声望，直到崇拜。{area:3197}的{npc:11056}（部落：{area:152}的{npc:11057}）会给你一个{item:13370}，没有它材料永远不会掉落；他还以50银出售奥术催化剂（每次交付一个；30分钟后碎裂，所以最后再买）。每次交付还需4个{item:14047}。刷{area:201}：其中的鬼魂约四分之一几率掉{item:13354}，所以约16杀够一次交付；其他瘟疫锅需要5或6种材料，掉落率十分之一或更低。一旦瘟疫之地的天灾停止计数，这比单交它们的天灾石多赚约四倍。",
}

G["forever/reputation/cenarion-circle"] = {
	["The {faction:609}'s other quests are spread over {zone:1414} and the Plaguelands. Forever pays them in full at any level: The Wildlife Suffers Too ({npc:10739}, {zone:1422}, levels 54 and 56) 75 and 75, Corruption of Earth and Seed ({area:2100}, level 51) 150. Shards of the Felvine ({quest:1123}, level 60, the {item:18501} from Alzzin in {area:2577}) pays 150 and its Reliquary 100 at any level."] = "{faction:609}的其他任务分布在{zone:1414}和瘟疫之地。无限在任何等级都全额支付：《野生动物也受苦》（{npc:10739}，{zone:1422}，54和56级）给75和75，《大地与种子的腐化》（{area:2100}，51级）给150。《魔藤碎片》（{quest:1123}，60级，{area:2577}中阿尔津掉的{item:18501}）在任何等级都给150，其后续的圣物匣任务给100。",
}

G["forever/reputation/centaur-clans"] = {
	["The Gelkis (south-west {zone:1443}) and the Magram (south-east) are at war: every kill of one clan gives the other 20 and costs its own clan 100, so you can only climb with one. Both start Neutral. Forever's quests are worth far more than kills now, and the choice quests no longer cost the other clan anything. Alliance: {npc:5396} at {area:608} offers {quest:1382} (Gelkis) and {quest:1385} (Magram). Horde: {npc:5412}, east of Shadowprey, offers {quest:1368} and {quest:1367}. Take the one of your clan and its Buying Friendship (3,000 for carrying a tote of totems), then tick the task. The guide goes on with the Gelkis; take the Magram's quests instead and it jumps to the Magram half. Forever pays these quests in full at any level."] = "吉尔吉斯（{zone:1443}西南）与玛格拉姆（东南）正在交战：每杀一个部族成员，另一部族加20，自己部族减100，所以你只能靠一个部族爬声望。两者初始都是中立。如今无限的任务价值远高于击杀，而且选择任务不再让另一部族受损。联盟：{area:608}的{npc:5396}提供{quest:1382}（吉尔吉斯）和{quest:1385}（玛格拉姆）。部落：葬影村以东的{npc:5412}提供{quest:1368}和{quest:1367}。接你部族的那一个及其“购买友谊”（带着一箱图腾去，得3,000），然后勾选该任务。攻略继续按吉尔吉斯走；若改接玛格拉姆的任务，它会跳到玛格拉姆那一半。无限在任何等级都全额支付这些任务。",
}

G["forever/reputation/merchants-favor"] = {
	["Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, the one its title names. Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for."] = "工匠令状就是营地声望：中级令状75点，高级令状125点，大师级令状200点。每份都要求一件制成品，就是令状标题写明的那件。自己制作或在拍卖行购买；不需要学会该专业。每份令状每天可完成一次，不同令状数量不限。只接你已经拥有物品、或顺路会买到的令状任务（右键点击令状），把令状留在包里，然后勾选此项：后续步骤会带你去见每一位你持有令状的顾客。",
	["bring it: engineers make it; {npc:789} in {area:69} lists it (not yet seen in her window up to level 30), or the Auction House"] = "带上它：工程学能做；{area:69}的{npc:789}有上架（30级前还没在她店里见过），或者去拍卖行",
	["bring it: leatherworkers make it, or buy it at the Auction House"] = "带上它：制皮师能做，或者在拍卖行购买",
}

G["forever/reputation/nightclaw-druids"] = {
	["{npc:252359} stands in {area:16638}, the Skyborne town in the south of the isle, and has heard nothing from the druids up north. His errand is the start of the Nightclaw storyline (level 8 and up, any race). Every quest of it pays Nightclaw reputation: 4100 in all, enough for Friendly. Players' turn-ins paid their full reputation well above these quests' level."] = "{npc:252359}站在{area:16638}，即岛南部的天裔城镇；他一直没有北方德鲁伊的消息。他的差事是夜爪任务线的开端（8级及以上，任何种族）。这条线的每个任务都给夜爪声望：总共4100，足够到友善。玩家实测上交时，即便等级远高于这些任务，也拿到了全额声望。",
}

G["forever/reputation/steamwheedle-cartel"] = {
	["Five goblin towns share one reputation family, the Steamwheedle Cartel: {faction:470}, {faction:21}, {faction:369}, {faction:577} and Forever's new {faction:2827} in the {zone:2548}. Everyone starts each at Neutral (500 into it). A gain with one town gives the others half as much; a quest for the Cartel itself, like {npc:14637}'s, pays every town in full. Losses spread the same way: a {npc:4624} or any goblin of the towns costs 125 (half that with the other towns), and Bloodsail Buccaneers reputation is earned only that way. {npc:14637} camps on the road through central {zone:1444} and works for anyone, even players the goblins hate. His first two quests are level 48 and open his repeatables (level 55); Forever pays all of them in full at any level."] = "五座地精城镇共享同一个声望阵营——热砂港财团：{faction:470}、{faction:21}、{faction:369}、{faction:577}，以及无限在{zone:2548}新增的{faction:2827}。每个人每座城镇都从中立开始（已有500点进度）。在一座城镇获得的声望，会将其余城镇各分到一半；而像{npc:14637}这样直接为财团做的任务，则全额计入每座城镇。损失也照此分摊：一个{npc:4624}或这些城镇的任何地精会损失125点（其余城镇减半），血帆海盗的声望只能靠这种方式获得。{npc:14637}在穿越{zone:1444}中部的路旁扎营，为任何人工作，甚至包括地精们憎恨的玩家。他头两个任务是48级，会开启他的可重复任务（55级）；无限在任何等级都全额支付这些任务。",
	["Neutral 500 to Friendly is 2,500 with each town. The quests above pay every town up to 700 ({npc:14637}'s two 300, {npc:10267}'s 150, the first Free Knot 150 and the first Ogre Suit 100); {npc:14637}'s repeatables do the rest, 25 to every town each: 10 residue (ten giants) or 6 cores (about twelve elementals). The towns' own quests count too, each giving the other towns half: {faction:470}'s in the {zone:1413} (levels 10-25, about 4,300: the Samophlange chain 625, {npc:3446}'s errands, the Wizzlecrank and Gilthares escorts 150 each), {faction:21}'s in Stranglethorn, Arathi and the {zone:1418} (30-50, about 6,500: the three OOX robot rescues 250 each, An OOX of Your Own 200, Stranglethorn Fever 200, Facing Negolash 200, the Sunken Treasure chain at {area:327}), {faction:369}'s in {zone:1446} (43-55, about 3,000: the {item:8548} 200, Wastewander Justice 100 each, the WANTED posters) and {faction:577}'s in {zone:1452} (52-60, about 1,450: {npc:9298}'s Winterfall chain, Umi's yeti quests). Forever adds a few low ones: A Simmering Storm and Stormy Potential in {zone:1411} and WANTED: Bruuz ({faction:470} 100 each), Important Heirlooms in {zone:1455} ({faction:369} 100). Forever pays them in full at any level. Kills help while they are not grey, 5 each: Southsea pirates in the {zone:1413} for {faction:470} and in {zone:1446} for {faction:369} and Stranglethorn's Venture Co. camps for {faction:21}, up to the end of Honored; Wastewander bandits for {faction:369} and Bloodsail pirates for {faction:21} only up to the end of Neutral. Friendly opens each quartermaster's first gear."] = "中立500点到友善需要每座城镇2,500点。上述任务每座城镇最多给700点（{npc:14637}的两个任务各300，{npc:10267}的150，第一次“解救诺特”150，第一次食人魔套装100）；其余靠{npc:14637}的可重复任务，每次每座城镇25点：10个残渣（十个巨人）或6个核心（约十二个元素生物）。各城镇自己的任务也算，且给其余城镇一半：{faction:470}在{zone:1413}的任务（10-25级，约4,300点：采样器任务链625，{npc:3446}的跑腿任务，维兹克兰克和吉尔萨雷斯护送各150），{faction:21}在荆棘谷、阿拉希和{zone:1418}的任务（30-50级，约6,500点：三次OOX机器人救援各250，《你自己的OOX》200，《荆棘谷热》200，《直面内格拉什》200，以及{area:327}的沉没的宝藏任务链），{faction:369}在{zone:1446}的任务（43-55级，约3,000点：{item:8548} 200，《废土正义》每个100，通缉告示）以及{faction:577}在{zone:1452}的任务（52-60级，约1,450点：{npc:9298}的冬泉任务链、乌米的雪人任务）。无限还加了几个低级任务：{zone:1411}的《酝酿的风暴》和《风暴潜能》，以及《通缉：布鲁兹》（{faction:470}各100）；{zone:1455}的《重要传家宝》（{faction:369} 100）。无限在任何等级都全额支付这些任务。击杀在怪物尚未变灰时有用，每只5点：{zone:1413}的南海海盗给{faction:470}、{zone:1446}的南海海盗给{faction:369}，以及荆棘谷的风险投资公司营地给{faction:21}，直到尊敬结束；废土强盗给{faction:369}、血帆海盗给{faction:21}，只到中立结束。友善会开放各军需官的第一批装备。",
}

G["forever/reputation/thorium-brotherhood"] = {
	["{area:1446} is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. Forever pays them in full at any level. {npc:14624}'s {quest:7722} also opens his {item:18942} turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%."] = "{area:1446}是火山口西北缘搭着脚手架的营地，设有飞行点。所有人一开始与兄弟会都是中立。这七个任务（48到50级）各给100点声望：共700点，加上下面提到的枕头为800点。无限在任何等级都全额支付这些任务。{npc:14624}的{quest:7722}还会开启他的{item:18942}上交，所以任何等级都需要做它。本篇攻略的数字未计入传承特长“外交家”，它最多加10%。",
}

G["forever/reputation/timbermaw-hold"] = {
	["The Deadwood furbolgs (level 48-50) hold the village at the south end of {zone:1448}. Keep every {item:21377}: they are worth 10 reputation each later and never stop counting. {npc:9464} (15 reputation) and the rare {npc:14342} (25) live here and count until Exalted. Forever pays quests in full at any level; in Classic grey mobs gave about a fifth, about 1 a kill for these furbolgs at 60. Do it while leveling if you can."] = "死木熊怪（48-50级）占据{zone:1448}南端的村庄。每根{item:21377}都留着：之后每根值10点声望，而且永远不会停止计数。{npc:9464}（15点声望）和稀有的{npc:14342}（25点）住在这里，且计数直到崇拜。无限在任何等级都全额支付任务；经典旧世中灰名怪物只给约五分之一，60级时这些熊怪每只约1点。可以的话边升级边做。",
}
